INSERT INTO `recipes` VALUES (2,'Paneer Tikka Masala',30,'Bước 1: Cắt phô mai paneer, ớt chuông và hành tây thành miếng vuông vừa ăn.\nBước 2: Trộn phô mai với hỗn hợp sốt sữa chua tẩm ướp cay nồng.\nBước 3: Xiên que và nướng trong lò hoặc chảo nướng cho đến khi các cạnh xém vàng.\nBước 4: Dọn kèm sốt bạc hà xanh mát và hành tây ngâm chanh.','NorthIndian',1,'Phô mai Paneer nướng gia vị thơm lừng, món ăn chay hoàng gia Bắc Ấn.','Tẩm ướp phô mai và rau củ -> Xiên que nướng vàng thơm -> Ăn kèm sốt bạc hà','recipe_1790865416_221.jpg','https://www.youtube.com/watch?v=xW5pP0O_9E0',2,'2026-09-22 22:59:13'),(3,'Crispy Masala Dosa',40,'Bước 1: Ngâm gạo và đậu urad dal, xay mịn và lên men qua đêm để bột nở chua nhẹ.\nBước 2: Làm nhân khoai tây xào mù tạt vàng, lá cà ri, nghệ và hành tây giòn ngọt.\nBước 3: Tráng bột thật mỏng trên chảo gang nóng có thoa bơ ghee cho đến khi bánh giòn tan.\nBước 4: Cho nhân khoai tây vào giữa, cuộn lại và thưởng thức nóng hổi cùng tương dừa (coconut chutney) và súp sambar.','SouthIndian',2,'Tựa như một bản giao hưởng giòn rụm kiêu hãnh của ẩm thực Nam Ấn, Crispy Masala Dosa là kiệt tác bánh crepe truyền thống nổi tiếng với vỏ bánh siêu mỏng, giòn tan vàng ươm ôm trọn lấy lớp nhân khoai tây đậm đà nồng nàn.','Tráng bột giòn trên chảo bơ ghee -> Thêm nhân khoai tây -> Cuộn tròn ăn kèm súp sambar','recipe_1790869870_746.jpg','https://www.youtube.com/watch?v=CCab5uqazCA',3,'2026-09-22 22:59:13'),(5,'Kung Pao Chicken (Gà Cung Bảo)',25,'Bước 1: Thịt ức gà cắt hạt lựu, ướp với xì dầu, rượu hoa tiêu và tinh bột bắp.\nBước 2: Pha nước sốt Kung Pao: nước tương, giấm đen, đường, dầu mè và chút ớt bột.\nBước 3: Đun nóng dầu ăn, phi thơm ớt khô và tiêu Tứ Xuyên cho dậy mùi thơm cay nồng.\nBước 4: Cho thịt gà vào xào săn trên lửa lớn, thêm hành paro, ớt chuông và nước sốt.\nBước 5: Cuối cùng cho đậu phộng rang giòn đảo đều rồi tắt bếp.','Chinese',3,'Món gà xào chua ngọt cay nồng Tứ Xuyên kết hợp cùng đậu phộng giòn rụm.','Ướp gà -> Phi thơm tiêu Tứ Xuyên và ớt -> Xào lửa lớn cùng sốt -> Trộn đậu phộng rang','recipe_1790865358_244.jpg','https://www.youtube.com/watch?v=nZ4B_s0q_4E',2,'2026-09-22 22:59:13'),(6,'Steamed Shrimp Shumai (Xíu Mại Tôm)',30,'Bước 1: Tôm bóc vỏ băm nhuyễn một nửa, một nửa cắt khúc để giữ độ giòn.\nBước 2: Trộn tôm với thịt heo xay, nấm hương, dầu hào, tiêu trắng và dầu mè thơm lừng.\nBước 3: Gói nhân vào lá hoành thánh mỏng, vuốt mép tạo hình phễu xíu mại truyền thống.\nBước 4: Đặt vào xửng tre hấp cách thủy trong 8-10 phút đến khi vỏ mờ trong và nhân chín mọng.','Chinese',3,'Tựa như một viên ngọc quý ẩn mình trong làn khói nghi ngút của xửng hấp tre, Steamed Shrimp Shumai (Xíu Mại Tôm) là biểu tượng thanh tao và kiêu kỳ của nghệ thuật ẩm thực Dimsum Quảng Đông.','Trộn nhân tôm thịt nấm hương -> Gói lá hoành thánh -> Hấp trong xửng tre 10 phút','recipe_1790870754_572.jpg','https://www.youtube.com/watch?v=2r1pQ20Wz70',3,'2026-09-22 22:59:13'),(8,'Creamy Mango Kulfi',20,'Bước 1: Đun sữa tươi nguyên kem và sữa đặc trên lửa nhỏ, khuấy đều cho cô đặc lại còn một nửa.\nBước 2: Xay nhuyễn thịt xoài cát chín mọng ngọt thơm.\nBước 3: Trộn xoài xay cùng hỗn hợp sữa đã để nguội, thêm bột bạch đậu khấu và hạt dẻ cười đập vụn.\nBước 4: Rót vào khuôn làm kem que hoặc ly gốm truyền thống và để đông lạnh 6-8 tiếng.','Dessert',4,'Kem xoài truyền thống Ấn Độ sánh mịn, thơm lừng hương thảo mộc và hạt dẻ.','Đun cô đặc sữa tươi -> Trộn xoài xay và bạch đậu khấu -> Đổ khuôn cấp đông qua đêm','recipe_1790865264_887.jpg','https://www.youtube.com/watch?v=T_7xQJ3_mK0',2,'2026-09-22 22:59:13'),(9,'Refreshing Mango Lassi',10,'Bước 1: Cho thịt xoài chín tươi (hoặc xoài xay đông lạnh) vào máy xay sinh tố.\nBước 2: Thêm sữa chua Hy Lạp không đường, một ít sữa tươi, đường hoặc mật ong tùy khẩu vị.\nBước 3: Cho thêm một nhúm bột thảo quả (cardamom) và vài viên đá lạnh.\nBước 4: Xay ở tốc độ cao trong 1-2 phút cho đến khi hỗn hợp nhuyễn mịn, sủi bọt kem hấp dẫn.\nBước 5: Rót ra ly, rắc thêm vài sợi nghệ tây và hạnh nhân thái lát lên trên.','Drinks',5,'Tựa như một điệu múa nhiệt đới đầy sức sống từ Ấn Độ, Refreshing Mango Lassi là sự giao hòa tuyệt diệu giữa vị ngọt đậm đà của xoài chín rực rỡ và nét chua dịu thanh mát từ sữa chua truyền thống.','Cho xoài, sữa chua, sữa tươi và đá vào cối -> Xay mịn nhuyễn -> Trang trí hạt hạnh nhân','recipe_1790870554_623.jpg','https://www.youtube.com/watch?v=5Qj4O_tW_yM',3,'2026-09-22 22:59:13'),(11,'Phở Bò Tái Lăn Hà Nội',60,'Bước 1: Xương bò rửa sạch, chần trong nước sôi khoảng 5 phút rồi rửa lại. Gừng và hành tây nướng cho thơm. Thịt bò thái lát thật mỏng ngang thớ và để lạnh cho đến khi chế biến.\nBước 2: Cho xương bò vào nồi cùng khoảng 3–3,5 lít nước. Đun sôi rồi hạ lửa nhỏ, thường xuyên hớt bọt để nước trong. Ninh khoảng 3–4 giờ.\nBước 3: Cho gừng nướng, hành tây nướng, quế và hoa hồi đã rang sơ vào nồi nước dùng trong khoảng 30–45 phút cuối. Không nên cho gia vị thơm quá sớm vì có thể làm nước dùng bị nồng.\nBước 4: Làm nóng chảo thật mạnh, cho một ít dầu và thịt bò thái mỏng vào đảo nhanh. Thịt chỉ cần vừa tái, bên ngoài săn lại nhưng bên trong vẫn mềm. Có thể thêm một chút hành tây thái mỏng khi tái lăn.\nBước 5: Bánh phở tươi trụng nhanh qua nước sôi rồi cho vào tô. Xếp phần thịt bò tái lăn lên trên.\nBước 6: Lọc nước dùng, nêm muối, nước mắm và một lượng nhỏ đường cho cân bằng. Chan nước dùng thật nóng vào tô phở, thêm hành lá, hành tây thái mỏng và rau thơm. Dùng ngay khi còn nóng.','Vietnamese',6,'Phở bò tái lăn Hà Nội nổi bật với nước dùng trong, thơm mùi quế hồi và vị ngọt tự nhiên từ xương bò. Phần thịt bò được tái lăn nhanh trên chảo nóng trước khi cho vào tô, giúp thịt thơm, mềm và đậm vị hơn.','Sơ chế & nướng gia vị → Ninh xương → Nấu nước dùng → Tái lăn thịt bò & trụng phở → Chan nước dùng & thưởng thức','https://images.unsplash.com/photo-1582878826629-29b7ad1cdc43?w=800','https://www.youtube.com/results?search_query=Ph%E1%BB%9F+B%C3%B2+T%C3%A1i+L%C4%83n+H%C3%A0+N%E1%BB%99i',4,'2026-09-23 00:15:02'),(12,'Bún Chả Hà Nội Nướng Than Hoa',45,'Bước 1: Thịt ba chỉ thái lát mỏng. Thịt nạc vai xay trộn với hành tím, nước mắm, đường, tiêu và một ít dầu. Ướp cả hai loại thịt khoảng 45 phút để thấm gia vị.\nBước 2: Thịt ba chỉ để làm chả miếng. Phần thịt xay vo thành những viên nhỏ, hơi dẹt để dễ nướng và chín đều.\nBước 3: Đốt than đến khi than đỏ và nhiệt ổn định. Xếp chả miếng và chả viên lên vỉ, nướng và trở đều nhiều lần đến khi thịt chín vàng, có cạnh xém nhẹ và thơm mùi than.\nBước 4: Pha nước mắm với nước ấm, đường và giấm hoặc chanh. Thêm đu đủ xanh và cà rốt thái mỏng đã ngâm nước muối loãng, cùng tỏi ớt băm. Nước chấm cần có vị mặn, ngọt, chua cân bằng.\nBước 5: Cho chả đã nướng vào bát nước chấm còn ấm. Dùng cùng bún tươi và rau sống. Khi ăn, gắp bún và rau chấm hoặc nhúng vào phần nước mắm cùng chả để thưởng thức.','Vietnamese',6,'Bún chả Hà Nội là món ăn đặc trưng của thủ đô với chả viên, chả miếng được nướng trên than hoa cho thơm và hơi xém cạnh. Chả được dùng cùng bún tươi, rau sống và bát nước mắm pha chua ngọt có đu đủ, cà rốt.','Ướp thịt → Làm chả → Nướng than hoa → Pha nước chấm → Bày món & thưởng thức','recipe_1790857731_220.webp','https://www.youtube.com/results?search_query=B%C3%BAn+Ch%E1%BA%A3+H%C3%A0+N%E1%BB%99i+N%C6%B0%E1%BB%9Bng+Than+Hoa',5,'2026-09-23 00:15:02'),(14,'Bánh Mì Kẹp Thịt Xá Xíu & Pate',20,'Bước 1: Bước 1: Thịt xá xíu thái lát mỏng vừa ăn; dưa leo cắt dọc hoặc thái lát mỏng; đồ chua rửa sơ, để ráo nước.\nBước 2: Bước 2: Đem nướng hoặc hâm nóng lại bánh mì trên lò nướng/chảo để bánh đạt độ giòn rụm hoàn hảo, sau đó dùng dao rạch một đường dọc thân bánh.\nBước 3: Bước 3: Lần lượt quét một lớp mỏng bơ trứng gà và pate gan heo vào lòng bánh mì, tiếp theo xếp đều dưa leo, đồ chua và những lát thịt xá xíu vào bên trong.\nBước 4: Bước 4: Thêm chút rau ngò (rau mùi) lên trên để tăng hương vị, ép nhẹ bánh mì lại và thưởng thức ngay khi còn nóng giòn.','Vietnamese',6,'Bánh mì vỏ giòn rụm kết hợp cùng nhân pate gan béo ngậy, thịt xá xíu thơm mềm đậm vị, quyện cùng đồ chua, dưa leo và rau ngò tươi mát, rưới thêm chút sốt bơ béo ngậy cực kỳ hấp dẫn.','Sơ chế & chuẩn bị nguyên liệu -> Làm nóng bánh mì & quét sốt -> Kẹp nhân thịt xá xíu, pate -> Thưởng thức ngay','https://images.unsplash.com/photo-1509722747041-616f39b57569?w=800','https://www.youtube.com/results?search_query=B%C3%A1nh+M%C3%AC+K%E1%BA%B9p+Th%E1%BB%8Bt+X%C3%A1+X%C3%ADu+%26+Pate',7,'2026-09-23 00:15:02'),(15,'Cơm Tấm Sườn Bì Chả Sài Gòn',75,'Bước 1: 1. Nấu cơm tấm: Vo nhẹ gạo tấm rồi cho vào nồi cùng lượng nước phù hợp, nấu đến khi cơm chín mềm và tơi. Khi cơm chín, xới nhẹ để hạt cơm không bị vón.\nBước 2: 2. Sơ chế sườn: Sườn cốt lết rửa sạch, để ráo rồi dùng dụng cụ dần thịt hoặc cán nhẹ để sườn mềm và dễ thấm gia vị.\nBước 3: 3. Ướp sườn: Băm nhỏ tỏi và hành tím, trộn cùng nước mắm, dầu hào, đường, mật ong, tiêu và dầu ăn. Cho sườn vào ướp đều ít nhất 30 phút, tốt nhất khoảng 2 giờ để thịt đậm đà.\nBước 4: 4. Làm bì: Luộc da heo đến khi chín mềm nhưng vẫn giữ được độ dai, sau đó vớt ra ngâm nước lạnh và để ráo. Thái da thành sợi thật mỏng, trộn cùng thịt heo luộc thái sợi, thính gạo và một ít muối.\nBước 5: 5. Làm chả trứng: Ngâm miến và mộc nhĩ cho mềm rồi thái nhỏ. Trộn thịt heo xay với miến, mộc nhĩ, trứng, nước mắm và tiêu. Cho hỗn hợp vào khuôn và hấp khoảng 20–25 phút đến khi chả chín.\nBước 6: 6. Pha nước mắm: Hòa tan đường với nước lọc, thêm nước mắm và nước cốt chanh rồi khuấy đều. Cho tỏi và ớt băm vào, nêm lại để nước mắm có vị mặn ngọt chua hài hòa.\nBước 7: 7. Nướng sườn: Làm nóng bếp nướng hoặc lò ở khoảng 200°C. Cho sườn lên nướng, thường xuyên trở mặt và phết phần nước ướp còn lại cho đến khi sườn chín mềm, vàng xém cạnh và thơm.\nBước 8: 8. Chuẩn bị đồ ăn kèm: Dưa leo rửa sạch, thái lát. Chuẩn bị đồ chua và các loại rau ăn kèm.\nBước 9: 9. Trình bày: Cho cơm tấm vào đĩa, đặt sườn nướng, một phần bì và chả trứng bên cạnh. Thêm dưa leo, đồ chua và chan hoặc dùng kèm nước mắm.\nBước 10: 10. Thưởng thức: Dùng cơm tấm khi còn nóng cùng sườn nướng, bì, chả trứng và nước mắm chua ngọt để cảm nhận đầy đủ hương vị đặc trưng của món cơm tấm Sài Gòn.','Vietnamese',6,'Cơm tấm đặc trưng Sài Gòn với hạt cơm tấm mềm thơm, sườn heo nướng đậm đà, bì dai giòn và chả trứng béo thơm, ăn kèm đồ chua, dưa leo và nước mắm chua ngọt.','Nấu cơm tấm → Sơ chế sườn → Ướp sườn → Làm bì → Làm chả trứng → Pha nước mắm → Nướng sườn → Chuẩn bị đồ ăn kèm → Trình bày và thưởng thức.','recipe_1790951945_463.jpg','https://www.youtube.com/results?search_query=C%C6%A1m+T%E1%BA%A5m+S%C6%B0%E1%BB%9Dn+B%C3%AC+Ch%E1%BA%A3+S%C3%A0i+G%C3%B2n',8,'2026-09-23 00:15:02'),(17,'Bánh Xèo Miền Tây Giòn Rụm',40,'Bước 1: Khuấy đều hỗn hợp bột, bột nghệ, nước cốt dừa, nước lọc và hành lá; để bột nghỉ 15 phút.\nBước 2: Làm nóng chảo với chút dầu ăn, xào sơ tôm thịt rồi múc một muôi bột tráng đều thật mỏng quanh lòng chảo; rải giá đỗ lên trên và đậy nắp 2 phút.\nBước 3: Mở nắp, đun thêm 1–2 phút cho viền bánh róc và đáy vàng giòn, gập đôi bánh lại.\nBước 4: Bày ra đĩa, trang trí rau thơm và thưởng thức nóng cùng gia đình!','Vietnamese',6,'Bánh xèo vàng ươm bột nghệ và nước cốt dừa béo ngậy, nhân tôm thịt giá đỗ đầy đặn cuộn cùng rau rừng và nước mắm chua ngọt.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/33/6b/65/336b656f607efabfafc9cf8b0276cd53.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+X%C3%A8o+Mi%E1%BB%81n+T%C3%A2y+Gi%C3%B2n+R%E1%BB%A5m',10,'2026-09-23 00:15:02'),(18,'Bún Riêu Cua Đồng Mộc Mạc',50,'Bước 1: Hòa chút muối vào nước lọc cua, đun lửa vừa và khuấy nhẹ; khi riêu cua đóng tảng nổi lên mặt nước thì vớt nhẹ tay ra đĩa.\nBước 2: Phi thơm hành tím xào gạch cua cho thơm rồi trút cà chua vào xào sơ. Đổ tất cả vào nồi nước cua, thêm giấm bỗng và 1 thìa cà phê mắm tôm tạo vị chua thanh dịu.\nBước 3: Thả đậu hũ chiên vào đun sôi lăn tăn; chần bún ra bát, múc riêu cua, chan nước dùng ngập tô và thưởng thức cùng rau muống chẻ, hoa chuối, kinh giới','Vietnamese',6,'Gạch cua đồng béo ngậy đóng tảng thơm lừng, nước dùng chua thanh từ cà chua và giấm bỗng, ăn kèm đậu hũ chiên và rau muống chẻ.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/11/7e/ff/117effc5dff015296be29e52596fa11b.jpg','https://www.youtube.com/results?search_query=B%C3%BAn+Ri%C3%AAu+Cua+%C4%90%E1%BB%93ng+M%E1%BB%99c+M%E1%BA%A1c',11,'2026-09-23 00:15:02'),(20,'Thịt Kho Tàu Hột Vịt Nước Dừa',90,'Bước 1: Sơ chế thịt: Rửa sạch thịt ba chỉ, chần qua nước sôi rồi cắt thành miếng vuông vừa ăn.\nBước 2: Luộc trứng: Luộc trứng vịt khoảng 8–10 phút, bóc vỏ rồi để riêng.\nBước 3: Ướp thịt: Ướp thịt với nước mắm, đường, hành tím, tỏi, tiêu và muối khoảng 30 phút.\nBước 4: Thắng nước màu: Cho đường vào nồi, đun lửa nhỏ đến khi đường chuyển màu nâu cánh gián rồi thêm một ít nước.\nBước 5: Kho thịt: Cho thịt đã ướp vào nồi, đảo đều cho thịt săn và thấm màu.\nBước 6: Thêm nước dừa và trứng: Đổ nước dừa vào ngập thịt, đun sôi rồi hạ nhỏ lửa, cho trứng vịt vào và kho khoảng 45–60 phút.\nBước 7: Hoàn thiện và thưởng thức: Nêm lại cho vừa ăn, kho đến khi thịt mềm và nước kho sánh nhẹ rồi tắt bếp, dùng nóng với cơm trắng.','Vietnamese',6,'Thịt kho tàu hột vịt nước dừa với thịt ba chỉ mềm béo, trứng vịt bùi thơm, nước kho đậm đà và có vị ngọt tự nhiên từ nước dừa.','Sơ chế thịt → Luộc trứng → Ướp thịt → Thắng nước màu → Kho thịt → Thêm trứng và nước dừa → Hoàn thiện và thưởng thức.','recipe_1790873336_651.jpg','https://www.youtube.com/results?search_query=thịt+kho+tàu+hột+vịt+nước+dừa+recipe',13,'2026-09-23 00:15:03'),(21,'Canh Chua Cá Lóc Nam Bộ',30,'Bước 1: Cá lóc làm sạch, chà với muối để khử mùi rồi rửa lại. Cắt cá thành từng khúc vừa ăn. Thơm, cà chua, đậu bắp và bạc hà cắt miếng vừa ăn.\nBước 2: Me cho vào chén, dằm với nước ấm rồi lọc qua rây để lấy phần nước cốt. Có thể điều chỉnh lượng me tùy mức độ chua mong muốn.\nBước 3: Đun khoảng 1–1,2 lít nước, cho thơm và cà chua vào trước. Khi nước sôi, cho cá lóc vào nấu khoảng 7–10 phút. Hớt bọt để nước canh trong.\nBước 4: Cho nước cốt me vào nồi, khuấy nhẹ. Nêm đường, nước mắm và muối để tạo vị chua – ngọt – mặn cân bằng theo phong cách Nam Bộ.\nBước 5: Cho đậu bắp và bạc hà vào trước, nấu khoảng 2–3 phút. Cuối cùng cho giá đỗ vào để giá vẫn giữ được độ giòn.\nBước 6: Nêm lại lần cuối rồi tắt bếp. Có thể thêm rau ngò om, ngò gai và ớt cắt lát trước khi dùng. Canh ngon nhất khi ăn nóng cùng cơm trắng.','Vietnamese',6,'Canh chua cá lóc là món canh quen thuộc của miền Nam với vị chua thanh từ me, vị ngọt của cá và sự tươi mát của rau. Bạc hà, đậu bắp, giá và thơm tạo nên nhiều tầng hương vị và độ giòn đặc trưng.','Sơ chế cá & rau → Nấu cá → Tạo vị chua bằng me → Cho rau vào nấu → Nêm vị & thưởng thức','recipe_1790852202_277.webp','https://www.youtube.com/results?search_query=Canh+Chua+C%C3%A1+L%C3%B3c+Nam+B%E1%BB%99',4,'2026-09-23 00:15:03'),(22,'Bò Kho Sốt Vang Ăn Bánh Mì',75,'Bước 1: Thịt bò cắt khối vừa ăn, trộn với một ít muối, tiêu, tỏi băm và khoảng một phần rượu vang. Ướp khoảng 30 phút để thịt thấm gia vị.\nBước 2: Làm nóng nồi với dầu, cho thịt bò vào áp chảo từng phần đến khi các mặt săn vàng. Vớt thịt ra để riêng.\nBước 3: Phi hành tây, cho cà chua vào xào mềm. Thêm phần rượu vang còn lại, đun vài phút để mùi rượu nồng giảm bớt. Cho thịt bò trở lại nồi.\nBước 4: Thêm nước vừa đủ ngập thịt, đậy nắp và hầm ở lửa nhỏ khoảng 60–75 phút. Khi thịt bắt đầu mềm, cho cà rốt và khoai tây vào nấu tiếp đến khi rau củ chín.\nBước 5: Nêm lại muối, nước mắm, đường và tiêu để vị đậm đà. Nấu thêm vài phút để nước sốt hơi sánh. Múc bò kho ra tô và dùng nóng với bánh mì.','Vietnamese',6,'Bò kho sốt vang là món bò hầm đậm đà với thịt bò mềm, cà rốt và nước sốt có màu đỏ nâu hấp dẫn. Món được biến tấu theo phong cách Việt, thường dùng nóng cùng bánh mì để chấm phần sốt sánh thơm.','Ướp bò → Xào săn → Nấu sốt vang → Hầm mềm → Hoàn thiện & dùng bánh mì','recipe_1790857650_704.jpg','https://www.youtube.com/results?search_query=B%C3%B2+Kho+S%E1%BB%91t+Vang+%C4%82n+B%C3%A1nh+M%C3%AC',5,'2026-09-23 00:15:03'),(25,'Nem Rán Hà Nội Giòn Tan',45,'Bước 1: 1. Sơ chế nguyên liệu: Ngâm miến, mộc nhĩ và nấm hương trong nước ấm cho mềm. Sau đó vớt ra để ráo, miến cắt ngắn, mộc nhĩ và nấm hương băm nhỏ. Cà rốt, hành tây và hành lá rửa sạch rồi thái nhỏ.\nBước 2: 2. Trộn nhân nem: Cho thịt heo xay, miến, mộc nhĩ, nấm hương, cà rốt, hành tây, giá đỗ và hành lá vào tô. Thêm trứng gà, tiêu, hạt nêm và một ít muối rồi trộn đều cho các nguyên liệu hòa quyện.\nBước 3: 3. Cuốn nem: Trải bánh đa nem lên mặt phẳng, cho một lượng nhân vừa đủ vào gần mép bánh. Gấp hai mép bên vào trong rồi cuộn tròn, vừa cuộn vừa giữ nhẹ tay để nem chắc nhưng không quá chặt.\nBước 4: 4. Pha nước chấm: Hòa tan đường với nước ấm, thêm nước mắm và nước cốt chanh rồi khuấy đều. Cho tỏi và ớt băm vào, nêm lại để có vị chua, ngọt và mặn hài hòa.\nBước 5: 5. Làm nóng dầu: Cho dầu ăn vào chảo sâu lòng và đun ở lửa vừa. Lượng dầu nên đủ ngập khoảng 2/3 chiếc nem để nem chín vàng đều.\nBước 6: 6. Chiên nem lần một: Cho nem vào chảo khi dầu nóng, chiên ở lửa vừa đến khi lớp vỏ se lại và chuyển màu vàng nhạt. Vớt nem ra để trên giấy thấm dầu.\nBước 7: 7. Chiên nem lần hai: Tăng nhiệt độ dầu lên một chút rồi cho nem đã chiên sơ vào chiên lần hai đến khi vỏ nem vàng giòn và có màu đẹp mắt. Vớt ra để ráo dầu.\nBước 8: 8. Chuẩn bị món ăn: Xếp nem rán ra đĩa, chuẩn bị rau sống, rau thơm và nước chấm. Có thể thêm bún và đồ chua nếu muốn ăn theo kiểu truyền thống.\nBước 9: 9. Thưởng thức: Dùng nem rán khi còn nóng, cuốn cùng rau sống và rau thơm rồi chấm vào nước mắm chua ngọt để cảm nhận lớp vỏ giòn và phần nhân đậm đà.','Vietnamese',6,'Nem rán Hà Nội với lớp vỏ vàng giòn, nhân thịt heo băm kết hợp cùng miến, mộc nhĩ, nấm hương và rau củ. Nem được chiên vàng đều, ăn kèm rau sống và nước mắm chua ngọt.','Sơ chế nguyên liệu → Trộn nhân nem → Cuốn nem → Pha nước chấm → Chiên nem lần một → Chiên lần hai → Chuẩn bị rau → Thưởng thức.','recipe_1790950748_690.jpg','https://www.youtube.com/results?search_query=Nem+R%C3%A1n+H%C3%A0+N%E1%BB%99i+Gi%C3%B2n+Tan',8,'2026-09-23 00:15:03'),(26,'Gà Hấp Lá Chanh Thơm Lừng',40,'Bước 1: Gà làm sạch, xát với muối và một ít nước cốt chanh để khử mùi, sau đó rửa lại bằng nước sạch và để ráo\nBước 2: Sả đập dập, cắt khúc; lá chanh rửa sạch, một phần thái sợi; tỏi và hành tím bóc vỏ rồi băm nhỏ\nBước 3: Trộn tỏi, hành tím, nước mắm, hạt nêm, đường, tiêu và dầu ăn thành hỗn hợp gia vị, sau đó xoa đều lên toàn bộ con gà và để khoảng 20 phút cho thấm.\nBước 4: Xếp sả đập dập và một phần lá chanh dưới đáy xửng hấp, đặt gà lên trên rồi phủ thêm lá chanh thái sợi.\nBước 5: Đun sôi nước trong nồi hấp, đặt xửng gà vào và hấp ở lửa vừa khoảng 35–40 phút tùy kích thước gà.\nBước 6: Dùng đũa hoặc que xiên kiểm tra phần thịt dày nhất của gà, nếu nước chảy ra trong và thịt không còn màu hồng thì gà đã chín.\nBước 7: Tắt bếp, để gà nghỉ khoảng 5 phút rồi chặt thành miếng vừa ăn để thịt giữ được độ mọng.\nBước 8: Pha muối chấm bằng muối, tiêu, ớt băm và nước cốt chanh, có thể thêm một chút đường để vị hài hòa.\nBước 9: Xếp gà ra đĩa, rắc thêm lá chanh thái sợi, dùng nóng cùng muối tiêu chanh và thưởng thức.','Vietnamese',6,'Gà hấp chín mềm mọng, thơm đậm mùi lá chanh và sả, giữ được vị ngọt tự nhiên của thịt, ăn kèm muối tiêu chanh cay mặn vừa miệng.','Sơ chế gà → Ướp gia vị → Chuẩn bị lá chanh và sả → Xếp nguyên liệu → Hấp gà → Kiểm tra độ chín → Pha muối chấm → Chặt gà và thưởng thức.','recipe_1790954432_981.jpg','https://www.youtube.com/results?search_query=G%C3%A0+H%E1%BA%A5p+L%C3%A1+Chanh+Th%C6%A1m+L%E1%BB%ABng',9,'2026-09-23 00:15:03'),(28,'Sườn Non Xào Chua Ngọt Óng Ánh',35,'Bước 1: Chần sườn qua nước sôi, ướp chút hạt nêm rồi phủ lớp bột bắp mỏng, đem rán trên chảo dầu đến khi vàng đều các mặt rồi vớt ra.\nBước 2: Phi thơm tỏi băm, cho bát sốt chua ngọt vào chảo đun sôi lăn tăn đến khi sánh lại.\nBước 3: Đổ sườn rán cùng vào chảo sốt, xốc đều tay trên lửa lớn 2–3 phút cho lớp sốt sánh đặc óng ả bao đều từng miếng sườn.\nBước 4: Bày ra đĩa và ăn ngay khi còn nóng!','Vietnamese',6,'Sườn non rán vàng xốc đều với sốt cà chua, giấm thơm, đường và ớt chuông tạo lớp sốt sánh đặc óng ả bắt mắt.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/34/e1/e7/34e1e7b1e8db1fa45dd8e2fb6c46d9f7.jpg','https://www.youtube.com/results?search_query=S%C6%B0%E1%BB%9Dn+Non+X%C3%A0o+Chua+Ng%E1%BB%8Dt+%C3%93ng+%C3%81nh',11,'2026-09-23 00:15:03'),(31,'Bánh Bèo Chén Xứ Huế',40,'Bước 1: Trộn bột gạo và bột năng với khoảng 500 ml nước, khuấy thật đều rồi để bột nghỉ khoảng 30 phút. Sau đó khuấy lại trước khi hấp.\nBước 2: Làm nóng các chén nhỏ trong xửng hấp. Quét một lớp dầu mỏng, sau đó đổ bột vào từng chén với độ dày vừa phải. Hấp khoảng 5–7 phút đến khi bánh chuyển trong và bề mặt đông lại.\nBước 3: Tôm luộc chín, bóc vỏ rồi giã hoặc xay nhỏ. Cho tôm vào chảo rang trên lửa nhỏ cùng một ít dầu và gia vị đến khi tôm khô, tơi và có màu vàng cam.\nBước 4: Da heo luộc chín, để thật ráo rồi cắt nhỏ. Chiên trên lửa vừa đến khi vàng giòn, sau đó vớt ra để ráo dầu.\nBước 5: Pha nước mắm với đường và nước ấm theo tỷ lệ vừa khẩu vị, thêm một ít ớt nếu thích. Nước mắm bánh bèo thường có vị mặn ngọt hài hòa và không quá đặc.\nBước 6: Rắc tôm cháy, tóp mỡ và hành phi lên từng chén bánh. Chan một ít nước mắm trực tiếp lên bánh hoặc dùng riêng để chấm.','Vietnamese',6,'Bánh bèo chén Huế là món ăn dân dã đặc trưng của cố đô, gồm lớp bánh bột gạo mềm dai vừa phải, bên trên là tôm cháy, hành phi và tóp mỡ. Bánh thường được dùng cùng nước mắm ngọt pha loãng, tạo nên hương vị đậm đà nhưng thanh nhẹ.','Pha bột → Hấp bánh → Làm tôm cháy & tóp mỡ → Pha nước mắm → Rắc nhân & thưởng thức','recipe_1790852129_749.jpeg','https://www.youtube.com/results?search_query=B%C3%A1nh+B%C3%A8o+Ch%C3%A9n+X%E1%BB%A9+Hu%E1%BA%BF',4,'2026-09-23 00:15:03'),(32,'Bánh Bột Lọc Tôm Thịt Gói Lá Chuối',45,'Bước 1: Tôm bóc vỏ, băm nhỏ. Thịt ba chỉ thái hạt lựu. Phi thơm hành, cho thịt vào xào săn rồi thêm tôm, nước mắm, đường và tiêu. Xào đến khi nhân khô ráo và đậm vị.\nBước 2: Cho bột năng vào tô, từ từ thêm nước nóng và khuấy đều. Nhào khi bột còn ấm đến khi tạo thành khối bột mềm, dẻo và không dính tay.\nBước 3: Chia bột thành các viên nhỏ, cán mỏng. Cho một lượng nhân vừa đủ vào giữa rồi gấp mép bột lại, ép kín phần viền.\nBước 4: Lá chuối rửa sạch, trụng nhanh qua nước nóng để mềm. Đặt bánh vào giữa lá, gói kín và xếp vào xửng hấp.\nBước 5: Hấp bánh khoảng 15–20 phút đến khi vỏ bánh chuyển trong và dai. Bóc lớp lá chuối, dùng bánh nóng cùng nước mắm chua ngọt.','Vietnamese',6,'Bánh bột lọc gói lá chuối là món bánh truyền thống với lớp vỏ bột trong, dai mềm, bao quanh nhân tôm thịt đậm đà. Bánh được gói trong lá chuối rồi hấp chín, tạo mùi thơm nhẹ đặc trưng.','Làm nhân → Nhào bột → Tạo bánh → Gói lá chuối → Hấp & thưởng thức','recipe_1790857506_545.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+B%E1%BB%99t+L%E1%BB%8Dc+T%C3%B4m+Th%E1%BB%8Bt+G%C3%B3i+L%C3%A1+Chu%E1%BB%91i',5,'2026-09-23 00:15:03'),(35,'Gà Nướng Muối Ớt Da Giòn',50,'Bước 1: 1. Sơ chế gà: Gà làm sạch, dùng muối và chanh chà xát toàn thân để khử mùi, sau đó rửa lại bằng nước sạch và để thật ráo. Dùng dao khứa nhẹ vài đường trên phần thịt dày để gia vị dễ thấm.\nBước 2: 2. Chuẩn bị hỗn hợp muối ớt: Sả, tỏi và ớt băm nhỏ. Trộn cùng muối hạt, đường, tiêu, bột ngọt, bột ớt, nước mắm và dầu ăn để tạo thành hỗn hợp gia vị.\nBước 3: 3. Ướp gà: Xoa đều hỗn hợp muối ớt lên toàn bộ con gà, đặc biệt là phần thịt. Hạn chế phết quá nhiều gia vị lên da để da có thể khô và giòn khi nướng. Ướp ít nhất 30 phút, tốt nhất 2–3 giờ trong tủ lạnh.\nBước 4: 4. Làm nóng lò: Làm nóng lò nướng ở nhiệt độ khoảng 200°C trong 10 phút trước khi cho gà vào nướng.\nBước 5: 5. Nướng gà lần đầu: Đặt gà lên khay nướng, phần da hướng lên trên. Nướng ở 200°C khoảng 35–40 phút cho đến khi gà chín và da bắt đầu vàng.\nBước 6: 6. Chuẩn bị sốt quét: Trộn mật ong với một ít nước mắm và dầu ăn để tạo hỗn hợp sốt giúp da gà vàng bóng và thơm hơn.\nBước 7: 7. Phết sốt và nướng lần cuối: Lấy gà ra, phết một lớp sốt mỏng lên phần da rồi tiếp tục nướng ở 220°C khoảng 5–10 phút cho đến khi da vàng giòn đẹp mắt.\nBước 8: 8. Kiểm tra và hoàn thành: Kiểm tra phần thịt bên trong đã chín hoàn toàn, sau đó lấy gà ra và để nghỉ khoảng 5–10 phút trước khi chặt thành miếng vừa ăn.\nBước 9: 9. Thưởng thức: Xếp gà ra đĩa, dùng nóng cùng muối ớt xanh, rau răm hoặc dưa leo để cân bằng vị cay mặn và thưởng thức.','Vietnamese',6,'Gà nướng thơm vàng với lớp da giòn rụm, thịt bên trong mềm mọng, thấm đậm vị muối ớt cay mặn hài hòa và có hương thơm hấp dẫn từ sả, tỏi.','Sơ chế gà → Chuẩn bị sốt muối ớt → Ướp gà → Làm nóng lò → Nướng gà → Phết sốt → Nướng lần cuối → Chặt gà và thưởng thức.','recipe_1790950290_303.jpg','https://www.youtube.com/results?search_query=G%C3%A0+N%C6%B0%E1%BB%9Bng+Mu%E1%BB%91i+%E1%BB%9At+Da+Gi%C3%B2n',8,'2026-09-23 00:15:03'),(37,'Lẩu Thái Hải Sản Kiểu Việt',40,'Bước 1: Phi thơm sả, riềng, cà chua và ớt, đổ nước hầm xương vào đun sôi.\nBước 2: Thêm lá chanh, nước cốt me, nêm nước mắm, đường, muối cho vị chua cay mặn ngọt hài hòa.\nBước 3: Đặt nồi lên bếp lẩu, thả hải sản và nấm vào nấu chín tới rồi thưởng thức nóng cùng bún và rau.','Vietnamese',6,'Nồi lẩu chua cay đậm đà hương lá chanh thái, sả ớt hòa quyện cùng tôm, mực, nghêu tươi sống và các loại nấm tươi mát.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/24/ad/59/24ad597e28ab57d9be26f551230e198b.jpg','https://www.youtube.com/results?search_query=L%E1%BA%A9u+Th%C3%A1i+H%E1%BA%A3i+S%E1%BA%A3n+Ki%E1%BB%83u+Vi%E1%BB%87t',10,'2026-09-23 00:15:03'),(39,'Cá Điêu Hồng Hấp Xì Dầu Nấm Đông Cô',23,'Bước 1: Sơ chế cá và nấm: Làm sạch cá điêu hồng, khứa vài đường trên thân; nấm đông cô ngâm mềm, rửa sạch và để ráo.\nBước 2: Ướp cá: Ướp cá với một ít xì dầu, gừng, tiêu và đường trong khoảng 15 phút.\nBước 3: Chuẩn bị nguyên liệu: Xếp cá lên đĩa, đặt nấm đông cô, gừng và hành lá xung quanh cá.\nBước 4: Hấp cá: Đặt đĩa cá vào xửng và hấp khoảng 15–20 phút đến khi cá chín mềm.\nBước 5: Rưới xì dầu: Rưới phần xì dầu còn lại và dầu mè lên cá, có thể thêm hành lá thái nhỏ.\nBước 6: Thưởng thức: Lấy cá ra khỏi xửng, dùng nóng cùng cơm trắng để cảm nhận vị cá mềm ngọt và xì dầu đậm đà.','Vietnamese',6,'Cá điêu hồng hấp mềm ngọt, thấm vị xì dầu đậm đà, kết hợp cùng nấm đông cô thơm mềm, tạo nên món ăn thanh nhẹ và hấp dẫn.','Sơ chế cá và nấm → Ướp cá → Chuẩn bị nguyên liệu → Hấp cá → Rưới xì dầu → Thưởng thức','recipe_1790869547_616.jpg','https://www.youtube.com/results?search_query=C%C3%A1+%C4%91i%C3%AAu+h%E1%BB%93ng+h%E1%BA%A5p+x%C3%AC+d%E1%BA%A7u+n%E1%BA%A5m+%C4%91%C3%B4ng+c%C3%B4',12,'2026-09-23 00:15:03'),(41,'Cơm Chiên Dương Châu Hải Sản',25,'Bước 1: Dùng cơm đã nấu từ trước và để nguội hoàn toàn, tốt nhất là cơm để trong tủ lạnh vài giờ. Dùng tay hoặc đũa tách các hạt cơm để khi chiên không bị vón cục.\nBước 2: Tôm bóc vỏ, bỏ chỉ lưng và cắt nhỏ. Lạp xưởng thái lát mỏng, cà rốt thái hạt lựu.\nBước 3: Làm nóng chảo với một ít dầu, cho trứng vào đảo nhanh đến khi vừa chín tới rồi lấy ra. Không chiên trứng quá khô để cơm giữ được độ mềm.\nBước 4: Cho lạp xưởng vào chảo đảo cho ra bớt dầu, sau đó cho tôm, cà rốt và đậu Hà Lan vào xào trên lửa lớn. Xào nhanh để hải sản không bị dai.\nBước 5: Cho cơm nguội vào chảo, đảo mạnh tay trên lửa lớn để hạt cơm tơi và săn. Thêm trứng đã chiên cùng nước tương, một ít dầu hào và tiêu rồi đảo đều.\nBước 6: Chiên thêm 2–3 phút đến khi cơm khô ráo, hạt tơi và topping phân bố đều. Tắt bếp, cho cơm ra đĩa và dùng nóng.','Chinese',3,'Cơm chiên Dương Châu hải sản là món cơm chiên kiểu Hoa với hạt cơm tơi, săn và thơm. Tôm, mực, trứng cùng rau củ tạo nên nhiều màu sắc và kết cấu, trong khi gia vị được nêm vừa phải để giữ vị thơm tự nhiên của nguyên liệu.','Sơ chế nguyên liệu → Chiên trứng → Xào hải sản & rau củ → Chiên cơm → Trộn đều & thưởng thức','recipe_1790852051_521.webp','https://www.youtube.com/results?search_query=C%C6%A1m+Chi%C3%AAn+D%C6%B0%C6%A1ng+Ch%C3%A2u+H%E1%BA%A3i+S%E1%BA%A3n',4,'2026-09-23 00:15:03'),(42,'Gỏi Ngó Sen Tôm Thịt Chua Ngọt',35,'Bước 1: Ngó sen tước phần xơ, cắt khúc vừa ăn rồi ngâm trong nước có pha một ít chanh để giữ màu trắng và độ giòn. Sau đó rửa lại và để ráo.\nBước 2: Tôm luộc chín, bóc vỏ và cắt đôi nếu tôm lớn. Thịt ba chỉ luộc chín, để nguội rồi thái lát mỏng.\nBước 3: Cà rốt và dưa leo thái sợi. Rau răm rửa sạch, để ráo rồi cắt nhỏ.\nBước 4: Pha nước mắm với đường, nước cốt chanh, một ít nước lọc, tỏi và ớt băm. Khuấy đều đến khi đường tan hoàn toàn.\nBước 5: Cho ngó sen, tôm, thịt, cà rốt, dưa leo và rau răm vào tô. Rưới nước trộn rồi đảo nhẹ tay. Bày ra đĩa, rắc đậu phộng rang và dùng ngay để giữ độ giòn.','Vietnamese',6,'Gỏi ngó sen tôm thịt là món khai vị thanh mát với ngó sen giòn, tôm ngọt, thịt heo mềm và nước trộn chua ngọt. Món ăn có vị hài hòa, giòn tươi và thường xuất hiện trong các bữa tiệc hoặc mâm cơm gia đình.','Sơ chế ngó sen → Luộc tôm thịt → Chuẩn bị rau → Pha nước trộn → Trộn gỏi & thưởng thức','recipe_1790857421_703.jpeg','https://www.youtube.com/results?search_query=G%E1%BB%8Fi+Ng%C3%B3+Sen+T%C3%B4m+Th%E1%BB%8Bt+Chua+Ng%E1%BB%8Dt',5,'2026-09-23 00:15:03'),(45,'Lẩu Mắm Miền Tây Đậm Tình Đất Mũi',60,'Bước 1: 1. Sơ chế mắm cá linh: Cho mắm cá linh vào nồi cùng khoảng 500ml nước, đun nhỏ lửa khoảng 10–15 phút cho mắm tan và tiết hết vị, sau đó lọc qua rây để loại bỏ xương và cặn.\nBước 2: 2. Sơ chế nguyên liệu: Cá basa cắt thành khúc vừa ăn. Tôm bóc vỏ, bỏ chỉ lưng. Mực làm sạch rồi cắt khoanh. Thịt ba chỉ thái lát mỏng.\nBước 3: 3. Chuẩn bị rau: Cà tím cắt miếng, bông súng tước vỏ và cắt khúc, rau muống, rau nhút, đậu bắp, giá đỗ, khổ qua và nấm rơm rửa sạch, để ráo.\nBước 4: 4. Chuẩn bị nguyên liệu tạo mùi: Sả đập dập và cắt khúc. Hành tím, tỏi và ớt băm nhỏ. Dứa gọt vỏ, bỏ mắt rồi cắt miếng vừa ăn.\nBước 5: 5. Nấu nước lẩu: Phi thơm hành tím, tỏi và sả với dầu ăn. Cho dứa và cà tím vào xào sơ rồi thêm phần nước mắm cá linh đã lọc cùng khoảng 500ml nước.\nBước 6: 6. Nêm nước lẩu: Đun sôi nước dùng rồi thêm đường, hạt nêm và một ít muối. Nêm nếm sao cho nước lẩu có vị mặn đậm đà đặc trưng, hơi ngọt và thơm mùi mắm.\nBước 7: 7. Chuẩn bị topping: Xếp cá basa, tôm, mực và thịt ba chỉ ra đĩa riêng. Xếp các loại rau và nấm ra đĩa để thuận tiện khi nhúng lẩu.\nBước 8: 8. Hoàn thiện nồi lẩu: Cho nấm rơm và một phần rau vào nồi, đun sôi lại rồi đặt nồi lẩu lên bếp giữ nóng.\nBước 9: 9. Thưởng thức: Khi ăn, lần lượt nhúng cá, tôm, mực, thịt và các loại rau vào nước lẩu đang sôi. Dùng nóng cùng bún tươi để cảm nhận vị đậm đà của nước lẩu và độ tươi ngon của các loại topping.','Vietnamese',6,'Lẩu mắm đặc trưng miền Tây với nước dùng đậm đà, thơm đặc trưng từ mắm cá linh, kết hợp cùng tôm, mực, cá và nhiều loại rau đồng quê tươi ngon.','Sơ chế nguyên liệu → Nấu nước mắm → Lọc nước dùng → Chuẩn bị hải sản và thịt → Sơ chế rau → Nêm nước lẩu → Bày nguyên liệu → Đun sôi và thưởng thức.','recipe_1790950068_895.jpg','https://www.youtube.com/results?search_query=L%E1%BA%A9u+M%E1%BA%AFm+Mi%E1%BB%81n+T%C3%A2y+%C4%90%E1%BA%ADm+T%C3%ACnh+%C4%90%E1%BA%A5t+M%C5%A9i',8,'2026-09-23 00:15:03'),(48,'Bánh Canh Trảng Bàng Giò Heo',50,'Bước 1: Chần sơ xương và giò heo, rửa sạch rồi cho vào nồi ninh cùng vài củ hành tím nướng trên lửa nhỏ, vớt bọt liên tục để nước dùng ngọt trong thanh tao.\nBước 2: Khi giò heo vừa chín mềm tới thì vớt ra ngâm ngay vào thau nước đá lạnh để da giòn trắng, sau đó thái lát mỏng.\nBước 3: Chần sợi bánh canh bột gạo mềm dẻo cho vào tô, xếp thịt giò heo lên trên, chan nước dùng nóng hổi, rắc hành ngò tiêu xay và chấm kèm nước mắm ớt nguyên chất.','Vietnamese',6,'Bánh canh sợi bột gạo hấp mềm dẻo, nước dùng ninh từ xương giò heo ngọt trong thanh tao, ăn cùng thịt giò nạc mỡ đan xen.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/49/ca/80/49ca806f1de66cba3ebdf77a2f0c1fd7.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+Canh+Tr%E1%BA%A3ng+B%C3%A0ng+Gi%C3%B2+Heo',11,'2026-09-23 00:15:03'),(51,'Cơm Gà Hải Nam Kiểu Sài Gòn',50,'Bước 1: Gà làm sạch, chà nhẹ với muối rồi rửa lại. Gừng đập dập, hành lá rửa sạch. Để gà ráo nước trước khi luộc.\nBước 2: Đun nồi nước đủ ngập gà, cho gừng và một phần hành lá vào. Khi nước sôi, cho gà vào, sau đó hạ nhỏ lửa và luộc khoảng 30–35 phút tùy kích thước gà. Khi gà chín, vớt ra ngâm vào nước lạnh vài phút để da săn và giữ độ mọng.\nBước 3: Vo gạo, để ráo rồi rang sơ với một ít dầu gà hoặc dầu ăn. Cho gạo vào nồi, dùng nước luộc gà để nấu thay nước thông thường. Có thể thêm một ít gừng băm để cơm thơm hơn.\nBước 4: Hành lá thái nhỏ, cho vào chén rồi rưới dầu nóng lên trên, khuấy đều. Dầu hành giúp cơm và thịt gà có mùi thơm đặc trưng.\nBước 5: Gà sau khi nguội bớt được chặt thành miếng vừa ăn. Có thể quét một lớp dầu mè mỏng lên phần da để da bóng và thơm.\nBước 6: Xới cơm ra đĩa, xếp gà lên trên hoặc bên cạnh, ăn kèm dưa leo và nước chấm gừng, tương ớt hoặc nước tương tùy khẩu vị.','Vietnamese',6,'Cơm gà Hải Nam kiểu Sài Gòn là món cơm lấy cảm hứng từ ẩm thực Hải Nam, được biến tấu phù hợp khẩu vị miền Nam. Gà luộc mềm mọng, da vàng, ăn cùng cơm nấu từ nước luộc gà thơm béo và các loại nước chấm đặc trưng.','Sơ chế gà → Luộc gà → Nấu cơm bằng nước luộc → Làm dầu hành & nước chấm → Chặt gà, bày cơm & thưởng thức','recipe_1790851957_612.jpg','https://www.youtube.com/results?search_query=C%C6%A1m+G%C3%A0+H%E1%BA%A3i+Nam+Ki%E1%BB%83u+S%C3%A0i+G%C3%B2n',4,'2026-09-23 00:15:03'),(52,'Bún Thịt Nướng Chả Giò Miền Nam',55,'Bước 1: Thịt heo thái lát mỏng, trộn với nước mắm, đường, mật ong, dầu hào, tỏi băm và tiêu. Ướp khoảng 30 phút để thịt thấm gia vị.\nBước 2: Dưa leo thái sợi, rau sống rửa sạch và để ráo. Bún trụng nhanh qua nước nóng rồi để ráo. Đậu phộng rang giã dập.\nBước 3: Nướng thịt trên bếp than hoặc nồi chiên không dầu ở nhiệt độ cao đến khi thịt chín vàng và có phần cạnh hơi xém. Trong quá trình nướng có thể phết thêm một lớp nước ướp để thịt bóng và thơm.\nBước 4: Đun dầu nóng rồi cho chả giò vào chiên ở lửa vừa đến khi lớp vỏ vàng giòn. Vớt ra để ráo dầu rồi cắt đôi hoặc cắt khúc.\nBước 5: Cho bún vào tô, thêm rau sống, dưa leo, thịt nướng và chả giò. Rưới nước mắm chua ngọt, rắc đậu phộng rang và hành phi rồi trộn đều trước khi ăn.','Vietnamese',6,'Bún thịt nướng chả giò là món bún trộn quen thuộc của miền Nam với thịt heo nướng thơm cháy cạnh, chả giò giòn rụm, bún tươi và rau sống. Nước mắm chua ngọt cùng đậu phộng rang tạo nên vị đậm đà nhưng thanh mát.','Ướp thịt → Chuẩn bị rau & bún → Nướng thịt → Chiên chả giò → Xếp bún & thưởng thức','recipe_1790857757_774.webp','https://www.youtube.com/results?search_query=B%C3%BAn+Th%E1%BB%8Bt+N%C6%B0%E1%BB%9Bng+Ch%E1%BA%A3+Gi%C3%B2+Mi%E1%BB%81n+Nam',5,'2026-09-23 00:15:03'),(55,'Bánh Khọt Vũng Tàu Tôm Tươi',45,'Bước 1: 1. Sơ chế tôm: Tôm bóc vỏ, bỏ đầu và chỉ lưng, rửa sạch rồi để ráo. Có thể giữ lại phần đuôi để bánh khọt đẹp mắt hơn.\nBước 2: 2. Chuẩn bị rau và đồ chua: Xà lách, rau thơm và cải xanh rửa sạch, ngâm nước muối loãng rồi để ráo. Đu đủ xanh và cà rốt bào sợi, ngâm với nước sạch rồi để ráo.\nBước 3: 3. Pha bột bánh: Cho bột bánh khọt vào tô, thêm nước lọc, nước cốt dừa, trứng gà, bột nghệ, muối và hạt nêm. Khuấy đều đến khi hỗn hợp bột mịn, không còn vón cục.\nBước 4: 4. Chuẩn bị hành lá: Hành lá rửa sạch, thái nhỏ rồi trộn với một ít dầu ăn để làm mỡ hành.\nBước 5: 5. Làm nóng khuôn: Đặt khuôn bánh khọt lên bếp, làm nóng khuôn rồi cho một ít dầu ăn vào từng khuôn bánh.\nBước 6: 6. Đổ bột và cho tôm: Khi khuôn nóng, đổ một lớp bột mỏng vào từng khuôn, đặt một con tôm lên trên rồi đậy nắp và chiên ở lửa vừa.\nBước 7: 7. Chiên bánh: Chiên khoảng 3–5 phút đến khi phần viền bánh vàng giòn, mặt bánh chín và tôm chuyển màu. Thêm một ít mỡ hành lên trên rồi lấy bánh ra khỏi khuôn.\nBước 8: 8. Làm nước mắm: Hòa tan đường với nước lọc và nước mắm, sau đó thêm nước cốt chanh, tỏi băm và ớt băm. Khuấy đều và điều chỉnh vị chua ngọt, mặn vừa ăn.\nBước 9: 9. Hoàn thành và thưởng thức: Xếp bánh khọt ra đĩa, dùng kèm xà lách, rau thơm, cải xanh và đồ chua. Cuốn bánh với rau rồi chấm vào nước mắm chua ngọt và thưởng thức khi bánh còn nóng.','Vietnamese',6,'Bánh khọt đặc trưng Vũng Tàu với lớp vỏ vàng giòn bên ngoài, bên trong mềm thơm, kết hợp cùng tôm tươi và hành lá. Bánh thường ăn kèm rau sống, đồ chua và nước mắm chua ngọt.','Chuẩn bị bột → Sơ chế tôm → Pha bột bánh → Làm nóng khuôn → Đổ bột và cho tôm → Chiên bánh giòn → Làm nước mắm → Chuẩn bị rau ăn kèm → Thưởng thức.','recipe_1790949703_242.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+Kh%E1%BB%8Dt+V%C5%A9ng+T%C3%A0u+T%C3%B4m+T%C6%B0%C6%A1i',8,'2026-09-23 00:15:03'),(57,'Gà Xào Sả Ớt Đậm Đà',25,'Bước 1: Ướp gà với 1/2 phần sả băm, chút nước mắm, hạt nêm trong 15 phút.\nBước 2: Phi thơm phần sả, tỏi, ớt còn lại với dầu ăn đến khi vàng dậy mùi.\nBước 3: Cho gà vào xào săn trên lửa lớn, hạ lửa vừa đậy vung om 7–10 phút đến khi cạn nước và sốt sánh vàng óng bám đều miếng gà.','Vietnamese',6,'Thịt gà ta chặt miếng vừa ăn xào săn cùng sả ớt băm thơm lừng, nước kho sánh vàng óng ả cay thơm nồng nàn.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/93/19/8d/93198d2dad7ae7de85e0b298e7d15286.jpg','https://www.youtube.com/results?search_query=G%C3%A0+X%C3%A0o+S%E1%BA%A3+%E1%BB%9At+%C4%90%E1%BA%ADm+%C4%90%C3%A0',10,'2026-09-23 00:15:03'),(58,'Tôm Rim Thịt Ba Rọi Mặn Ngọt',30,'Bước 1: Cho thịt ba rọi vào chảo đảo lửa vừa đến khi ra bớt mỡ và xém cạnh vàng thơm.\nBước 2: Cho hành tỏi băm vào phi thơm, trút tôm vào đảo đều trên lửa lớn cho tôm chuyển màu đỏ au.\nBước 3: Nêm nước mắm, đường và chút tiêu, hạ lửa nhỏ rim liu riu đến khi nước sốt keo lại bám bóng bẩy quanh tôm thịt thì rắc hành lá rồi tắt bếp.','Vietnamese',6,'Tôm đất đồng nguyên vỏ rim cùng thịt ba rọi cháy cạnh cho đến khi đường mắm keo lại đỏ au bóng bẩy giòn béo.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/736x/cb/ce/6d/cbce6ddfdcdc222958e5c428dad92ff7.jpg','https://www.youtube.com/results?search_query=T%C3%B4m+Rim+Th%E1%BB%8Bt+Ba+R%E1%BB%8Di+M%E1%BA%B7n+Ng%E1%BB%8Dt',11,'2026-09-23 00:15:03'),(61,'Bún Mắm Miền Tây Hải Sản',45,'Bước 1: Tôm bóc vỏ, bỏ chỉ lưng. Mực làm sạch rồi cắt khoanh. Cá lóc làm sạch và cắt khúc. Cà tím cắt miếng vừa ăn, rau ăn kèm rửa sạch và để ráo.\nBước 2: Cho mắm cá linh hoặc mắm cá sặc vào nồi cùng khoảng 500 ml nước. Đun nhỏ lửa cho mắm tan ra, sau đó lọc qua rây để loại bỏ phần xương và cặn.\nBước 3: Cho phần nước mắm đã lọc vào nồi cùng nước dùng. Thêm sả đập dập và một ít đường để cân bằng vị mặn. Đun sôi rồi hạ nhỏ lửa.\nBước 4: Cho cá lóc và cà tím vào nồi, nấu đến khi cá chín và cà tím mềm. Vớt cá ra, gỡ lấy phần thịt và để riêng.\nBước 5: Cho tôm và mực vào nồi nước dùng, nấu khoảng 3–5 phút đến khi vừa chín. Nêm lại nước dùng với đường, nước mắm và các gia vị cần thiết.\nBước 6: Cho bún vào tô, xếp cá, tôm, mực và cà tím lên trên. Chan nước dùng thật nóng, ăn kèm rau sống, rau muống chẻ để tăng độ thanh mát và giòn.','Vietnamese',6,'Bún mắm miền Tây là món nước đặc trưng với phần nước dùng có mùi thơm đặc trưng của mắm cá linh hoặc mắm cá sặc. Khi kết hợp cùng tôm, mực, cá và rau miền Tây, món ăn có vị đậm đà, thơm nồng nhưng được cân bằng bởi rau sống và các loại rau ăn kèm.','Sơ chế hải sản → Lọc nước mắm → Nấu nước dùng → Nấu hải sản → Chan bún & thưởng thức','recipe_1790851774_790.jpg','https://www.youtube.com/results?search_query=B%C3%BAn+M%E1%BA%AFm+Mi%E1%BB%81n+T%C3%A2y+H%E1%BA%A3i+S%E1%BA%A3n',4,'2026-09-23 00:15:03'),(62,'Bánh Đa Cua Hải Phòng',55,'Bước 1: Cua đồng rửa sạch, tách mai, lấy gạch cua để riêng. Phần thân cua giã hoặc xay nhuyễn với nước rồi lọc qua rây nhiều lần để lấy nước cua trong.\nBước 2: Xương hoặc sườn heo chần qua nước sôi rồi rửa sạch. Ninh với khoảng 1,5–2 lít nước trong 30–40 phút, thường xuyên hớt bọt để nước trong.\nBước 3: Chả lá lốt chiên hoặc nướng chín. Rau muống và rau rút làm sạch, cắt đoạn vừa ăn. Cà chua bổ múi cau.\nBước 4: Đun phần nước cua đã lọc ở lửa vừa, không khuấy mạnh để riêu cua kết lại thành mảng. Cho cà chua và gạch cua đã xào vào, sau đó hòa cùng nước dùng xương. Nêm gia vị vừa ăn.\nBước 5: Bánh đa đỏ ngâm và trụng nhanh qua nước sôi. Cho bánh đa vào tô, thêm riêu cua, chả lá lốt, rau muống và rau rút rồi chan nước dùng nóng. Dùng ngay khi còn nóng.','Vietnamese',6,'Bánh đa cua là món ăn nổi tiếng của Hải Phòng với sợi bánh đa đỏ dai mềm, nước dùng ngọt đậm từ cua và xương, kết hợp cùng chả lá lốt, rau và các loại topping. Món ăn có màu sắc đặc trưng và hương vị đậm đà của đất cảng.','Giã & lọc cua → Ninh nước dùng → Làm topping → Nấu nước cua → Trụng bánh đa & thưởng thức','recipe_1790857188_475.jpeg','https://www.youtube.com/results?search_query=B%C3%A1nh+%C4%90a+Cua+H%E1%BA%A3i+Ph%C3%B2ng',5,'2026-09-23 00:15:03'),(65,'Lẩu Cá Kèo Lá Giang Chua Thanh',45,'Bước 1: 1. Sơ chế cá kèo: Cá kèo rửa sạch, có thể chà nhẹ với muối để loại bỏ nhớt rồi rửa lại bằng nước sạch và để ráo.\nBước 2: 2. Sơ chế lá giang: Lá giang nhặt bỏ lá già, rửa sạch rồi vò nhẹ để lá tiết ra vị chua khi nấu.\nBước 3: 3. Chuẩn bị rau và nguyên liệu: Rau muống nhặt sạch, rửa và để ráo. Sả đập dập cắt khúc, hành tím và tỏi băm nhỏ, cà chua cắt múi cau, ớt thái lát.\nBước 4: 4. Nấu nước dùng: Đun nóng dầu ăn, phi thơm hành tím, tỏi và sả. Cho cà chua vào xào sơ rồi thêm khoảng 1 lít nước và đun sôi.\nBước 5: 5. Thêm lá giang và gia vị: Khi nước sôi, cho lá giang vào nồi, dùng vá dầm nhẹ để lá tiết vị chua. Thêm nước mắm, đường, muối và hạt nêm rồi khuấy đều.\nBước 6: 6. Cho cá kèo vào nồi: Khi nước lẩu sôi trở lại, cho cá kèo vào và nấu khoảng 5–7 phút đến khi cá vừa chín. Không nên nấu quá lâu để cá không bị nát.\nBước 7: 7. Hoàn thiện nồi lẩu: Nêm nếm lại nước dùng cho có vị chua thanh, mặn ngọt vừa ăn. Có thể thêm sa tế và ớt nếu muốn vị cay đậm đà hơn.\nBước 8: 8. Chuẩn bị thưởng thức: Xếp rau muống và bún tươi ra đĩa, đặt nồi lẩu lên bếp giữ nóng.\nBước 9: 9. Thưởng thức: Khi ăn, nhúng rau muống vào nước lẩu nóng, dùng cùng cá kèo, bún và nước dùng lá giang chua thanh.','Vietnamese',6,'Lẩu cá kèo với nước dùng chua thanh tự nhiên từ lá giang, kết hợp vị ngọt của cá kèo và hương thơm của sả, ớt. Món ăn thường dùng kèm rau muống, bún và các loại rau tươi.','Sơ chế cá kèo → Sơ chế lá giang và rau → Nấu nước dùng → Thêm lá giang và gia vị → Cho cá kèo vào nồi → Chuẩn bị rau và bún → Đun sôi và thưởng thức.','recipe_1790878176_920.jpg','https://www.youtube.com/results?search_query=L%E1%BA%A9u+C%C3%A1+K%C3%A8o+L%C3%A1+Giang+Chua+Thanh',8,'2026-09-23 00:15:03'),(66,'Cơm Hến Xứ Huế Cay Nồng',40,'Bước 1: Nếu dùng hến tươi, ngâm hến trong nước sạch khoảng 1–2 giờ, rửa nhiều lần rồi luộc với 1 lít nước cho hến mở miệng, sau đó vớt lấy thịt và giữ lại phần nước luộc.\nBước 2: Hành tím, tỏi, sả và ớt băm nhỏ; bắp chuối, rau muống và giá đỗ rửa sạch, để ráo.\nBước 3: Phi thơm hành tím, tỏi và sả với dầu ăn, cho thịt hến vào xào nhanh cùng nước mắm, đường, muối, tiêu và ớt bột cho hến thấm gia vị.\nBước 4: Cho một phần nước luộc hến vào nồi, thêm mắm ruốc Huế và ớt, khuấy đều rồi đun sôi khoảng 5 phút, nêm lại cho nước dùng đậm đà và cay vừa khẩu vị.\nBước 5: Chuẩn bị tô lớn, cho cơm trắng nguội vào trước, sau đó xếp hến xào, bắp chuối, rau muống chẻ, giá đỗ và rau thơm lên trên.\nBước 6: Rắc tóp mỡ giòn và đậu phộng rang lên cơm, thêm một ít ớt băm nếu thích ăn cay.\nBước 7: Chan một ít nước hến nóng vào tô hoặc dùng nước hến riêng bên cạnh, trộn đều cơm với hến và các loại rau trước khi ăn.\nBước 8: Thưởng thức cơm hến ngay khi còn ấm để cảm nhận vị ngọt của hến, vị cay nồng của ớt và mắm ruốc cùng độ giòn của tóp mỡ, đậu phộng và rau sống.','Vietnamese',6,'Đặc sản xứ Huế với cơm nguội trộn hến xào đậm đà, tóp mỡ giòn, rau sống, đậu phộng và nước hến cay nồng đặc trưng.','Sơ chế hến → Luộc và lọc nước hến → Xào hến → Chuẩn bị rau và topping → Làm nước hến → Trộn cơm → Thêm topping → Thưởng thức.','recipe_1790954299_162.jpg','https://www.youtube.com/results?search_query=C%C6%A1m+H%E1%BA%BFn+X%E1%BB%A9+Hu%E1%BA%BF+Cay+N%E1%BB%93ng',9,'2026-09-23 00:15:03'),(67,'Măng Nhồi Thịt Hấp Cách Thủy',35,'Bước 1: Trộn đều thịt xay với nấm hương, hành khô và gia vị.\nBước 2: Nhồi chặt phần nhân thịt vào từng khúc măng.\nBước 3: Xếp vào xửng hấp cách thủy trên lửa vừa 20–25 phút đến khi nhân chín thơm; cắt khúc vừa ăn.','Vietnamese',6,'Từng khúc măng tươi luộc sạch nhồi thịt heo mọc nấm hương béo ngọt hấp chín tới thơm lừng.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/f0/ef/f9/f0eff995984e1e37a5acc2e34fdf905e.jpg','https://www.youtube.com/results?search_query=M%C4%83ng+Nh%E1%BB%93i+Th%E1%BB%8Bt+H%E1%BA%A5p+C%C3%A1ch+Th%E1%BB%A7y',10,'2026-09-23 00:15:03'),(68,'Chả Mực Giã Tay Hạ Long',40,'Bước 1: Thân mực thái miếng nhỏ, râu mực thái hạt lựu để riêng.\nBước 2: Cho thân mực vào cối đá giã tay nhuyễn dẻo, sau đó trộn đều cùng râu mực, mỡ heo và gia vị để tạo độ giòn sần sật.\nBước 3: Thoa dầu ăn vào lòng bàn tay, nặn chả thành từng miếng tròn dẹt rồi thả vào chảo dầu nóng rán vàng ruộm hai mặt trên lửa vừa.\nBước 4: Bày ra đĩa, trang trí rau thơm và thưởng thức nóng!','Vietnamese',6,'Mực mai nang dày giã tay truyền thống tạo độ dai giòn sần sật tự nhiên, rán vàng ruộm thơm nức mũi.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/57/fb/98/57fb984fbecae1afeedfa2262f0282c1.jpg','https://www.youtube.com/results?search_query=Ch%E1%BA%A3+M%E1%BB%B1c+Gi%C3%A3+Tay+H%E1%BA%A1+Long',11,'2026-09-23 00:15:03'),(69,'Gỏi Gà Măng Cụt Chua Ngọt',40,'Bước 1: Sơ chế nguyên liệu: Gọt vỏ măng cụt, tách múi; cà rốt bào sợi, hành tây thái mỏng và rau răm rửa sạch.\nBước 2: Luộc gà: Luộc thịt gà trong nước đến khi chín, vớt ra để nguội rồi xé thành miếng vừa ăn.\nBước 3: Chuẩn bị nước trộn: Khuấy đều nước mắm, nước cốt chanh, đường, tỏi và ớt băm thành hỗn hợp chua ngọt.\nBước 4: Trộn gỏi: Cho gà xé, măng cụt, cà rốt, hành tây và rau răm vào tô, rưới nước trộn rồi đảo nhẹ.\nBước 5: Hoàn thiện: Trộn đều các nguyên liệu, nêm nếm lại cho vừa khẩu vị và rắc đậu phộng rang lên trên.\nBước 6: Thưởng thức: Bày gỏi ra đĩa và thưởng thức ngay để giữ độ giòn tươi của măng cụt.','Vietnamese',6,'Gỏi gà măng cụt chua ngọt với thịt gà mềm thơm, măng cụt giòn ngọt hòa quyện cùng rau củ và nước trộn đậm đà, tạo nên hương vị tươi mát, hấp dẫn.','Sơ chế nguyên liệu → Luộc gà → Xé gà → Chuẩn bị nước trộn → Trộn gỏi → Trang trí và thưởng thức','recipe_1790869182_928.jpg','https://www.youtube.com/results?search_query=G%E1%BB%8Fi+g%C3%A0+m%C4%83ng+c%E1%BB%A5t+chua+ng%E1%BB%8Dt',12,'2026-09-23 00:15:03'),(71,'Bò Nhúng Dấm Cuộn Bánh Tráng',35,'Bước 1: Thịt bò rửa sạch, thấm khô rồi thái lát thật mỏng ngang thớ. Có thể để thịt trong ngăn mát khoảng 15 phút trước khi thái để dễ thái mỏng.\nBước 2: Dưa leo, rau xà lách, rau thơm và các loại rau sống rửa sạch, ngâm nước muối loãng rồi để ráo. Dứa thái lát mỏng, hành tây thái múi cau.\nBước 3: Cho nước dừa, nước lọc và dấm vào nồi. Thêm dứa, hành tây, một ít đường, muối và nước mắm. Đun sôi rồi hạ nhỏ lửa để giữ nước dùng nóng.\nBước 4: Pha mắm nêm với dứa băm, đường, chanh và ớt theo khẩu vị. Khuấy đều để tạo nước chấm có vị mặn, ngọt, chua và cay hài hòa.\nBước 5: Khi ăn, dùng đũa hoặc vợt nhỏ nhúng từng lát bò vào nồi nước đang sôi. Nhúng nhanh đến khi thịt vừa chín tới để giữ độ mềm.\nBước 6: Làm mềm bánh tráng bằng một ít nước, đặt rau, bún, dứa và thịt bò lên trên rồi cuộn lại. Chấm cùng mắm nêm và thưởng thức ngay.','Vietnamese',6,'Bò nhúng dấm là món ăn kết hợp giữa thịt bò thái mỏng, nước dùng chua nhẹ và các loại rau sống. Thịt bò được nhúng nhanh trong nồi nước dấm nóng rồi cuốn cùng bánh tráng, rau và bún, tạo thành món ăn thanh nhẹ nhưng đậm đà.','Thái & ướp bò → Chuẩn bị rau & bánh tráng → Nấu nước nhúng dấm → Nhúng bò → Cuốn bánh & thưởng thức','recipe_1790851685_960.jpeg','https://www.youtube.com/results?search_query=B%C3%B2+Nh%C3%BAng+D%E1%BA%A5m+Cu%E1%BB%99n+B%C3%A1nh+Tr%C3%A1ng',4,'2026-09-23 00:15:03'),(72,'Cá Tai Tượng Chiên Xù Đứng Miền Tây',40,'Bước 1: Cá tai tượng làm sạch, bỏ mang và nội tạng, giữ nguyên con. Rửa với muối và nước sạch rồi dùng khăn giấy thấm thật khô toàn bộ thân cá.\nBước 2: Dùng dao khía nhẹ vài đường trên thân cá để nhiệt truyền đều vào phần thịt. Ướp cá với một ít muối và tiêu, sau đó để khoảng 10 phút. Cá càng khô thì khi chiên càng dễ đạt độ giòn.\nBước 3: Đun lượng dầu đủ ngập cá trong chảo sâu lòng. Khi dầu nóng, cho cá vào chiên ở lửa vừa, trở đều các mặt đến khi lớp da và vảy vàng giòn, thịt cá chín. Vớt ra để ráo dầu.\nBước 4: Pha nước mắm với đường, nước lọc, nước cốt chanh, tỏi và ớt băm. Khuấy đều đến khi có vị mặn, ngọt, chua và cay cân bằng.\nBước 5: Đặt cá lên đĩa, ăn kèm bánh tráng, bún, rau sống, dưa leo và đậu phộng. Gỡ từng phần thịt cá, cuốn cùng rau và chấm nước mắm chua ngọt.','Vietnamese',6,'Cá tai tượng chiên xù là món ăn đặc trưng của miền Tây Nam Bộ, nổi bật với nguyên con cá được chiên vàng giòn, phần da và vảy giòn rụm trong khi thịt cá bên trong vẫn mềm ngọt. Cá thường được cuốn bánh tráng cùng rau sống, bún và chấm nước mắm chua ngọt.','Sơ chế cá → Làm khô cá → Chiên xù → Pha nước chấm → Cuốn & thưởng thức','recipe_1790856453_869.jpg','https://www.youtube.com/results?search_query=C%C3%A1+Tai+T%C6%B0%E1%BB%A3ng+Chi%C3%AAn+X%C3%B9+%C4%90%E1%BB%A9ng+Mi%E1%BB%81n+T%C3%A2y',5,'2026-09-23 00:15:03'),(73,'Bánh Đúc Nóng Thịt Băm Hà Nội',30,'Bước 1: Bước 1: Trộn đều bột gạo tẻ và bột năng với nước, nêm chút muối và một ít dầu ăn, để bột nghỉ khoảng 30 phút rồi đem khuấy trên lửa nhỏ đến khi bột sánh đặc, trong và chín dẻo quánh.\nBước 2: Bước 2: Mộc nhĩ, nấm hương ngâm nở, thái nhỏ. Thịt heo băm ướp với chút hành khô băm, nước mắm, hạt tiêu khoảng 15 phút cho thấm gia vị.\nBước 3: Bước 3: Đun nóng chảo với dầu ăn, phi thơm hành khô rồi cho mộc nhĩ, nấm hương và thịt băm vào xào săn chín thơm, nêm nếm lại vừa ăn.\nBước 4: Bước 4: Múc bánh đúc nóng dẻo ra bát, múc phần thịt băm xào lên trên, rắc thêm rau mùi, hành phi và chan nước mắm ấm chua ngọt rồi thưởng thức.','Vietnamese',6,'Bát bánh đúc dẻo quánh ấm nóng múc ngập thịt băm mộc nhĩ xào thơm, chan nước mắm chua ngọt ấm bụng ngày đông.','Pha & khuấy bột -> Sơ chế & xào thịt -> Hoàn thành tô bánh đúc -> Thưởng thức nóng','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQelGGjXH3PUoFYsdmYEBGqI8qbuBVWqPQiV_eqaTan0A&s=10','https://www.youtube.com/results?search_query=B%C3%A1nh+%C4%90%C3%BAc+N%C3%B3ng+Th%E1%BB%8Bt+B%C4%83m+H%C3%A0+N%E1%BB%99i',6,'2026-09-23 00:15:03'),(75,'Lẩu Bò Nhúng Topping Đầy Đặn',60,'Bước 1: 1. Sơ chế nguyên liệu: Xương bò rửa sạch, chần qua nước sôi rồi rửa lại. Thịt bò thái thành những lát mỏng vừa ăn. Rau, nấm và các loại topping rửa sạch, để ráo.\nBước 2: 2. Chuẩn bị nguyên liệu tạo mùi: Gừng rửa sạch đập dập, sả đập dập cắt khúc, hành tây bóc vỏ và cắt múi cau. Tỏi và ớt băm nhỏ.\nBước 3: 3. Nấu nước dùng: Cho xương bò vào nồi cùng 1,5 lít nước, thêm gừng và sả rồi đun sôi. Hớt bọt thường xuyên để nước dùng trong và tiếp tục ninh khoảng 40–45 phút.\nBước 4: 4. Nêm nước lẩu: Cho sa tế, nước mắm, đường, hạt nêm và muối vào nồi nước dùng. Khuấy đều rồi nêm nếm lại cho vừa khẩu vị.\nBước 5: 5. Chuẩn bị topping: Đậu phụ cắt miếng vừa ăn, viên bò chuẩn bị sẵn, ngô cắt khúc và các loại nấm cắt bỏ phần gốc.\nBước 6: 6. Chuẩn bị rau: Cải thảo, rau muống và các loại rau ăn kèm rửa sạch, cắt thành những đoạn vừa ăn rồi xếp riêng ra đĩa\nBước 7: 7. Bày nguyên liệu: Xếp thịt bò thái mỏng, viên bò, đậu phụ, ngô, nấm và rau ra các đĩa riêng để dễ nhúng vào nồi lẩu.\nBước 8: 8. Hoàn thành nồi lẩu: Cho hành tây và một ít ớt vào nồi nước dùng, đun sôi rồi đặt nồi lẩu lên bếp giữ nóng\nBước 9: 9. Nhúng và thưởng thức: Khi nước lẩu sôi, lần lượt nhúng thịt bò, viên bò, nấm, rau và các topping vào nồi. Thịt bò chỉ cần nhúng vừa chín tới để giữ được độ mềm ngọt, sau đó thưởng thức nóng cùng nước chấm.','Vietnamese',6,'Nồi lẩu bò nóng hổi với nước dùng đậm đà, thịt bò thái mỏng mềm ngọt kết hợp cùng nhiều loại topping và rau nấm tươi ngon, thích hợp cho những bữa ăn quây quần cùng gia đình và bạn bè','Sơ chế nguyên liệu → Nấu nước dùng → Nêm gia vị → Chuẩn bị thịt bò và topping → Chuẩn bị rau nấm → Bày nguyên liệu → Đun sôi nước lẩu → Nhúng bò và topping → Thưởng thức','recipe_1790877843_942.jpg','https://www.youtube.com/results?search_query=L%E1%BA%A9u+B%C3%B2+Nh%C3%BAng+Topping+%C4%90%E1%BA%A7y+%C4%90%E1%BA%B7n',8,'2026-09-23 00:15:03'),(76,'Súp Cua Bắp Non Trứng Cút',30,'Bước 1: Bắp non và cà rốt rửa sạch, thái thành những miếng nhỏ vừa ăn; nấm hương ngâm nước ấm cho nở rồi thái lát.\nBước 2: Trứng cút luộc chín khoảng 5–6 phút, bóc vỏ và để riêng; trứng gà đập vào bát rồi đánh tan.\nBước 3: Đun nóng nước dùng gà, cho bắp non, cà rốt và nấm hương vào nấu khoảng 5–7 phút cho rau củ vừa chín mềm.\nBước 4: Cho thịt cua vào nồi, khuấy nhẹ để thịt cua phân bố đều mà không bị nát quá.\nBước 5: Thêm trứng cút đã luộc vào nồi và nêm hạt nêm, muối, đường, tiêu cùng dầu mè cho vừa khẩu vị.\nBước 6: Hòa bột năng với 50ml nước lạnh, từ từ đổ vào nồi súp và khuấy liên tục đến khi súp đạt độ sánh mong muốn.\nBước 7: Từ từ rót trứng gà đã đánh tan vào nồi theo dòng nhỏ, đồng thời khuấy nhẹ theo một chiều để tạo thành các sợi trứng đẹp mắt.\nBước 8: Nấu thêm khoảng 1–2 phút rồi tắt bếp, nêm lại gia vị nếu cần và rắc hành lá cùng rau mùi lên trên.\nBước 9: Múc súp cua ra tô, rắc thêm một chút tiêu và thưởng thức khi còn nóng.','Vietnamese',6,'Món súp cua nóng hổi với thịt cua ngọt thơm, bắp non giòn nhẹ, trứng cút béo bùi và nước súp sánh mịn.','Sơ chế nguyên liệu → Nấu nước dùng → Cho thịt cua và bắp non → Thêm trứng cút → Khuấy trứng → Tạo độ sánh → Nêm gia vị → Hoàn thành và thưởng thức.','recipe_1790954040_454.jpg','https://www.youtube.com/results?search_query=S%C3%BAp+Cua+B%E1%BA%AFp+Non+Tr%E1%BB%A9ng+C%C3%BAt',9,'2026-09-23 00:15:03'),(78,'Bánh Canh Ghẹ Nguyên Con',45,'Bước 1: Ghẹ làm sạch, hấp chín nguyên con rồi vớt ra để riêng.\nBước 2: Nấu nước dùng từ xương hầm và củ cải cho ngọt; chưng dầu màu điều cho vào nồi để tạo màu đỏ gạch đẹp mắt, nêm gia vị vừa ăn rồi hòa chút bột năng vào khuấy nhẹ cho nước hơi sánh.\nBước 3: Chần sợi bánh canh bột lọc cho vào tô, xếp ghẹ nguyên con lên trên, chan nước dùng sánh đỏ ngập mặt tô, rắc hành ngò, tiêu xay và thưởng thức nóng.','Vietnamese',6,'Con ghẹ biển tươi xanh luộc ngọt lịm nằm trên bát bánh canh bột lọc nước dùng sánh đỏ gạch cua thơm nức.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/28/10/42/2810421ad30ea14dc61515a148c8f8ea.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+Canh+Gh%E1%BA%B9+Nguy%C3%AAn+Con',11,'2026-09-23 00:15:03'),(79,'Cánh Gà Chiên Nước Mắm Kẹo',31,'Bước 1: Sơ chế cánh gà: Rửa sạch cánh gà, để ráo và có thể chặt thành từng khúc vừa ăn.\nBước 2: Ướp gia vị: Ướp cánh gà với một ít nước mắm, tiêu và tỏi băm trong khoảng 20–30 phút.\nBước 3: Chiên cánh gà: Phủ một lớp bột chiên giòn mỏng lên cánh gà rồi chiên trong dầu nóng đến khi vàng giòn và chín đều.\nBước 4: Làm sốt nước mắm: Phi thơm tỏi, cho nước mắm và đường vào chảo, đun nhỏ lửa đến khi hỗn hợp sánh lại.\nBước 5: Áo sốt: Cho cánh gà đã chiên vào chảo sốt, đảo đều đến khi nước mắm bám thành lớp kẹo óng quanh cánh gà.\nBước 6: Thưởng thức: Gắp cánh gà ra đĩa, rắc thêm ớt hoặc tiêu và thưởng thức khi còn nóng.','Vietnamese',6,'Cánh gà chiên nước mắm kẹo vàng óng, giòn bên ngoài, mềm thơm bên trong, phủ lớp sốt nước mắm đậm đà, ngọt nhẹ và sánh quyện.','Sơ chế cánh gà → Ướp gia vị → Chiên cánh gà → Làm sốt nước mắm → Áo sốt → Thưởng thức','recipe_1790868847_711.jpg','https://www.youtube.com/results?search_query=C%C3%A1nh+g%C3%A0+chi%C3%AAn+n%C6%B0%E1%BB%9Bc+m%E1%BA%AFm+kẹo',12,'2026-09-23 00:15:04'),(80,'Gỏi Cuốn Nem Nướng Nha Trang',40,'Bước 1: Làm nem nướng: Trộn thịt heo xay với tỏi băm, hành lá, nước mắm, đường, tiêu và bột năng, sau đó để ướp khoảng 20 phút.\nBước 2: Chuẩn bị rau: Rửa sạch xà lách, dưa leo, cà rốt và cắt thành những phần vừa cuốn.\nBước 3: Nướng nem: Nặn thịt thành những thanh nem vừa ăn, phết dầu rồi nướng trên bếp hoặc nồi chiên không dầu đến khi chín vàng thơm.\nBước 4: Chuẩn bị bánh tráng: Nhúng bánh tráng qua nước cho mềm rồi đặt lên mặt phẳng sạch.\nBước 5: Cuốn gỏi: Xếp xà lách, bún, dưa leo, cà rốt và nem nướng lên bánh tráng, gấp hai mép rồi cuộn chặt tay.\nBước 6: Hoàn thiện và thưởng thức: Cắt đôi cuốn gỏi, rắc thêm đậu phộng và dùng cùng nước chấm khi còn tươi ngon.','Vietnamese',6,'Gỏi cuốn nem nướng Nha Trang kết hợp nem nướng thơm đậm đà, rau sống tươi mát, bún và bánh tráng mềm, dùng cùng nước chấm đậu phộng béo bùi.','Làm nem nướng → Chuẩn bị rau và bún → Làm nước chấm → Nướng nem → Cuốn bánh tráng → Hoàn thiện và thưởng thức.','recipe_1790873051_149.jpg','https://www.youtube.com/results?search_query=gỏi+cuốn+nem+nướng+Nha+Trang+recipe',13,'2026-09-23 00:15:04'),(81,'Canh Sườn Nấu Sấu Hà Nội',30,'Bước 1: Sườn chặt miếng vừa ăn, chần qua nước sôi khoảng 2–3 phút rồi rửa lại bằng nước sạch để loại bỏ bọt và tạp chất.\nBước 2: Sấu cạo sạch vỏ, dùng dao khía nhẹ vài đường trên quả. Cà chua rửa sạch, bổ múi cau.\nBước 3: Phi thơm hành tím, cho sườn vào đảo sơ. Thêm khoảng 1,2 lít nước và đun sôi. Hạ lửa, ninh khoảng 30–35 phút cho sườn mềm.\nBước 4: Cho sấu và cà chua vào nồi, tiếp tục nấu khoảng 8–10 phút để sấu tiết vị chua và cà chua mềm.\nBước 5: Dùng muôi dầm nhẹ một vài quả sấu để nước canh có vị chua rõ hơn. Nêm muối, nước mắm và một chút đường cho cân bằng.\nBước 6: Tắt bếp, cho hành lá và rau mùi thái nhỏ vào. Múc canh ra tô và dùng cùng cơm nóng.','Vietnamese',6,'Canh sườn nấu sấu là món canh đặc trưng của mùa hè Hà Nội, nổi bật với vị chua thanh tự nhiên từ quả sấu kết hợp với vị ngọt của sườn heo. Món canh thường được dùng nóng hoặc ấm cùng cơm trắng.','Sơ chế sườn & sấu → Ninh sườn → Cho sấu & cà chua → Nêm vị chua thanh → Thêm rau thơm & thưởng thức','recipe_1790851583_824.jpg','https://youtu.be/avEnvAkDGGg?si=J604JnIkI-xBWgL2',4,'2026-09-23 00:15:04'),(82,'Cá Thu Sốt Cà Chua Đậm Đà',35,'Bước 1: Cá thu cắt khoanh, rửa sạch và thấm khô. Ướp với một ít muối và tiêu khoảng 10 phút để cá đậm vị.\nBước 2: Làm nóng chảo với dầu, cho cá thu vào chiên ở lửa vừa đến khi hai mặt vàng nhẹ. Vớt cá ra để riêng.\nBước 3: Phi thơm tỏi, cho hành tây vào xào mềm. Thêm cà chua thái nhỏ cùng một ít nước, nấu đến khi cà chua nhừ và tạo thành sốt.\nBước 4: Nêm nước mắm, đường, tiêu và ớt vào sốt. Cho cá thu vào, hạ lửa nhỏ và om khoảng 8–10 phút để cá thấm đều sốt.\nBước 5: Nêm lại gia vị, rắc hành lá và tiêu lên trên. Múc cá ra đĩa, chan phần sốt cà chua và dùng nóng với cơm trắng.','Vietnamese',6,'Cá thu sốt cà chua là món ăn gia đình quen thuộc với thịt cá thu săn chắc, được chiên vàng rồi om trong sốt cà chua chua ngọt. Món ăn có vị đậm đà, thơm hành tỏi và đặc biệt hợp dùng với cơm nóng.','Sơ chế cá → Chiên vàng → Nấu sốt cà chua → Om cá thấm vị → Hoàn thiện & thưởng thức','recipe_1790856252_651.jpg','https://www.youtube.com/results?search_query=C%C3%A1+Thu+S%E1%BB%91t+C%C3%A0+Chua+%C4%90%E1%BA%ADm+%C4%90%C3%A0',5,'2026-09-23 00:15:04'),(85,'Mì Xào Giòn Hải Sản Thập Cẩm',45,'Bước 1: 1. Sơ chế nguyên liệu: Tôm bóc vỏ, bỏ đầu và chỉ lưng. Mực làm sạch, bỏ mai và nội tạng rồi cắt miếng vừa ăn. Cà rốt, hành tây, ớt chuông, cải thìa và bông cải rửa sạch, cắt thành miếng vừa ăn.\nBước 2: 2. Chuẩn bị nước sốt: Cho dầu hào, nước tương, tương ớt, tương cà, đường, hạt nêm và một ít nước vào bát. Thêm bột năng rồi khuấy đều cho hỗn hợp hòa tan.\nBước 3: 3. Chiên mì: Đun nóng dầu ăn, cho mì vào chiên đến khi sợi mì vàng đều và giòn. Vớt mì ra để ráo dầu rồi đặt lên đĩa.\nBước 4: 4. Xào hải sản: Phi thơm tỏi với một ít dầu, cho tôm và mực vào xào nhanh trên lửa lớn đến khi vừa chín tới thì cho ra đĩa.\nBước 5: 5. Xào rau củ: Cho cà rốt, bông cải, cải thìa, hành tây, ớt chuông và cần tây vào chảo, xào nhanh tay để rau củ vừa chín nhưng vẫn giữ được độ giòn.\nBước 6: 6. Thêm nước sốt: Đổ phần nước sốt đã chuẩn bị vào chảo rau củ, đảo đều cho sốt bao phủ các nguyên liệu và hơi sánh lại\nBước 7: 7. Kết hợp hải sản: Cho tôm và mực đã xào trở lại chảo, đảo đều khoảng 1–2 phút để hải sản thấm sốt.\nBước 8: 8. Hoàn thành: Đặt mì chiên giòn lên đĩa, cho phần hải sản và rau củ cùng nước sốt lên trên, trang trí với cần tây hoặc hành lá và thưởng thức khi còn nóng.','Vietnamese',6,'Mì xào giòn vàng rụm kết hợp cùng tôm, mực và các loại rau củ tươi ngon, phủ nước sốt đậm đà, sánh nhẹ, tạo nên món ăn hấp dẫn và đầy đủ hương vị.','Sơ chế nguyên liệu → chiên mì vàng giòn → xào tôm mực → xào rau củ → làm sốt → kết hợp nguyên liệu → trình bày.','recipe_1790877340_827.jpg','https://www.youtube.com/watch?v=ZPi2wdg_he8',8,'2026-09-23 00:15:04'),(86,'Canh Khổ Qua Nhồi Thịt',45,'Bước 1: Khổ qua rửa sạch, cắt bỏ hai đầu, bổ dọc và dùng thìa lấy hết phần ruột cùng hạt bên trong\nBước 2: Mộc nhĩ ngâm nước ấm cho nở, rửa sạch rồi băm nhỏ; hành tím bóc vỏ và băm nhuyễn, hành lá thái nhỏ.\nBước 3: Cho thịt heo xay, mộc nhĩ, hành tím, hành lá, tiêu, hạt nêm và một chút nước mắm vào tô, trộn đều rồi để khoảng 10 phút cho nhân thấm gia vị.\nBước 4: Dùng thìa nhồi phần nhân thịt vào bên trong từng quả khổ qua, nén vừa phải để nhân không bị bung ra khi nấu.\nBước 5: Đun sôi 1,2 lít nước, cho khổ qua đã nhồi thịt vào nồi và nấu ở lửa vừa khoảng 25–30 phút, thường xuyên vớt bọt để nước canh trong.\nBước 6: Khi khổ qua mềm và phần thịt bên trong chín hoàn toàn, nêm thêm muối, hạt nêm, đường và nước mắm cho vừa khẩu vị.\nBước 7: Nấu thêm khoảng 2–3 phút để gia vị hòa vào nước canh rồi tắt bếp.\nBước 8: Múc khổ qua nhồi thịt ra tô, chan nước canh lên trên, rắc hành lá và rau mùi, thêm vài lát ớt nếu thích rồi thưởng thức nóng.','Vietnamese',6,'Khổ qua nhồi thịt mềm, nước canh thanh mát, hơi đắng nhẹ hòa cùng vị ngọt đậm đà của thịt và nước dùng.','Sơ chế khổ qua → Chuẩn bị nhân thịt → Nhồi nhân → Nấu nước dùng → Cho khổ qua vào nấu → Nêm gia vị → Hoàn thành và thưởng thức.','recipe_1790953759_645.jpg','https://www.youtube.com/results?search_query=Canh+Kh%E1%BB%95+Qua+Nh%E1%BB%93i+Th%E1%BB%8Bt',9,'2026-09-23 00:15:04'),(88,'Bánh Mì Chảo Bò Bít Tết Trứng Ốp La',20,'Bước 1: Ướp thịt bò với chút dầu hào, tỏi băm, tiêu và dầu ăn trong 10 phút cho ngấm mềm.\nBước 2: Nấu sốt: Phi thơm tỏi, xào mềm cà chua, nêm tương cà, dầu hào, tiêu đun sệt lại.\nBước 3: Đun nóng chảo gang, cho bơ lạt vào áp chảo thịt bò nhanh 1–2 phút cho vừa chín tới; ốp la trứng lòng đào, đặt pate, xíu mại vào chảo rồi rưới sốt bơ cà chua nóng lên, ăn kèm bánh mì.','Vietnamese',6,'Chảo gang nóng xèo xèo miếng bít tết bò mềm thơm, trứng ốp la lòng đào, pate béo ngậy và xíu mại chan sốt bơ.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/736x/59/8c/6c/598c6c4e1c37d09fc588c9e51e9ba7b5.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+M%C3%AC+Ch%E1%BA%A3o+B%C3%B2+B%C3%ADt+T%E1%BA%BFt+Tr%E1%BB%A9ng+%E1%BB%90p+La',11,'2026-09-23 00:15:04'),(89,'Chả Giò Cá Trích Phú Quốc',40,'Bước 1: Sơ chế cá trích: Rửa sạch cá trích phi lê, để ráo rồi băm nhỏ hoặc cắt thành miếng nhỏ.\nBước 2: Trộn nhân: Trộn cá trích với cà rốt, hành tây, miến, hành tím, trứng, nước mắm và tiêu.\nBước 3: Cuốn chả giò: Trải bánh tráng, cho lượng nhân vừa đủ vào giữa rồi cuốn chặt tay thành từng cuốn.\nBước 4: Chiên chả giò: Đun nóng dầu, cho chả giò vào chiên ở lửa vừa đến khi vỏ vàng giòn.\nBước 5: Để ráo dầu: Vớt chả giò ra và đặt lên giấy thấm dầu để loại bỏ dầu thừa.\nBước 6: Thưởng thức: Dùng chả giò cá trích khi còn nóng, ăn kèm rau sống và nước chấm.','Vietnamese',6,'Chả giò cá trích Phú Quốc giòn rụm bên ngoài, nhân cá trích thơm béo, đậm đà, kết hợp cùng rau củ tạo nên món ăn hấp dẫn.','Sơ chế cá trích → Trộn nhân → Cuốn chả giò → Chiên chả giò → Để ráo dầu → Thưởng thức','recipe_1790868580_242.jpg','https://www.youtube.com/results?search_query=Ch%E1%BA%A3+gi%C3%B2+c%C3%A1+tr%C3%ADch+Ph%C3%BA+Qu%E1%BB%91c',12,'2026-09-23 00:15:04'),(90,'Cơm Chiên Cá Mặn Gà Xé',25,'Bước 1: Sơ chế nguyên liệu: Luộc chín thịt gà, để nguội rồi xé sợi; cá mặn rửa sạch, để ráo và xé nhỏ.\nBước 2: Chiên cá mặn: Phi thơm tỏi với dầu ăn, cho cá mặn vào chiên đến khi vàng thơm và tơi ra.\nBước 3: Xào gà: Cho thịt gà xé vào chảo, đảo đều với cá mặn khoảng 2–3 phút rồi cho ra đĩa.\nBước 4: Chiên cơm: Phi thơm hành tím, cho cơm nguội vào đảo đều trên lửa lớn để hạt cơm tơi và săn.\nBước 5: Thêm trứng: Đẩy cơm sang một bên chảo, cho trứng vào đảo chín rồi trộn đều với cơm.\nBước 6: Trộn nguyên liệu: Cho hỗn hợp cá mặn và gà xé vào chảo, đảo đều để các nguyên liệu hòa quyện.\nBước 7: Hoàn thiện: Nêm nước mắm, đường và tiêu cho vừa ăn, rắc hành lá lên trên rồi tắt bếp.','Vietnamese',6,'Cơm chiên cá mặn gà xé thơm ngon với hạt cơm tơi giòn, kết hợp vị đậm đà của cá mặn và thịt gà xé mềm, thích hợp cho bữa sáng hoặc bữa ăn nhanh.','Sơ chế nguyên liệu → Chiên cá mặn → Xào gà → Chiên cơm → Trộn nguyên liệu → Nêm gia vị → Hoàn thiện và thưởng thức.','recipe_1790872766_470.jpg','https://www.youtube.com/results?search_query=cơm+chiên+cá+mặn+gà+xé+recipe',13,'2026-09-23 00:15:04'),(91,'Nộm Bò Khô Đu Đủ Phố Cổ',20,'Bước 1: Đu đủ xanh gọt vỏ, bỏ hạt, bào thành sợi dài. Ngâm đu đủ trong nước lạnh khoảng 10 phút rồi vớt ra, vắt nhẹ cho ráo nước để giữ độ giòn.\nBước 2: Cà rốt bào sợi. Rau kinh giới nhặt sạch, rửa và để ráo. Bò khô xé thành những sợi vừa ăn.\nBước 3: Pha nước mắm với đường, nước cốt chanh, một ít nước lọc và ớt băm. Khuấy đều cho đường tan và tạo thành hỗn hợp chua ngọt.\nBước 4: Cho đu đủ và cà rốt vào tô, rưới nước trộn rồi đảo nhẹ. Để khoảng 3–5 phút cho rau củ ngấm gia vị.\nBước 5: Cho bò khô, gan sấy và rau kinh giới vào, trộn đều nhưng không bóp mạnh để đu đủ không bị mềm.\nBước 6: Cho nộm ra đĩa, rắc đậu phộng rang lên trên. Có thể thêm một ít bò khô sợi ở mặt trên để món ăn đẹp mắt hơn.','Vietnamese',6,'Nộm bò khô đu đủ là món ăn vặt quen thuộc của Hà Nội, đặc biệt gắn với những hàng nộm phố cổ. Đu đủ xanh giòn, bò khô dai thơm, kết hợp với nước trộn chua ngọt và đậu phộng tạo nên hương vị vừa đậm đà vừa thanh nhẹ.','Sơ chế đu đủ → Chuẩn bị bò khô & rau → Pha nước trộn → Trộn nộm → Rắc đậu phộng & thưởng thức','recipe_1790851475_232.jpeg','https://youtu.be/oTuRb02R5NY?si=izV4Mrz78xVX8Ach',4,'2026-09-23 00:15:04'),(92,'Bún Bò Xào Nam Bộ Thanh Mát',30,'Bước 1: Thịt bò thái lát mỏng ngang thớ, trộn với một ít nước mắm, dầu hào, đường, tiêu và tỏi băm. Ướp khoảng 10–15 phút.\nBước 2: Dưa leo thái sợi, hành tây thái mỏng. Rau sống và giá đỗ rửa sạch rồi để thật ráo. Đậu phộng rang giã dập.\nBước 3: Pha nước mắm với đường, nước lọc và nước cốt chanh. Thêm tỏi, ớt băm và khuấy đều cho đường tan hoàn toàn.\nBước 4: Làm nóng chảo ở nhiệt độ cao, cho bò vào xào nhanh khoảng 2–3 phút. Thêm hành tây và đảo nhanh đến khi bò vừa chín tới.\nBước 5: Cho bún vào tô, xếp rau, dưa leo, giá và thịt bò lên trên. Rưới nước mắm, rắc đậu phộng và hành phi rồi trộn đều trước khi ăn.','Vietnamese',6,'Bún bò xào Nam Bộ là món bún trộn thanh mát với thịt bò xào nhanh, bún tươi và nhiều loại rau sống. Nước mắm chua ngọt cùng đậu phộng rang tạo nên vị đậm đà, cân bằng với sự tươi giòn của rau.','Ướp bò → Sơ chế rau → Pha nước mắm → Xào bò → Trộn bún & thưởng thức','recipe_1790856109_972.jpeg','https://www.youtube.com/results?search_query=B%C3%BAn+B%C3%B2+X%C3%A0o+Nam+B%E1%BB%99+Thanh+M%C3%A1t',5,'2026-09-23 00:15:04'),(95,'Thịt Ba Chỉ Luộc Chấm Mắm Tôm Chua',35,'Bước 1: 1. Sơ chế thịt: Rửa sạch thịt ba chỉ với nước muối loãng, sau đó rửa lại bằng nước sạch. Đập dập gừng và bóc vỏ hành tím.\nBước 2: 2. Luộc thịt: Cho thịt vào nồi cùng nước, gừng và hành tím. Đun sôi, hớt bọt và tiếp tục luộc khoảng 20–25 phút đến khi thịt chín mềm.\nBước 3: 3. Ngâm thịt: Vớt thịt ra và ngâm vào nước đun sôi để nguội khoảng 5 phút để thịt trắng và săn hơn.\nBước 4: 4. Thái thịt: Để thịt nguội rồi thái thành từng lát vừa ăn.\nBước 5: 5. Pha mắm tôm chua: Trộn mắm tôm chua với tỏi băm, ớt băm, đường và nước cốt chanh. Khuấy đều để tạo hỗn hợp chấm đậm đà\nBước 6: 6. Trình bày món ăn và Thưởng thức: Xếp thịt ba chỉ ra đĩa, bày kèm rau sống và chén mắm tôm chua. Cuốn thịt cùng rau sống và chấm mắm tôm chua để cảm nhận hương vị hài hòa giữa vị béo của thịt và vị đậm đà của nước chấm','Vietnamese',6,'Món ăn dân dã đậm chất Việt Nam với thịt ba chỉ luộc mềm, thơm ngon, ăn kèm mắm tôm chua chua ngọt ngọt, cay nhẹ và rau sống tươi mát.','Sơ chế thịt → luộc thịt → pha mắm tôm chua → thái thịt → bày cùng rau sống và thưởng thức.','recipe_1790876790_780.jpg','https://www.youtube.com/watch?v=v_9tlDz3pKs',8,'2026-09-23 00:15:04'),(96,'Bún Mọc Sườn Heo Dọc Mùng',60,'Bước 1: Sườn heo rửa sạch, chặt miếng vừa ăn rồi chần qua nước sôi khoảng 3 phút để loại bỏ bọt và tạp chất, sau đó rửa lại với nước sạch.\nBước 2: Mộc nhĩ và nấm hương ngâm nước ấm cho nở, rửa sạch rồi băm nhỏ, hành tím bóc vỏ và đập dập.\nBước 3: Trộn giò sống với mộc nhĩ, nấm hương và tiêu, sau đó vo thành những viên mọc nhỏ vừa ăn.\nBước 4: Đun sôi nước, thả từng viên mọc vào luộc đến khi mọc nổi lên thì vớt ra để riêng.\nBước 5: Cho sườn vào nồi cùng 1,5 lít nước và hành tím, hầm ở lửa nhỏ khoảng 35–40 phút, thường xuyên vớt bọt để nước dùng trong.\nBước 6: Dọc mùng tước bỏ lớp vỏ xơ, thái lát chéo, bóp với một ít muối rồi rửa sạch và vắt ráo để giảm ngứa.\nBước 7: Cà chua bổ múi cau, hành tây thái lát, sau đó cho cà chua và hành tây vào nồi nước dùng, nêm nước mắm, muối, đường và hạt nêm cho vừa vị.\nBước 8: Cho dọc mùng và mọc đã luộc vào nồi, nấu thêm khoảng 3–5 phút rồi tắt bếp để dọc mùng vẫn giữ được độ giòn.\nBước 9: Trụng bún tươi qua nước nóng, cho vào tô, xếp sườn, mọc và dọc mùng lên trên, chan nước dùng nóng rồi rắc hành lá, rau mùi và thưởng thức.','Vietnamese',6,'Món bún nước thanh ngọt với nước dùng hầm sườn heo, mọc thịt nấm mềm thơm và dọc mùng giòn nhẹ, ăn kèm rau thơm.','Sơ chế sườn → Nấu nước dùng → Làm mọc → Luộc mọc → Sơ chế dọc mùng → Nêm nước dùng → Trụng bún → Chan nước dùng và thưởng thức.','recipe_1790953564_482.jpg','https://www.youtube.com/results?search_query=B%C3%BAn+M%E1%BB%8Dc+S%C6%B0%E1%BB%9Dn+Heo+D%E1%BB%8Dc+M%C3%B9ng',9,'2026-09-23 00:15:04'),(97,'Cút Lộn Xào Me Chua Ngọt Cay Cay',20,'Bước 1: Luộc chín trứng cút lộn, ngâm nước lạnh rồi bóc sạch vỏ.\nBước 2: Phi thơm tỏi băm, cho nước cốt me cùng đường, nước mắm, tương ớt và ớt băm vào đun sôi lăn tăn đến khi sốt hơi sệt lại.\nBước 3: Cho trứng cút lộn vào đảo nhẹ tay trên lửa nhỏ 3–5 phút cho thấm đẫm sốt me; múc ra đĩa, rắc rau răm, hành phi và đậu phộng lên trên.','Vietnamese',6,'Trứng cút lộn luộc bóc vỏ xào cùng sốt me sánh đặc chua ngọt, rắc rau răm và đậu phộng rang giòn ăn vặt cực đỉnh.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/736x/66/81/d8/6681d898f8d4ae82aac10c18257f3875.jpg','https://www.youtube.com/results?search_query=C%C3%BAt+L%E1%BB%99n+X%C3%A0o+Me+Chua+Ng%E1%BB%8Dt+Cay+Cay',10,'2026-09-23 00:15:04'),(98,'Lẩu Riêu Cua Bắp Bò Sườn Sụn',45,'Bước 1: Sườn sụn chần sơ rồi ninh nhỏ lửa 20 phút cho mềm sần sật. Phi thơm hành tím xào cà chua và gạch cua cho lên màu đẹp.\nBước 2: Đun nước lọc cua với chút muối trên lửa vừa, khuấy nhẹ đến khi riêu nổi mảng lớn thì vớt riêng ra bát.\nBước 3: Đổ nước ninh sườn vào nồi nước cua, thêm cà chua xào, sườn sụn và giấm bỗng, nêm nước mắm vừa vị chua thanh đậm đà; khi ăn nhúng thịt bắp bò, riêu cua và rau.','Vietnamese',6,'Nồi lẩu riêu cua đồng sôi sùng sục, nhúng sườn sụn giòn sần sật, bắp bò hoa tươi rói và đĩa rau muống hoa chuối.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/736x/f7/71/2c/f7712cfc1df430a0d2810c0bcdea2cae.jpg','https://www.youtube.com/results?search_query=L%E1%BA%A9u+Ri%C3%AAu+Cua+B%E1%BA%AFp+B%C3%B2+S%C6%B0%E1%BB%9Dn+S%E1%BB%A5n',11,'2026-09-23 00:15:04'),(99,'Gà Hấp Muối Hột Lá Chuối',60,'Bước 1: Sơ chế gà: Làm sạch gà, rửa với nước muối loãng rồi để ráo nước.\nBước 2: Ướp gia vị: Xoa đều gừng, sả, tiêu và bột ngọt lên gà, ướp khoảng 30 phút.\nBước 3: Chuẩn bị nồi hấp: Rải đều muối hột dưới đáy nồi, phủ một lớp sả và lá chanh lên trên\nBước 4: Bọc gà bằng lá chuối: Đặt gà lên lớp lá chuối, bọc kín gà bằng lá chuối để giữ hương thơm.\nBước 5: Hấp gà: Đậy kín nồi và hấp ở lửa vừa khoảng 45–50 phút đến khi gà chín mềm.\nBước 6: Chặt gà và thưởng thức: Lấy gà ra, để nguội bớt, chặt thành miếng vừa ăn và thưởng thức.','Vietnamese',6,'Gà hấp muối hột lá chuối thơm mềm, đậm đà, giữ trọn vị ngọt tự nhiên của thịt gà, hòa quyện cùng hương thơm đặc trưng của lá chuối và gia vị.','Sơ chế gà → Ướp gia vị → Chuẩn bị nồi hấp → Bọc gà bằng lá chuối → Hấp gà → Chặt gà và thưởng thức','recipe_1790868084_993.jpg','',12,'2026-09-23 00:15:04'),(100,'Bánh Giò Nóng Thịt Băm Mộc Nhĩ',60,'Bước 1: Chuẩn bị lá chuối: Rửa sạch lá chuối, trụng qua nước nóng cho mềm rồi lau khô.\nBước 2: Làm nhân: Ngâm mềm mộc nhĩ, thái nhỏ rồi trộn với thịt heo xay, hành tím, nước mắm, đường và tiêu.\nBước 3: Xào nhân: Phi thơm hành với dầu ăn, cho hỗn hợp thịt vào xào chín và nêm vừa ăn.\nBước 4: Nấu bột: Hòa bột gạo và bột năng với nước, thêm muối rồi khuấy trên lửa nhỏ đến khi bột đặc sánh và mịn.\nBước 5: Gói bánh: Trải lá chuối, cho một lớp bột vào giữa, thêm nhân thịt rồi phủ kín bằng một lớp bột khác và gói thành hình bánh giò.\nBước 6: Hấp bánh: Xếp bánh vào xửng và hấp khoảng 30–40 phút cho bánh chín hoàn toàn.\nBước 7: Hoàn thiện và thưởng thức: Lấy bánh ra, để nguội nhẹ rồi thưởng thức khi còn nóng cùng tương ớt hoặc dưa góp.','Vietnamese',6,'Bánh giò nóng với lớp bột mềm mịn, nhân thịt băm đậm đà kết hợp mộc nhĩ giòn thơm, gói trong lá chuối và hấp chín.','Chuẩn bị lá chuối → Làm nhân → Nấu bột → Gói bánh → Hấp bánh → Hoàn thiện và thưởng thức.','recipe_1790872554_828.jpg','https://www.youtube.com/results?search_query=bánh+giò+nóng+thịt+băm+mộc+nhĩ+recipe',13,'2026-09-23 00:15:04'),(101,'Gỏi Tai Heo Dưa Leo Giòn Sần Sật',35,'Bước 1: Tai heo làm sạch, chà với muối và chanh rồi rửa lại. Luộc tai heo trong nước sôi khoảng 12–15 phút cho vừa chín tới, sau đó ngâm ngay vào nước lạnh để giữ độ giòn.\nBước 2: Tai heo để ráo rồi thái lát thật mỏng. Dưa leo bổ đôi, bỏ bớt phần ruột nhiều nước rồi thái lát. Cà rốt bào sợi, hành tây thái mỏng và rau răm cắt nhỏ.\nBước 3: Trộn nước mắm, đường, nước cốt chanh và một ít ớt băm theo khẩu vị. Khuấy đến khi đường tan hoàn toàn.\nBước 4: Cho tai heo, dưa leo, cà rốt và hành tây vào tô lớn. Rưới nước trộn từ từ rồi đảo nhẹ để nguyên liệu thấm đều.\nBước 5: Cho rau răm vào trộn nhanh. Nêm lại vị chua, cay, mặn, ngọt cho cân bằng.\nBước 6: Bày gỏi ra đĩa, rắc đậu phộng rang lên trên và dùng ngay để giữ được độ giòn của tai heo và dưa leo.','Vietnamese',6,'Gỏi tai heo dưa leo là món khai vị có vị chua ngọt, thanh mát và đặc biệt hấp dẫn nhờ độ giòn sần sật của tai heo kết hợp với dưa leo. Nước trộn đậm đà giúp cân bằng vị béo và làm món ăn trở nên dễ ăn.','Luộc tai heo → Thái tai heo & rau củ → Pha nước trộn → Trộn gỏi → Trang trí & thưởng thức','recipe_1790851303_877.jpg','https://youtu.be/ciK-_323z0E?si=t8CYQRiMzPD8RNtZ',4,'2026-09-23 00:15:04'),(102,'Bún Cá Chấm Hải Phòng',45,'Bước 1: Cá phi lê rửa sạch, thấm khô, cắt miếng vừa ăn và ướp nhẹ với muối, tiêu. Dọc mùng tước vỏ, thái lát, bóp muối rồi rửa sạch. Cà chua bổ múi cau, thì là cắt nhỏ.\nBước 2: Áo cá bằng một lớp bột chiên giòn mỏng. Chiên trong dầu nóng đến khi cá vàng giòn hai mặt, sau đó vớt ra để ráo dầu.\nBước 3: Xào cà chua với hành rồi thêm nước. Nêm nước mắm, muối, đường và một chút dấm hoặc me để tạo vị chua nhẹ. Cho dọc mùng vào nấu nhanh rồi thêm thì là.\nBước 4: Pha nước mắm với đường, nước lọc, nước cốt chanh và ớt băm. Khuấy đều đến khi có vị mặn, ngọt, chua cay cân bằng.\nBước 5: Cho bún và rau vào tô, dùng cá chiên giòn riêng bên cạnh. Ăn cá chấm cùng nước mắm pha và dùng kèm nước dùng nóng.','Vietnamese',6,'Bún cá chấm Hải Phòng nổi bật với cá được chiên vàng giòn, ăn kèm bún, rau và nước chấm đậm đà. Cá có lớp ngoài giòn thơm, bên trong mềm, kết hợp cùng nước chấm chua ngọt tạo nên hương vị đặc trưng của món ăn đất cảng.','Sơ chế cá & rau → Chiên cá giòn → Nấu nước dùng → Pha nước chấm → Bày món & thưởng thức','recipe_1790855997_281.jpeg','https://www.youtube.com/results?search_query=B%C3%BAn+C%C3%A1+Ch%E1%BA%A5m+H%E1%BA%A3i+Ph%C3%B2ng',5,'2026-09-23 00:15:04'),(106,'Chè Bưởi An Giang Giòn Sần Sật',60,'Bước 1: Gọt bỏ phần vỏ xanh và phần cùi trắng xốp bên trong, chỉ giữ lại phần cùi bưởi trắng rồi cắt thành những miếng vuông nhỏ vừa ăn.\nBước 2: Bóp cùi bưởi với khoảng 1 thìa cà phê muối và một ít nước trong vài phút, sau đó xả sạch nhiều lần để loại bỏ vị đắng.\nBước 3: Luộc cùi bưởi trong nước sôi khoảng 5 phút, vớt ra ngâm vào nước lạnh rồi vắt thật ráo nước.\nBước 4: Trộn cùi bưởi với khoảng 50g đường, để khoảng 10 phút cho đường thấm rồi cho bột năng và bột gạo vào trộn đều để từng miếng cùi được phủ một lớp bột mỏng.\nBước 5: Đun sôi một nồi nước, cho cùi bưởi đã áo bột vào luộc đến khi lớp bột bên ngoài trở nên trong và cùi bưởi nổi lên thì vớt ra ngâm ngay vào nước lạnh.\nBước 6: Đậu xanh ngâm nước khoảng 2–3 giờ, sau đó hấp hoặc nấu chín đến khi mềm nhưng vẫn còn nguyên hạt.\nBước 7: Đun 800ml nước với lá dứa, thêm phần đường còn lại và một chút muối, khuấy đều rồi cho đậu xanh đã chín vào nấu khoảng 5 phút.\nBước 8: Cho phần cùi bưởi đã luộc vào nồi chè, khuấy nhẹ và nấu thêm 3–5 phút để các nguyên liệu hòa quyện, sau đó thêm vani rồi tắt bếp.\nBước 9: Đun nước cốt dừa với 30g đường và một chút muối ở lửa nhỏ, khuấy đều đến khi nóng và hơi sánh thì tắt bếp.\nBước 10: Múc chè bưởi ra chén, chan nước cốt dừa lên trên và thưởng thức nóng hoặc để nguội rồi thêm đá.','Vietnamese',6,'Chè bưởi với cùi bưởi giòn sần sật, áo lớp bột năng dai nhẹ, nấu cùng đậu xanh và nước cốt dừa béo thơm.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','recipe_1790953306_395.jpg','https://www.youtube.com/results?search_query=Ch%C3%A8+B%C6%B0%E1%BB%9Fi+An+Giang+Gi%C3%B2n+S%E1%BA%A7n+S%E1%BA%ADt',9,'2026-09-23 00:15:04'),(107,'Chè Ba Màu Nước Cốt Dừa',30,'Bước 1: Nấu mềm đậu đỏ với đường; nấu chín đậu xanh rồi tán nhuyễn với đường. Nấu thạch lá dứa, để nguội cho đông lại rồi cắt sợi ngắn hoặc hạt lựu.\nBước 2: Nấu ấm nước cốt dừa với đường, chút muối và bột năng/bột bắp cho sệt nhẹ, để nguội.\nBước 3: Múc lần lượt vào ly một lớp đậu xanh, một lớp đậu đỏ, một lớp thạch lá dứa, thêm đá nhuyễn và rưới nước cốt dừa lên trên.','Vietnamese',6,'Ly chè ba màu gồm đậu đỏ ngọt bùi, đậu xanh dẻo thơm và thạch lá dứa giòn mát chan nước cốt dừa đá nhuyễn mát lạnh.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/1200x/00/a2/6d/00a26ddcf2c98c167913ca2eb90beab6.jpg','https://www.youtube.com/results?search_query=Ch%C3%A8+Ba+M%C3%A0u+N%C6%B0%E1%BB%9Bc+C%E1%BB%91t+D%E1%BB%ABa',10,'2026-09-23 00:15:04'),(108,'Bánh Bò Nướng Nước Cốt Dừa Rễ Tre',45,'Bước 1: Đun ấm nước cốt dừa, nước cốt lá dứa và đường cho tan hoàn toàn rồi để nguội.\nBước 2: Đánh tan nhẹ trứng gà (không đánh bông), đổ nước cốt dừa nguội vào khuấy đều. Rây bột năng, bột gạo và bột nở vào trộn đều, lọc qua rây.\nBước 3: Làm nóng khuôn và lò ở 180°C trước 10 phút, thoa dầu vào khuôn rồi rót bột qua rây vào khuôn nóng để tạo rễ tre; nướng ở 175°C trong 40–45 phút.','Vietnamese',6,'Bánh bò nướng nở rễ tre xốp mềm thơm mùi lá dứa và béo ngậy vị nước cốt dừa nướng vàng óng thơm phức.','Sơ chế nguyên liệu -> Tẩm ướp gia vị -> Nấu chín thơm -> Trình bày và thưởng thức','https://i.pinimg.com/736x/0d/d8/0f/0dd80fd7ef11a387d923f3641c908b7a.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+B%C3%B2+N%C6%B0%E1%BB%9Bng+N%C6%B0%E1%BB%9Bc+C%E1%BB%91t+D%E1%BB%ABa+R%E1%BB%85+Tre',11,'2026-09-23 00:15:04'),(109,'Cà Phê Muối Xứ Huế Thơm Béo',10,'Bước 1: Pha cà phê: Cho cà phê bột vào phin, thêm nước nóng và chờ cà phê nhỏ giọt, thu khoảng 50–60ml cà phê.\nBước 2: Làm kem muối: Đánh whipping cream với sữa đặc, đường và một chút muối đến khi hỗn hợp sánh mịn.\nBước 3: Thêm sữa: Cho sữa đặc và sữa tươi vào ly cà phê, khuấy đều để hòa quyện\nBước 4: Cho đá: Thêm đá viên vào ly cà phê tùy khẩu vị.\nBước 5: Phủ kem muối: Nhẹ nhàng cho lớp kem muối lên trên bề mặt cà phê.\nBước 6: Thưởng thức: Khuấy nhẹ để hòa quyện vị cà phê đậm đà với lớp kem muối béo mặn rồi thưởng thức.','Drinks',5,'Cà phê muối Xứ Huế đậm đà, thơm nồng hòa quyện cùng lớp kem sữa béo mịn và chút vị mặn nhẹ, tạo nên hương vị hài hòa, độc đáo.','Pha cà phê → Làm kem muối → Thêm sữa → Cho đá → Phủ kem muối → Thưởng thức','recipe_1790867715_801.jpg','https://www.youtube.com/watch?v=5fakDw5WZvM',12,'2026-09-23 00:15:04'),(110,'Trà Đào Cam Sả Tươi Mát',15,'Bước 1: Nấu nước sả: Rửa sạch sả, đập dập rồi đun với 300ml nước khoảng 5 phút để lấy hương thơm.\nBước 2: Pha trà: Cho trà túi lọc vào nước sả nóng, ủ khoảng 3–5 phút rồi lấy túi trà ra.\nBước 3: Chuẩn bị cam và đào: Cam rửa sạch, cắt lát; đào ngâm cắt thành miếng vừa ăn.\nBước 4: Pha trà: Cho đường và nước đào ngâm vào trà, khuấy đều cho tan rồi để nguội bớt.\nBước 5: Thêm cam và đào: Cho lát cam và đào vào ly, sau đó rót phần trà đã pha vào.\nBước 6: Thêm đá: Cho đá viên vào ly, khuấy nhẹ để các nguyên liệu hòa quyện.\nBước 7: Trang trí và thưởng thức: Trang trí bằng một lát cam và nhánh sả, dùng trà khi còn lạnh.','Vietnamese',6,'Trà đào cam sả có vị trà thanh mát, kết hợp vị ngọt thơm của đào, vị chua nhẹ của cam và hương sả dễ chịu, thích hợp dùng lạnh.','Nấu nước sả → Pha trà → Chuẩn bị cam và đào → Pha trà đào cam sả → Thêm đá → Trang trí và thưởng thức.','recipe_1790872387_230.jpg','https://www.youtube.com/results?search_query=trà+đào+cam+sả+recipe',13,'2026-09-23 00:15:04'),(111,'Dal Makhani',40,'Bước 1: Cho đỗ đen và đậu thận đỏ đã ngâm vào nồi (ưu tiên nồi áp suất) cùng gia vị nguyên hạt ở mục B, 1/2 thìa cà phê muối và khoảng 800ml nước. Ninh đỗ chín thật mềm rục (khoảng 5 - 6 lần xả van với nồi áp suất).\nBước 2: Đun chảy 25g bơ nhạt trên chảo. Cho gừng tỏi băm vào phi thơm, sau đó cho cà chua xay nhuyễn và bột ớt Kashmiri vào xào ở lửa vừa cho đến khi cà chua chín nhừ, hỗn hợp tách dầu.\nBước 3: Trút toàn bộ phần đỗ đã ninh nhừ (cả phần nước ninh) vào chảo sốt cà chua. Dùng thìa gỗ dầm nhẹ một phần hạt đậu để tạo độ sánh. Hạ lửa nhỏ nhất và ninh chầm chậm trong 30 - 45 phút, khuấy đều tay tránh cháy đáy.\nBước 4: Cho phần bơ nhạt còn lại (25g), kem tươi, bột Garam Masala và lá Kasuri Methi vò nát vào. Khuấy nhẹ nhàng trên lửa nhỏ thêm 5 phút cho các hương vị hòa quyện rồi tắt bếp.\nBước 5: Múc Dal Makhani ra bát sâu lòng, rưới nhẹ một dải kem tươi lên bề mặt trang trí. Dùng nóng kèm với bánh mì Naan tỏi hoặc cơm Biryani.','NorthIndian',1,'Như một nét phác họa ấm áp và êm dịu từ vùng Bắc Ấn, Dal Makhani là hiện thân của sự sang trọng, tinh tế trong nghệ thuật ninh nấu chầm chậm (Slow-cooking).','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790870401_955.jpg','',3,'2026-09-23 00:15:04'),(113,'Chicken Tikka Masala',50,'Bước 1: Gà cắt miếng vừa ăn, trộn với sữa chua, gừng tỏi, garam masala, một ít nghệ, muối và dầu. Ướp khoảng 30 phút.\nBước 2: Làm nóng chảo, cho gà vào áp chảo trên lửa vừa lớn đến khi các mặt vàng xém và thịt gần chín. Không nên chiên quá lâu để tránh làm gà bị khô.\nBước 3: Phi hành tây với dầu đến khi mềm, thêm gừng tỏi rồi đảo thơm. Cho cà chua xay vào và nấu đến khi sốt đặc lại. Thêm garam masala và gia vị.\nBước 4: Cho gà đã áp chảo vào sốt, hạ lửa nhỏ và nấu khoảng 8–10 phút để gà chín hoàn toàn và thấm sốt.\nBước 5: Thêm kem tươi, khuấy nhẹ và nấu thêm 2–3 phút. Rắc rau mùi lên trên và dùng nóng với cơm basmati hoặc naan.','NorthIndian',1,'Chicken Tikka Masala gồm những miếng gà được ướp sữa chua và gia vị, áp chảo hoặc nướng thơm rồi nấu trong sốt cà chua béo nhẹ. Món có màu đỏ cam đặc trưng, thơm garam masala và phù hợp ăn cùng cơm hoặc bánh naan.','Ướp gà → Áp chảo gà → Nấu sốt → Om gà với sốt → Hoàn thiện & thưởng thức','recipe_1790855855_636.jpeg','https://www.youtube.com/results?search_query=Chicken+Tikka+Masala',5,'2026-09-23 00:15:04'),(116,'Garlic Naan Bread',20,'Bước 1: Trộn đều bột mì, men nở, đường, muối, sữa chua và nước ấm, nhào thành khối mịn dẻo rồi ủ nở gấp đôi (khoảng 45–60 phút).\nBước 2: Chia bột thành các phần nhỏ, cán mỏng thành hình bầu dục.\nBước 3: Áp chảo khô trên lửa vừa–lớn đến khi nổi bọng khí phồng to và xém vàng hai mặt, lấy ra quết ngay bơ tỏi lên bề mặt rồi thưởng thức nóng.','NorthIndian',1,'Bánh mì naan nướng bơ tỏi giòn xốp.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/1200x/1c/a6/c1/1ca6c100275644142a7e9efb099a59da.jpg','',10,'2026-09-23 00:15:04'),(117,'Chole Bhature',45,'Bước 1: Bước 1: Nấu đậu gà (Chole)\r\nCho đậu gà đã ngâm vào nồi áp suất cùng với 1 túi trà lọc, lá nguyệt quế, quế, bạch đậu khấu và chút muối.\r\n\r\nNinh khoảng 15–20 phút (hoặc đun nồi thường 45–60 phút) cho đậu gà chín mềm nhừ. Sau khi chín, vớt túi trà ra.\r\n\r\nPhi thơm hành tây băm, gừng tỏi băm với dầu ăn trên chảo. Cho cà chua xay vào xào đến khi cạn nước và tách dầu.\r\n\r\nCho toàn bộ bột gia vị (ớt, nghệ, Garam Masala, thì là, rau mùi, xoài khô) vào đảo đều trong 1 phút.\r\n\r\nTrút toàn bộ đậu gà (bao gồm cả phần nước ninh đậu) vào chảo gia vị, dầm nát nhẹ một ít hạt đậu để nước sốt sánh đặc hơn.\r\n\r\nĐun lửa nhỏ khoảng 10–15 phút cho ngấm gia vị. Nêm lại muối/chanh cho vừa ăn, rắc rau mùi tươi lên trên.\nBước 2: Bước 2: Làm vỏ bánh (Bhature)\r\nTrong một tô lớn, trộn đều bột mì, bột gạo, bột nở, đường và muối.\r\n\r\nCho sữa chua và 1 thìa dầu ăn vào, từ từ thêm nước ấm nhào thành khối bột mịn, mềm, không dính tay (nhào khoảng 8–10 phút).\r\n\r\nThoa một lớp dầu mỏng quanh khối bột, bọc kín và để bột nghỉ từ 1 đến 2 tiếng.\r\n\r\nSau khi nghỉ, chia bột thành các viên nhỏ cỡ quả trứng golf. Cán viên bột thành hình tròn hoặc hình bầu dục, độ dày khoảng 2–3mm.\nBước 3: Bước 3: Chiên bánh Bhature\r\nĐun nóng nhiều dầu trong chảo sâu lòng (dầu phải thật nóng).\r\n\r\nThả lá bột đã cán vào chảo. Dùng vá thủng ấn nhẹ bề mặt bánh xuống dầu vài giây để bánh phồng to như quả bóng.\r\n\r\nTrở mặt bánh chiên vàng đều 2 mặt rồi vớt ra ráo dầu.','NorthIndian',1,'Đậu gà cay ăn kèm bánh mì phồng chiên giòn.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790865161_314.jpg','',2,'2026-09-23 00:15:04'),(118,'Chicken Korma',40,'Bước 1: Sơ chế gà: Rửa sạch thịt gà, để ráo và cắt thành miếng vừa ăn.\nBước 2: Ướp gà: Trộn gà với sữa chua, bột nghệ, một ít garam masala và muối, ướp khoảng 30 phút.\nBước 3: Xào hành và gia vị: Phi thơm gừng, tỏi với dầu ăn, cho hành tây vào xào đến khi mềm và vàng nhẹ.\nBước 4: Nấu gà: Cho gà đã ướp vào xào săn, thêm nước rồi đậy nắp nấu khoảng 20 phút.\nBước 5: Thêm sốt kem hạt điều: Xay hạt điều với một ít nước thành hỗn hợp mịn, cho vào nồi cùng kem tươi và phần garam masala còn lại, nấu đến khi sốt sánh.\nBước 6: Hoàn thiện: Nêm lại gia vị cho vừa ăn, nấu thêm vài phút rồi tắt bếp.\nBước 7: Thưởng thức: Rắc rau mùi lên trên và dùng Chicken Korma nóng cùng cơm hoặc bánh naan.','NorthIndian',1,'Chicken Korma là món cà ri gà kiểu Nam Á với thịt gà mềm thơm, sốt kem béo mịn, kết hợp cùng các loại gia vị và hạt điều tạo nên hương vị đậm đà, thơm nhẹ.','Sơ chế gà → Ướp gà → Xào hành và gia vị → Nấu gà → Thêm sốt kem hạt điều → Hoàn thiện và thưởng thức','recipe_1790872158_180.jpg','https://www.youtube.com/results?search_query=Chicken+Korma+recipe+Indian',13,'2026-09-23 00:15:04'),(119,'Mutton Biryani',60,'Bước 1: Thịt cừu cắt miếng vừa ăn, trộn với sữa chua, gừng tỏi, bột biryani, muối và một ít nước cốt chanh. Ướp ít nhất 1 giờ để thịt thấm gia vị.\nBước 2: Vo và ngâm gạo basmati khoảng 20–30 phút. Luộc gạo với nước và một ít muối đến khi hạt chín khoảng 70%, sau đó vớt ra để ráo.\nBước 3: Phi thơm hành tây, cho thịt cừu vào xào săn. Thêm cà chua và một ít nước, đậy nắp nấu ở lửa nhỏ đến khi thịt mềm và phần sốt cô lại.\nBước 4: Trải một lớp cơm basmati lên phần thịt, tiếp tục xếp xen kẽ thịt và cơm nếu dùng nồi sâu. Có thể rắc thêm hành phi hoặc rau mùi giữa các lớp.\nBước 5: Đậy kín nắp, nấu lửa nhỏ khoảng 20–25 phút. Khi cơm chín, xới nhẹ từ dưới lên để trộn các lớp. Dùng nóng cùng raita hoặc sữa chua.','NorthIndian',1,'Mutton Biryani là món cơm cừu đặc trưng của ẩm thực Ấn Độ, nổi bật với hạt gạo basmati tơi, thịt cừu mềm và hương thơm mạnh của các loại gia vị. Cơm được nấu theo từng lớp để thịt và gạo thấm đều gia vị.','Ướp thịt → Sơ chế & luộc gạo → Nấu thịt → Xếp lớp → Om cơm & thưởng thức','recipe_1790855652_150.jpg','https://www.youtube.com/results?search_query=+MUTTON+BIRYANI',5,'2026-09-23 00:15:04'),(120,'Samosa Chaat',25,'Bước 1: Nấu nhừ gạo, đậu lăng và rau củ cùng nước và bột nghệ trong nồi áp suất hoặc nồi thường (dạng như cháo đặc).\nBước 2: Hòa bột Bisi Bele Bath và nước cốt me vào nồi cơm đậu, nêm muối vừa ăn, đun sôi nhỏ lửa 5–7 phút cho hòa quyện.\nBước 3: Phi thơm hạt mù tạt và lá cà ri với bơ ghee, đổ thẳng vào nồi cơm khuấy đều rồi tắt bếp.','NorthIndian',1,'Bánh gối nhân khoai tây đậu hà lan sốt me cay.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/1200x/7b/20/08/7b2008cb12ec1f7b6b69512bbb9deab3.jpg','',11,'2026-09-23 00:15:04'),(121,'Rava Dosa',30,'Bước 1: Cho bột semolina, bột gạo, bột mì và muối vào tô, trộn đều rồi từ từ thêm nước, khuấy đến khi thu được hỗn hợp bột khá loãng.\nBước 2: Hành tây, ớt xanh, gừng và rau mùi băm nhỏ, sau đó cho vào hỗn hợp bột cùng hạt thì là và tiêu đen.\nBước 3: Để bột nghỉ khoảng 15–20 phút, sau đó kiểm tra và thêm nước nếu bột đặc vì Rava Dosa cần hỗn hợp loãng để tạo lớp bánh mỏng giòn.\nBước 4: Làm nóng chảo chống dính hoặc chảo gang ở lửa vừa đến lớn, sau đó phết một lớp dầu mỏng lên mặt chảo.\nBước 5: Khuấy đều bột rồi dùng muôi rưới bột từ ngoài vào trong lên chảo, không cần dùng muôi dàn bột như khi làm dosa thông thường.\nBước 6: Rưới một ít dầu quanh mép bánh và lên các phần bột còn ướt, chiên khoảng 2–3 phút đến khi mặt dưới vàng nâu và giòn.\nBước 7: Khi bánh đã giòn, nhẹ nhàng gỡ bánh khỏi chảo rồi gấp đôi hoặc gấp thành hình tam giác\nBước 8: Làm tương tự với phần bột còn lại và thưởng thức Rava Dosa nóng cùng Coconut Chutney hoặc sambar.','SouthIndian',2,'Rava Dosa là món bánh crepe giòn kiểu Nam Ấn, làm từ semolina (rava), bột gạo và bột mì, có kết cấu mỏng, giòn và thơm nhẹ gia vị.','Pha bột → Chuẩn bị gia vị → Ủ bột → Làm nóng chảo → Tráng bột mỏng → Chiên giòn → Gấp bánh và thưởng thức.','recipe_1790953022_117.jpg','',9,'2026-09-23 00:15:04'),(122,'Medu Vada',40,'Bước 1: Ngâm đậu: Rửa sạch đậu urad dal rồi ngâm trong nước khoảng 4–6 giờ cho đậu mềm.\nBước 2: Xay đậu: Chắt bỏ nước, xay đậu cùng một ít nước thành hỗn hợp bột đặc, mịn và hơi xốp.\nBước 3: Trộn gia vị: Trộn bột đậu với gừng, ớt xanh, hành tây, lá cà ri, rau mùi, tiêu và muối.\nBước 4: Tạo hình: Làm ướt tay, lấy một phần bột, vo tròn rồi tạo một lỗ nhỏ ở giữa để tạo hình bánh vada.\nBước 5: Chiên bánh: Đun nóng dầu, nhẹ nhàng cho bánh vào chiên ở lửa vừa đến khi bánh vàng giòn hai mặt.\nBước 6: Để ráo dầu: Vớt bánh ra, đặt lên giấy thấm dầu để loại bỏ dầu thừa.\nBước 7: Thưởng thức: Dùng Medu Vada khi còn nóng, ăn kèm chutney dừa hoặc sambar.','SouthIndian',2,'Medu Vada là bánh chiên truyền thống của Nam Ấn, có lớp ngoài vàng giòn, bên trong mềm xốp, thơm nhẹ mùi đậu lăng và các loại gia vị.','Ngâm đậu → Xay đậu → Trộn gia vị → Tạo hình → Chiên bánh → Để ráo dầu và thưởng thức','recipe_1790871826_463.jpg','https://www.youtube.com/results?search_query=Medu+Vada+recipe+South+Indian',13,'2026-09-23 00:15:04'),(123,'Hyderabadi Dum Biryani',60,'Bước 1: Trộn đều thịt với tất cả gia vị trong mục A (sữa chua, hành phi, gừng tỏi, bột ớt, garam masala, lá thơm...). Trộn thật kỹ và bọc kín, ướp trong tủ lạnh ít nhất 2 - 4 tiếng (hoặc qua đêm).\nBước 2: Đun sôi khoảng 2 lít nước cùng toàn bộ gia vị nguyên hạt ở mục B và 2 thìa canh muối. Cho gạo Basmati đã ngâm vào luộc trong khoảng 6 - 7 phút. Khi hạt gạo cắn vào còn hơi cứng ở lõi (chín khoảng 70%), vớt ra để ráo.\nBước 3: Hoàn thiện món ăn thơm ngon và thưởng thức cùng bạn bè.Xếp toàn bộ phần thịt đã ướp xuống đáy nồi đáy dày (hoặc nồi đất). Rải đều lớp gạo Basmati chín 70% lên trên. Rưới đều nước sữa nghệ tây, bơ Ghee, nước Kewra, rắc thêm chút hành phi, lá bạc hà và lá mùi lên bề mặt.\nBước 4: Dùng khối bột mì miết kín quanh mép nồi rồi đậy nắp lại (hoặc phủ giấy bạc thật kín trước khi đậy nắp).\r\n\r\n10 phút đầu: Đun ở lửa vừa-to.\r\n\r\n20 - 25 phút sau: Hạ lửa xuống mức nhỏ nhất (có thể đặt thêm tấm lót tản nhiệt dưới đáy nồi).\r\nTắt bếp và giữ nguyên không mở nắp trong 10 - 15 phút cho hơi nóng phân bổ đều.\nBước 5: Mở nắp, xới nhẹ nhàng từ đáy lên để hạt gạo không bị gãy vỡ. Thưởng thức nóng kèm với sốt Raita (sữa chua dưa chuột) hoặc sốt Salan.','SouthIndian',2,'Tựa như một bức tranh ẩm thực kiệt tác đến từ hoàng gia Ấn Độ, Hyderabadi Dum Biryani là sự hòa quyện đỉnh cao giữa nghệ thuật gia vị bí truyền và phương pháp nấu ủ chầm chậm (Dum).','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790869815_342.jpg','',3,'2026-09-23 00:15:04'),(124,'Chettinad Pepper Chicken',40,'Bước 1: Sơ chế gà: Rửa sạch thịt gà, để ráo rồi cắt thành miếng vừa ăn.\nBước 2: Ướp gà: Ướp gà với nghệ, muối, nước cốt chanh và một ít tiêu đen trong khoảng 20 phút.\nBước 3: Rang gia vị: Rang khô tiêu đen, hạt thì là, hạt rau mùi và ớt khô đến khi dậy mùi thơm rồi giã hoặc xay nhỏ.\nBước 4: Xào gia vị: Phi thơm gừng, tỏi, hành tây và lá cà ri với dầu ăn, sau đó cho cà chua vào xào mềm\nBước 5: Nấu gà: Cho gà đã ướp vào xào săn, thêm hỗn hợp gia vị rang và một ít nước, đậy nắp nấu khoảng 20–25 phút.\nBước 6: Hoàn thiện: Mở nắp, đảo đều và nấu thêm vài phút đến khi sốt sánh lại, gà chín mềm và thơm nồng\nBước 7: Thưởng thức: Cho gà ra đĩa, rắc thêm tiêu đen và dùng nóng cùng cơm hoặc bánh mì.','SouthIndian',2,'Chettinad Pepper Chicken là món gà kiểu Nam Ấn đậm đà, thơm nồng với tiêu đen, các loại gia vị đặc trưng và chút cay ấm, tạo nên hương vị hấp dẫn.','Sơ chế gà → Ướp gà → Rang gia vị → Xào gia vị → Nấu gà → Hoàn thiện và thưởng thức','recipe_1790871445_623.jpg','https://www.youtube.com/results?search_query=Chettinad+Pepper+Chicken+recipe',13,'2026-09-23 00:15:04'),(125,'Coconut Chutney',20,'Bước 1: 1. Chuẩn bị nguyên liệu: Dừa nạo, ớt xanh và gừng rửa sạch. Chuẩn bị sẵn đậu rang, muối và các loại gia vị dùng cho phần tempering.\nBước 2: 2. Xay chutney: Cho dừa nạo, ớt xanh, gừng, đậu rang, muối và khoảng 50ml nước vào máy xay. Xay đến khi hỗn hợp mịn, sau đó thêm nước từ từ để đạt độ sánh mong muốn.\nBước 3: 3. Điều chỉnh gia vị: Cho chutney ra bát, nếm và điều chỉnh lượng muối hoặc nước để có độ đặc vừa phải, không quá loãng.\nBước 4: 4. Làm tempering: Đun nóng dầu trong chảo nhỏ, cho hạt mù tạt vào. Khi hạt bắt đầu nổ, thêm hạt thì là, lá cà ri, ớt khô và một chút asafoetida.\nBước 5: 5. Kết hợp: Đổ phần gia vị tempering nóng lên trên chutney dừa. Trộn nhẹ để dầu thơm và các loại gia vị hòa quyện với hỗn hợp dừa.\nBước 6: 6. Hoàn thành: Để chutney nghỉ khoảng 2–3 phút cho gia vị thấm rồi khuấy nhẹ lần cuối.\nBước 7: 7. Thưởng thức: Dùng Coconut Chutney làm nước chấm cùng dosa, idli, vada hoặc các món ăn Nam Ấn khác.','SouthIndian',2,'Nước chấm kiểu Nam Ấn làm từ dừa tươi xay nhuyễn, kết hợp cùng đậu lăng, ớt xanh và gia vị, có vị béo nhẹ, thơm và cay dịu. Thường được dùng kèm dosa, idli và vada.','Chuẩn bị nguyên liệu → Xay hỗn hợp dừa → Nêm gia vị → Làm phần tempering → Trộn tempering với chutney → Hoàn thành và thưởng thức.','recipe_1790952776_767.jpg','',9,'2026-09-23 00:15:04'),(126,'Mứt khoai lang',40,'Bước 1: Sơ chế khoai lang: Khoai lang gọt vỏ, rửa sạch, cắt thành lát hoặc miếng vừa ăn. Độ dày chỉ khoảng 1 cm là được bạn nhé. Sử dụng vôi sống ngâm vào nước, lọc phần nước trong khi vô đã lắng hết cặn ở dưới. Thả các miếng khoai lang vừa cắt vào nước vô trong trong khoảng 5 tiếng. Bạn lưu ý là nước vô phải ngập trong nước nhé. Sau đó, vớt khoai lang ra, rửa lại với nước sạch nhiều lần để bỏ đi mùi vôi. Đây là bước quan trọng để khoai lang cứng hơn, khi sên mứt, khoai không bị nát.\nBước 2: Ướp  khoai lang: Ướp khoai lang với đường theo tỉ lệ 2:1. Cứ 1kg khoai là 500gr đường. Thi thoảng dùng đũa dảo đều để đường thấm đều vào khoai. Khi thấy đường đã tan hết (5h sau) thì bạn mới bắt đầu đến bước xao khoai lang\nBước 3: Xao khoai lang: Đặt chảo lên bếp, đợi chảo nóng rồi cho hỗn hợp đường và khoai vào, đun với lửa vừa, thi thoảng đảo qua mứt cho khoai lang không bị sém và mứt được ngấm đường. Khi đường bắt đầu sền sệt thì giảm nhỏ lửa, để lửa liu riu và dùng đũa đảo đều liên tục. Khi khoai lang khô đều, đường trắng kết tinh vào từng lát khoai lang thì bạn cho vanilla vào tạo mùi thơm ngon, béo ngậy cho mứt, nhanh tay đảo thêm một vài lần rồi nhấc chảo xuống. Như vậy, bạn đã hoàn thành cách làm mứt khoai lang deo dẻo, bùi thơm rồi. Khi mứt còn đang nóng cần để một lúc cho nguội hẳn, bỏ vào lọ kín để bảo quản mứt được lâu hơn nhé.','Vietnamese',6,'Không chỉ có chứa nhiều tinh bột, chất xơ, vitamin mà khoai lang còn là món ăn hấp dẫn được biến tấu thành nhiều phiên bản khác nhau như khoai lang chiên giòn, khoai lang luộc, khoai lang lắc… Đặc biệt, món mứt khoai lang dẻo ngọt cho ngày tết sẽ khiến bạn mê ly. Vậy tại sao chúng ta không thử với cách làm mứt khoai lang nhâm nhi vào những ngày tết nguyên đán này nhỉ?','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790866830_922.webp','',6,'2026-09-23 00:15:04'),(127,'Cháo sườn heo',120,'Bước 1: Bước 1: Sơ chế gạo và rau thơm: Trộn lẫn gạo tẻ và gạo nếp, vo sạch rồi ngâm nước trong khoảng 4 – 5 tiếng cho gạo mềm và nở đều, giúp cháo nhanh nhừ hơn khi nấu. Nhặt và rửa sạch mùi tàu, hành hoa, sau đó thái nhỏ hoặc cắt khúc vừa ăn.\nBước 2: Bước 2: Sơ chế và ninh mềm sườn heo: Sườn heo rửa sạch, chặt khúc khoảng 3 – 4 cm, chần qua nước sôi 2 – 3 phút để loại bỏ tạp chất và mùi hôi, sau đó vớt ra rửa lại với nước. Cho sườn vào nồi nước mới cùng một củ hành tím thái lát, ninh thật nhừ trong khoảng 30 – 40 phút. Vớt sườn ra, tách lấy phần thịt, có thể giã hoặc xay nhỏ tùy theo sở thích (hoặc để nguyên miếng nếu thích ăn nguyên bản).\nBước 3: Bước 3: Nấu cháo sườn bằng nồi cơm điện: Cho phần gạo đã ngâm vào nồi cơm điện cùng lượng nước thích hợp (nên dùng nước ấm từ 40 – 50°C) và thêm 1 muỗng canh dầu ăn để cháo không bị trào khi sôi. Bật chế độ nấu (Cook) khoảng 20 phút, sau đó chuyển sang chế độ giữ ấm (Warm) và ủ trong vòng 30 phút để cháo nhuyễn mịn.\nBước 4: Bước 4: Hoàn thành và thưởng thức: Khi cháo đã chín nhừ, cho phần thịt sườn vào nồi, nêm nếm gia vị lại cho vừa ăn và đun nóng thêm 7 – 10 phút. Thêm hành hoa và mùi tàu vào, đảo đều rồi tắt bếp. Múc cháo ra tô, dùng nóng kèm với quẩy rán hoặc ruốc thịt để món ăn thêm phần trọn vị.','Vietnamese',6,'Cháo sườn heo là một món cháo được nhiều người yêu thích bởi không chỉ mang đến vị ngon ngọt đặc trưng mà còn có giá trị dinh dưỡng dồi dào từ xương và thịt. Món cháo này là lựa chọn hàng đầu của các bà mẹ khi muốn chăm sóc các bé bằng những món ăn thơm ngon, bổ dưỡng.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790852618_696.webp','',6,'2026-09-23 00:15:04'),(128,'Kerala Fish Curry',40,'Bước 1: Phi thơm hành tím, tỏi, gừng và lá cà ri với một ít dầu ăn.\nBước 2: Cho bột nghệ, bột ớt và bột thì là vào đảo nhỏ lửa khoảng 30 giây để dậy mùi.\nBước 3: Cuối cùng hạ lửa nhỏ, rót nước cốt dừa vào khuấy nhẹ, nêm lại muối cho vừa miệng, đun sôi lăn tăn rồi tắt bếp.','SouthIndian',2,'Cà ri cá biển nấu nước cốt dừa quả me kokum.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/1200x/57/a7/90/57a790103d1c017313996cdaa1601cc6.jpg','',10,'2026-09-23 00:15:04'),(131,'Vịt Quay Bắc Kinh',120,'Bước 1: Sơ chế vịt: Làm sạch vịt, dùng gừng và một ít giấm chà lên da để khử mùi, sau đó rửa sạch và để ráo.\nBước 2: Ướp gia vị: Ướp phần bụng vịt với nước tương, đường, ngũ vị hương, gừng, tỏi và hành lá trong khoảng 2–3 giờ.\nBước 3: Làm khô da vịt: Dùng nước nóng dội đều lên phần da vịt, sau đó phết hỗn hợp mật ong và giấm lên da rồi để vịt khô tự nhiên.\nBước 4: Quay vịt: Làm nóng lò ở 180°C, quay vịt khoảng 90–120 phút đến khi da vàng nâu, giòn và thịt chín mềm.\nBước 5: Chặt vịt: Lấy vịt ra khỏi lò, để nghỉ khoảng 10 phút rồi chặt thành từng miếng vừa ăn.\nBước 6: Chuẩn bị ăn kèm: Chuẩn bị bánh tráng mỏng, dưa leo và sốt chấm để dùng cùng vịt quay.\nBước 7: Thưởng thức: Cuốn thịt vịt cùng bánh tráng và chấm với sốt đặc trưng.','Chinese',3,'Vịt quay Bắc Kinh nổi bật với lớp da vàng nâu giòn bóng, thịt vịt mềm thơm, đậm đà, thường ăn kèm bánh tráng mỏng, dưa leo và sốt đặc trưng.','Sơ chế vịt → Ướp gia vị → Làm khô da vịt → Phết mật ong → Quay vịt → Chặt vịt → Thưởng thức','recipe_1790871082_463.jpg','https://www.youtube.com/results?search_query=V%E1%BB%8Bt+quay+B%E1%BA%AFc+Kinh+h%C6%B0%E1%BB%9Bng+d%E1%BA%ABn',13,'2026-09-23 00:15:04'),(132,'Chè cốm đậu xanh',60,'Bước 1: Sơ chế nguyên liệu: Đậu xanh: Vo sạch, đãi bỏ tạp chất, sau đó ngâm nước khoảng 2 tiếng cho mềm rồi vớt ra để ráo. Cốm khô: Sàng nhẹ qua rổ thưa để loại bỏ tạp chất, xả sơ qua nước 2–3 lần, rồi ngâm khoảng 5 phút cho mềm (tránh ngâm quá lâu làm cốm bị nhão). Lá dứa: Rửa sạch, cắt khúc nhỏ, đem xay nhuyễn với một ít nước rồi vắt lấy nước cốt dứa (bỏ bã). Bột sắn dây: Hòa tan bột sắn với một ít nước trong chén để tránh bị vón cục khi nấu.\nBước 2: Bước 2: Chuẩn bị nước cốt dừa: Cho dừa nạo vào tô cùng nước nóng, nhào đều và vắt lấy nước cốt dừa. Đặt nồi nước cốt dừa lên bếp, nêm thêm một chút muối và đường cho vừa ăn, đun sôi nhẹ rồi tắt bếp, để riêng ra chén.\nBước 3: Bước 3: Nấu chè cốm đậu xanh: Cho đậu xanh đã ráo nước vào nồi cùng với 1 lít nước và phần nước cốt lá dứa, nấu với lửa nhỏ cho đến khi đậu xanh chín nhừ. Nêm lượng đường vừa ăn vào nồi đậu, đảo đều tay cho đường tan hoàn toàn. Cho tiếp cốm vào nấu chung. Khi chè sôi trở lại, nêm nếm lại cho vừa khẩu vị. Vừa đổ từ từ chén nước bột sắn dây vào nồi, vừa khuấy nhẹ nhàng đến khi chè chuyển sang độ sánh đặc vừa ý thì tắt bếp.\nBước 4: Bước 4: Hoàn thành và thưởng thức: Múc chè cốm đậu xanh ra chén. Khi chè nguội bớt, rưới phần nước cốt dừa lên trên mặt để tăng độ béo ngậy và thưởng thức cùng gia đình hoặc bạn bè.','Dessert',4,'Chè luôn là món ăn được nhiều người chọn lựa để giải nhiệt trong những ngày nắng nóng bức. Trong đó, món chè cốm phảng phất hương thơm lừng, tươi mát quyện với vị ngọt thanh, bùi bùi chắc chắn sẽ làm cho bạn thích thú và không thể cưỡng lại. Sau đây, hãy cùng Cet.edu.vn tìm hiểu ngay hai cách nấu chè cốm là chè cốm đậu xanh và chè cốm hạt sen đơn giản nhé!','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790851821_148.webp','',6,'2026-09-23 00:15:04'),(133,'Hoành Thánh Tôm Thịt Nước',45,'Bước 1: Sơ chế nguyên liệu: Tôm bóc vỏ, bỏ chỉ lưng rồi băm nhỏ; hành lá và hành tím rửa sạch, băm nhỏ, cải thìa rửa sạch.\nBước 2: Làm nhân: Trộn tôm, thịt heo, hành tím, hành lá, tiêu, nước mắm và dầu mè đến khi nhân kết dính.\nBước 3: Gói hoành thánh: Cho một lượng nhân vừa đủ vào giữa vỏ hoành thánh, gấp và miết mép để tạo hình, làm lần lượt đến hết nhân.\nBước 4: Nấu nước dùng: Hầm xương heo với 1,5 lít nước khoảng 30 phút, vớt bọt và nêm muối, đường, nước mắm cho vừa ăn.\nBước 5: Luộc hoành thánh: Đun sôi nước, cho hoành thánh vào luộc khoảng 4–5 phút đến khi vỏ trong và nhân chín.\nBước 6: Hoàn thiện: Chần cải thìa, cho vào tô cùng hoành thánh, chan nước dùng nóng và rắc hành lá lên trên.\nBước 7: Thưởng thức: Dùng hoành thánh khi còn nóng, có thể thêm tiêu hoặc dầu mè tùy khẩu vị.','Chinese',3,'Hoành thánh tôm thịt nước với lớp vỏ mềm dai, nhân tôm thịt đậm đà, dùng cùng nước dùng trong thanh ngọt và thơm nhẹ.','Sơ chế nguyên liệu → Làm nhân → Gói hoành thánh → Nấu nước dùng → Luộc hoành thánh → Hoàn thiện và thưởng thức','recipe_1790870717_293.jpg','https://www.youtube.com/results?search_query=Ho%C3%A0nh+th%C3%A1nh+t%C3%B4m+th%E1%BB%8Bt+n%C6%B0%E1%BB%9Bc',13,'2026-09-23 00:15:04'),(134,'Mì Xào Giòn Quảng Đông',40,'Bước 1: Mì trứng chần nhanh qua nước sôi rồi vớt ra để thật ráo. Tôm bóc vỏ, bỏ chỉ lưng; thịt heo thái lát mỏng. Cải thìa rửa sạch, cà rốt thái lát và nấm hương ngâm mềm rồi thái nhỏ.\nBước 2: Làm nóng chảo với lượng dầu vừa đủ. Cho mì vào dàn thành lớp đều, chiên ở lửa vừa đến khi mặt dưới vàng giòn thì trở mặt và tiếp tục chiên. Khi mì giòn đều, vớt ra để ráo dầu.\nBước 3: Phi thơm một ít hành tỏi, cho thịt heo và tôm vào xào nhanh trên lửa lớn. Khi tôm vừa chuyển màu, cho cà rốt, nấm hương và cải thìa vào đảo đều.\nBước 4: Thêm nước dùng gà cùng nước tương, dầu hào, một ít đường và tiêu. Đun đến khi rau củ chín tới và phần nước sốt sôi nhẹ.\nBước 5: Hòa một ít bột năng với nước lạnh rồi từ từ cho vào chảo, khuấy đều đến khi nước sốt hơi sánh và bám nhẹ vào nguyên liệu.\nBước 6: Đặt mì giòn lên đĩa, rưới phần nhân và nước sốt nóng lên trên. Dùng ngay để giữ được độ giòn đặc trưng của mì.','Chinese',3,'Mì xào giòn Quảng Đông nổi bật với phần mì trứng được chiên vàng giòn bên ngoài nhưng vẫn giữ độ mềm nhẹ bên trong. Mì được phủ lên trên bởi phần thịt, tôm và rau củ xào cùng nước sốt đậm đà, tạo sự tương phản giữa mì giòn và topping mềm mọng.','Sơ chế nguyên liệu → Chiên mì giòn → Xào thịt hải sản & rau củ → Nấu sốt sánh → Rưới sốt & thưởng thức','recipe_1790851116_139.jpg','https://youtu.be/NH4FmQYtv_I?si=KlWjyYg9CwvOEguL',4,'2026-09-23 00:15:04'),(135,'Xá Xíu Mật Ong',60,'Bước 1: Sơ chế thịt: Rửa sạch thịt heo, để ráo nước và cắt thành từng miếng dài vừa ăn\nBước 2: Ướp thịt: Trộn thịt với nước tương, dầu hào, đường, ngũ vị hương và tỏi băm, ướp khoảng 2–3 giờ.\nBước 3: Nướng thịt: Làm nóng lò ở 180°C, cho thịt vào nướng khoảng 35–40 phút và trở mặt giữa chừng.\nBước 4: Phết mật ong: Lấy thịt ra, phết đều một lớp mật ong lên hai mặt thịt.\nBước 5: Nướng hoàn thiện: Nướng thêm 5–10 phút đến khi thịt chín mềm và có lớp ngoài vàng óng.\nBước 6: Thái lát và thưởng thức: Để thịt nguội bớt, thái thành lát mỏng và thưởng thức cùng cơm hoặc bánh mì.','Vietnamese',6,'Thịt xá xíu mềm thơm, đậm đà với lớp sốt mật ong óng vàng, mang vị ngọt dịu và hương thơm hấp dẫn.','Sơ chế thịt → Ướp thịt → Nướng thịt → Phết mật ong → Nướng hoàn thiện → Thái lát và thưởng thức','recipe_1790867305_317.jpg','https://www.youtube.com/watch?v=B4RwbO9Dujo',12,'2026-09-23 00:15:04'),(138,'Bánh Bao Thượng Hải (Xiao Long Bao)',60,'Bước 1: Da heo làm sạch, luộc sơ rồi ninh với nước và một ít gừng khoảng 1,5–2 giờ. Lọc lấy nước, để nguội rồi làm lạnh đến khi đông thành dạng gelatin. Cắt nhỏ phần gelatin để trộn vào nhân.\nBước 2: Trộn thịt heo xay với gừng băm, hành lá, nước tương, dầu mè và gia vị. Thêm gelatin đã cắt nhỏ rồi trộn đều.\nBước 3: Nhào bột mì với nước ấm thành khối bột mềm, để nghỉ khoảng 20 phút. Chia bột thành viên nhỏ, cán thành miếng tròn mỏng rồi cho nhân vào giữa và gấp mép thành nhiều nếp.\nBước 4: Đặt bánh vào xửng trên giấy nến hoặc lá bắp cải. Hấp trên lửa lớn khoảng 8–10 phút cho đến khi vỏ bánh chín trong và nhân chín hoàn toàn.\nBước 5: Để bánh nghỉ 1–2 phút trước khi lấy ra. Dùng cùng giấm đen và gừng thái sợi. Khi ăn nên mở một lỗ nhỏ trên vỏ để thoát hơi và thưởng thức phần nước súp bên trong.','Chinese',3,'Xiao Long Bao là bánh bao hấp nổi tiếng của Thượng Hải với lớp vỏ mỏng, nhân thịt đậm đà và phần nước súp nóng bên trong. Bánh thường được thưởng thức cùng giấm đen và gừng thái sợi.','Nấu nước súp → Làm nhân → Nhào & cán vỏ → Gói bánh → Hấp & thưởng thức','recipe_1790855468_239.jpeg','https://www.youtube.com/results?search_query=B%C3%81NH+BAO+TH%C6%AF%E1%BB%A2NG+H%E1%BA%A2I+%E2%80%93+XIAO+LONG+BAO',5,'2026-09-23 00:15:04'),(140,'Gà Xào Hạt Điều Cung Bảo',25,'Bước 1: Ướp gà với 1 thìa cà phê nước tương và chút tiêu trong 10 phút.\nBước 2: Phi thơm hành tỏi và ớt khô trên chảo dầu nóng, cho thịt gà vào xào săn trên lửa lớn.\nBước 3: Thêm ớt chuông, rưới bát nước sốt vào đảo đều đến khi sốt sệt bám quanh thịt; tắt bếp rồi thả hạt điều vào đảo nhanh tay là xong.','Chinese',3,'Thịt gà ức xào hạt điều ớt chuông cay ngọt.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/736x/fb/d9/70/fbd9704696f4fed614631b99544abffe.jpg','',10,'2026-09-23 00:15:04'),(141,'Tiramisu Cà Phê Ý',30,'Bước 1: 1. Chuẩn bị cà phê: Pha cà phê espresso hoặc cà phê đen thật đậm, sau đó để nguội. Có thể thêm rượu Marsala hoặc rum để tạo hương vị đặc trưng.\nBước 2: 2. Làm hỗn hợp mascarpone: Tách lòng đỏ và lòng trắng trứng. Đánh lòng đỏ với đường đến khi hỗn hợp chuyển màu vàng nhạt và hơi bông. Thêm mascarpone vào và trộn nhẹ đến khi mịn.\nBước 3: 3. Đánh lòng trắng trứng: Đánh lòng trắng trứng đến khi bông cứng, sau đó nhẹ nhàng trộn vào hỗn hợp mascarpone để tạo độ xốp và mềm cho phần kem.\nBước 4: 4. Nhúng bánh ladyfinger: Nhúng nhanh từng chiếc bánh ladyfinger vào cà phê đã nguội. Không ngâm quá lâu vì bánh sẽ bị nhão.\nBước 5: 5. Xếp lớp đầu tiên: Xếp một lớp bánh ladyfinger đã thấm cà phê vào đáy khuôn.\nBước 6: 6. Thêm lớp kem: Phủ một lớp kem mascarpone lên trên lớp bánh, sau đó dàn đều bề mặt.\nBước 7: 7. Lặp lại các lớp: Tiếp tục xếp một lớp bánh ladyfinger, sau đó thêm một lớp kem mascarpone. Lặp lại cho đến khi hết nguyên liệu, kết thúc bằng lớp kem.\nBước 8: 8. Phủ cacao: Rây một lớp bột cacao nguyên chất mỏng và đều lên trên bề mặt tiramisu.\nBước 9: 9. Làm lạnh và thưởng thức:Đậy kín và để tiramisu trong tủ lạnh ít nhất 4–6 giờ, tốt nhất là qua đêm. Khi thưởng thức, cắt thành từng miếng và dùng lạnh.','Dessert',4,'Tiramisu truyền thống kiểu Ý với lớp bánh ladyfinger thấm đẫm cà phê espresso, xen kẽ cùng kem mascarpone béo mịn và phủ một lớp bột cacao đắng nhẹ.','Pha cà phê → đánh kem mascarpone → nhúng bánh ladyfinger → xếp lớp bánh và kem → phủ cacao → làm lạnh','recipe_1790876310_591.jpg','https://www.youtube.com/watch?v=RMEsbHHSJFQ',8,'2026-09-23 00:15:04'),(142,'Bánh Flan Caramen Nước Cốt Dừa',35,'Bước 1: Thắng 60 g đường với chút nước đến màu cánh gián, tráng đều đáy khuôn bánh.\nBước 2: Đun ấm hỗn hợp sữa tươi, nước cốt dừa và sữa đặc (không để sôi). Đánh tan trứng nhẹ tay rồi từ từ rót sữa ấm vào khuấy đều, lọc qua rây cho mịn.\nBước 3: Rót hỗn hợp vào khuôn caramen, hấp lửa nhỏ 25–30 phút (che mặt khuôn bằng giấy bạc để tránh rỗ bánh), sau đó để lạnh trước khi dùng.','Dessert',4,'Bánh flan trứng sữa mềm mịn sốt caramen đắng nhẹ.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/1200x/d2/4d/4c/d24d4cc1db7722a8bcda9eb402f5d2ac.jpg','',10,'2026-09-23 00:15:04'),(143,'Panna Cotta Sốt Dâu Tây',25,'Bước 1: Nấu phần kem sữa: Ngâm gelatin vào nước lạnh cho mềm/nở. Cho whipping cream, sữa tươi và đường vào nồi đun lửa nhỏ cho ấm (không để sôi), tắt bếp rồi thả gelatin đã vắt ráo vào khuấy tan. Rót ra ly/hũ, để nguội bớt rồi cho vào ngăn mát tủ lạnh 3–4 tiếng cho đông hoàn toàn.\nBước 2: Làm sốt dâu: Dâu tây cắt nhỏ, sên cùng đường và nước cốt chanh trên lửa nhỏ đến khi dâu mềm nhừ và sệt lại; để nguội hoàn toàn.\nBước 3: Rưới lớp sốt dâu tây lên mặt ly panna cotta đã đông và thưởng thức lạnh.','Dessert',4,'Kem sữa dẻo mềm rưới sốt dâu tây chua ngọt.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/736x/9a/1d/02/9a1d02278749012d6fb8bb5cabacf561.jpg','',10,'2026-09-23 00:15:04'),(144,'Chè Khúc Bạch Hạnh Nhân',30,'Bước 1: Bước 1: Ngâm nở Gelatin\r\nNgâm bột/lá gelatin vào 50ml nước lạnh khoảng 10–15 phút cho nở mềm.\nBước 2: Bước 2: Làm khúc bạch hạnh nhân\r\nCho sữa tươi, whipping cream và đường vào nồi, đun lửa nhỏ, khuấy nhẹ tay cho đường tan hết. \r\nChỉ đun đến khi hỗn hợp ấm khoảng 60°C–70°C (xung quanh mép nồi lăn tăn nhẹ), không đun sôi để tránh làm biến chất whipping cream.\r\nCho gelatin đã ngâm nở vào nồi sữa ấm, khuấy tan hoàn toàn.Tắt bếp, thêm 1/4 thìa cà phê tinh dầu hạnh nhân vào khuấy đều.\r\nLọc hỗn hợp qua rây vào khuôn để mặt khúc bạch được mịn phẳng (hớt sạch bọt khí nếu có).\r\nĐể nguội rồi cho vào ngăn mát tủ lạnh từ 4–5 tiếng cho đến khi đông hoàn toàn.\nBước 3: Bước 3: Nấu nước đường\r\nCho 500ml nước, đường phèn và lá dứa vào nồi, đun sôi cho đường tan hết.\r\n\r\nNêm độ ngọt vừa thanh dịu. Tắt bếp, vớt lá dứa ra và để nước đường thật nguội (hoặc cất ngăn mát tủ lạnh).\nBước 4: Bước 4: Rang hạnh nhân & Chuẩn bị topping\r\nRang hạnh nhân lát trên chảo ở lửa nhỏ đến khi vàng giòn và có mùi thơm.\r\n\r\nNhãn hoặc vải bóc vỏ, bỏ hạt. Có thể ngâm vào nước đường đã nguội để nhãn ngấm vị ngọt thanh.\nBước 5: Bước 5: Hoàn thiện và thưởng thức\r\nDùng dao có lưỡi sóng (hoặc dao thường) cắt khúc bạch thành các viên vuông vừa ăn.\r\n\r\nCho khúc bạch, nhãn/vải vào bát.\r\n\r\nMúc nước đường mát lạnh chế vào, rắc hạnh nhân lát rang giòn lên trên cùng (thêm đá viên nếu muốn ăn lạnh sâu).','Dessert',4,'Khúc bạch phô mai dẻo bùi nhãn tươi hạnh nhân lát.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790864912_720.webp','',2,'2026-09-23 00:15:04'),(145,'Bánh Crepe Sầu Riêng Ngàn Lớp',60,'Bước 1: Làm bột crepe: Trộn bột mì, trứng, sữa, đường và bơ tan chảy thành hỗn hợp bột mịn, sau đó lọc qua rây.\nBước 2: Tráng bánh: Làm nóng chảo, đổ một lớp bột mỏng và tráng đều hai mặt, thực hiện cho đến khi hết bột.\nBước 3: Làm nhân kem sầu riêng: Đánh whipping cream với đường bột đến khi bông mềm, sau đó trộn nhẹ với thịt sầu riêng.\nBước 4: Xếp bánh: Đặt một lớp crepe, phết một lớp kem sầu riêng mỏng rồi tiếp tục xếp xen kẽ đến khi hết nguyên liệu.\nBước 5: Làm lạnh: Đặt bánh vào tủ lạnh khoảng 2–3 giờ để các lớp bánh ổn định và dễ cắt.\nBước 6: Thưởng thức: Lấy bánh ra, cắt thành từng miếng và thưởng thức khi bánh còn mát.','Dessert',4,'Bánh crepe sầu riêng ngàn lớp mềm mỏng, xen kẽ lớp kem béo mịn và sầu riêng thơm ngọt, tạo nên hương vị hấp dẫn và tan nhẹ trong miệng.','Chuẩn bị nguyên liệu → Làm bột crepe → Tráng bánh → Làm nhân kem sầu riêng → Xếp bánh thành nhiều lớp → Làm lạnh → Thưởng thức','recipe_1790866842_966.jpg','https://www.youtube.com/watch?v=Y2h7W6SWfdM',12,'2026-09-23 00:15:04'),(146,'Bánh Phô Mai Nướng Basque',45,'Bước 1: Chuẩn bị nguyên liệu: Làm mềm cream cheese, cân và chuẩn bị đầy đủ các nguyên liệu.\nBước 2: Trộn hỗn hợp: Đánh cream cheese với đường, sau đó lần lượt thêm trứng, whipping cream và bột mì, trộn đều.\nBước 3: Đổ khuôn: Lót giấy nến vào khuôn rồi đổ hỗn hợp phô mai vào khuôn.\nBước 4: Nướng bánh: Làm nóng lò ở 220°C, nướng bánh khoảng 40–45 phút đến khi mặt bánh cháy xém vàng nâu.\nBước 5: Làm nguội: Lấy bánh ra, để nguội hoàn toàn rồi bảo quản lạnh.\nBước 6: Thưởng thức: Cắt bánh thành từng miếng và thưởng thức khi bánh đã mát.','Dessert',4,'Bánh phô mai mềm mịn, béo ngậy với lớp mặt cháy xém đặc trưng, mang hương vị thơm ngon, đậm đà và tan nhẹ trong miệng.','Chuẩn bị nguyên liệu → Trộn hỗn hợp phô mai → Đổ khuôn → Nướng bánh → Để nguội → Thưởng thức 🍰🧀','recipe_1790866409_985.jpg','https://www.youtube.com/watch?v=v1tmgvYHALo',12,'2026-09-23 00:15:04'),(147,'Bánh Mochi Nhật Bản Nhân Trà Xanh',35,'Bước 1: Khuấy tan bột nếp, matcha, đường và sữa tươi, lọc qua rây rồi bọc màng thực phẩm hấp chín 15–20 phút.\nBước 2: Thêm bơ vào khối bột nóng dẻo, nhồi/kéo cho mịn dai rồi chia viên nhỏ.\nBước 3: Cán dẹt vỏ bánh (dùng bột áo chống dính), cho nhân kem trà xanh vào giữa, túm kín mép bánh lại và bảo quản mát trước khi ăn.','Dessert',4,'Bánh bột nếp dẻo dai nhân kem matcha mát lạnh.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/736x/44/fd/11/44fd11be50485aadcf67c4fd9bf6c94f.jpg','',11,'2026-09-23 00:15:04'),(148,'Chè Xoài Bột Báng Hong Kong',20,'Bước 1: Xoài gọt vỏ, một phần cắt hạt lựu để trang trí, phần còn lại cắt nhỏ để xay. Bưởi tách thành các tép nhỏ.\nBước 2: Đun sôi một nồi nước, cho bột báng vào luộc khoảng 10–15 phút đến khi phần lớn hạt chuyển trong. Tắt bếp, đậy nắp thêm vài phút rồi vớt ra xả nước lạnh.\nBước 3: Cho xoài vào máy xay cùng sữa tươi và đường, xay đến khi hỗn hợp mịn. Điều chỉnh lượng đường tùy độ ngọt của xoài.\nBước 4: Trộn xoài xay với nước cốt dừa, sau đó thêm bột báng đã để ráo. Khuấy nhẹ để bột báng phân bố đều.\nBước 5: Múc chè ra ly hoặc bát, thêm xoài hạt lựu và tép bưởi lên trên. Làm lạnh trước khi thưởng thức để món ăn đạt độ mát và thơm ngon.','Dessert',4,'Chè xoài bột báng Hong Kong là món tráng miệng lạnh có vị xoài chín thơm ngọt, kết hợp với bột báng dai mềm và nước cốt dừa béo nhẹ. Món ăn có màu vàng đẹp mắt và vị thanh mát.','Sơ chế xoài → Luộc bột báng → Xay xoài → Trộn hỗn hợp → Làm lạnh & thưởng thức','recipe_1790855280_185.jpg','https://www.youtube.com/results?search_query=Ch%C3%A8+Xo%C3%A0i+B%E1%BB%99t+B%C3%A1ng+Hong+Kong',5,'2026-09-23 00:15:04'),(149,'Bánh Su Kem Vỏ Giòn Craquelin',45,'Bước 1: Làm lớp Craquelin: Trộn bơ mềm, đường nâu và bột mì thành khối bột, cán mỏng rồi để lạnh và cắt thành những miếng tròn vừa kích thước bánh\nBước 2: Làm bột vỏ su: Đun nước, sữa, bơ và muối đến khi sôi nhẹ, cho bột mì vào khuấy nhanh đến khi tạo thành khối bột mịn.\nBước 3: Tạo hình bánh: Để bột nguội bớt, lần lượt cho trứng vào trộn đều rồi cho bột vào túi bắt kem và tạo những viên bánh tròn trên khay.\nBước 4: Đặt Craquelin: Đặt từng miếng Craquelin lên trên mặt mỗi viên bột su.\nBước 5: Nướng bánh: Làm nóng lò ở 180°C, nướng khoảng 30–35 phút đến khi bánh phồng và vỏ vàng giòn.\nBước 6: Bơm nhân kem: Đánh whipping cream với đường bột và vani đến khi bông mịn, sau đó bơm kem vào bên trong bánh.\nBước 7: Thưởng thức: Để bánh nguội hoàn toàn rồi thưởng thức khi lớp vỏ còn giòn và nhân kem mát lạnh.','Dessert',4,'Bánh su kem vỏ giòn Craquelin có lớp vỏ ngoài giòn nhẹ, thơm bơ, bên trong mềm rỗng và nhân kem béo mịn, ngọt dịu.','Làm lớp Craquelin → Làm bột vỏ su → Tạo hình bánh → Đặt Craquelin → Nướng bánh → Bơm nhân kem → Thưởng thức','recipe_1790870399_279.jpg','https://www.youtube.com/results?search_query=B%C3%A1nh+su+kem+v%E1%BB%8F+gi%C3%B2n+Craquelin+',13,'2026-09-23 00:15:04'),(150,'Bánh Brownie Socola Hạnh Nhân',35,'Bước 1: Đun cách thủy cho tan chảy socola đen và bơ lạt, để nguội bớt.\nBước 2: Đánh tan trứng với đường, đổ hỗn hợp socola bơ vào khuấy đều; rây bột mì và bột cacao vào trộn nhẹ tay cho mịn.\nBước 3: Đổ bột vào khuôn lót giấy nến, rải đều hạnh nhân lên mặt bánh, nướng ở 175°C trong 20–25 phút rồi để nguội trước khi cắt.','Dessert',4,'Bánh socola đậm đặc hạnh nhân thơm bùi.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/1200x/7c/56/12/7c5612a139e38c2b09a8b0622d051749.jpg','',11,'2026-09-23 00:15:04'),(151,'Trà Sữa Trân Châu Đường Đen',30,'Bước 1: 1. Pha trà: Cho 10g trà đen vào 300ml nước nóng khoảng 90–95°C, ủ trong 5–7 phút rồi lọc bỏ bã trà và để trà nguội bớt.\nBước 2: 2. Nấu trân châu: Đun sôi một nồi nước, cho trân châu đen vào luộc theo hướng dẫn trên bao bì, thường khoảng 20–30 phút. Khi trân châu chín, vớt ra ngâm với nước lạnh rồi để ráo.\nBước 3: 3. Làm sốt đường đen: Cho 50g đường nâu và 30ml nước vào nồi, đun ở lửa nhỏ đến khi đường tan và hỗn hợp hơi sánh lại. Cho trân châu vào đảo đều để trân châu được phủ một lớp đường đen.\nBước 4: 4. Pha trà sữa: Cho trà đã pha vào bình, thêm sữa tươi và sữa đặc rồi khuấy đều. Có thể điều chỉnh lượng sữa đặc tùy theo độ ngọt mong muốn.\nBước 5: 5. Chuẩn bị ly: Dùng thìa múc trân châu đường đen cho vào đáy ly, sau đó nghiêng ly và xoay nhẹ để phần đường đen bám thành ly tạo hiệu ứng đẹp mắt.\nBước 6: 6. Thêm trà sữa: Cho đá viên vào ly rồi từ từ rót trà sữa vào đến gần đầy ly.\nBước 7: 7. Hoàn thành và thưởng thức: Thêm một ít trân châu đường đen lên trên, khuấy đều trước khi uống để trà sữa hòa quyện với phần đường đen và thưởng thức lạnh.','Drinks',5,'Trà sữa thơm béo kết hợp với trân châu dai mềm phủ đường đen caramel đậm đà, tạo nên thức uống ngọt ngào, thơm mùi trà và hấp dẫn.','Pha trà → Nấu trân châu → Làm sốt đường đen → Pha trà sữa → Kết hợp các nguyên liệu → Thêm đá → Trang trí và thưởng thức.','recipe_1790952519_868.jpg','',9,'2026-09-23 00:15:04'),(152,'Nước Ép Dưa Hấu Bạc Hà',5,'Bước 1: Rửa sạch dưa hấu, gọt vỏ, bỏ hạt và cắt thành miếng nhỏ. Lá bạc hà rửa sạch, để ráo.\nBước 2: Cho dưa hấu đã sơ chế vào máy ép và ép lấy phần nước.\nBước 3: Cho vài lá bạc hà vào nước ép dưa hấu, vò nhẹ để tạo hương thơm và vị the.\nBước 4: Khuấy nhẹ nước ép để dưa hấu và bạc hà hòa quyện. Có thể thêm đường và đá tùy khẩu vị.\nBước 5: Rót nước ép ra ly, trang trí bằng vài lá bạc hà và thưởng thức khi còn mát lạnh.','Drinks',5,'Dưa hấu ngọt mát hòa quyện cùng bạc hà the nhẹ, tạo nên thức uống tươi mát, sảng khoái và giải nhiệt, phù hợp cho những ngày nóng bức.','Sơ chế dưa hấu, bạc hà → Ép lấy nước → Thêm bạc hà → Khuấy đều → Thưởng thức🍉🌿','recipe_1790865790_428.jpg','https://www.youtube.com/watch?v=xQBSQ1tYnks',12,'2026-09-23 00:15:04'),(154,'Trà Vải Hoa Hồng Mát Lạnh',15,'Bước 1: 1. Pha trà: Cho 5g trà đen vào 250ml nước nóng khoảng 90–95°C, ngâm trong 3–5 phút rồi lọc bỏ bã trà và để trà nguội.\nBước 2: 2. Chuẩn bị vải: Nếu dùng vải tươi, bóc vỏ, bỏ hạt và giữ lại phần thịt vải. Nếu dùng vải ngâm, vớt vải ra để ráo và giữ lại một ít nước vải.\nBước 3: 3. Chuẩn bị siro hoa hồng: Cho siro hoa hồng, đường và 50ml nước lọc vào ly, khuấy đều cho đường tan hoàn toàn.\nBước 4: 4. Kết hợp nguyên liệu: Cho trà đã nguội vào bình hoặc ly lớn, thêm siro hoa hồng, nước cốt chanh và một ít nước vải. Khuấy đều và nếm lại để điều chỉnh độ ngọt, chua.\nBước 5: 5. Thêm vải và đá: Cho thịt vải vào ly, thêm đá viên gần đầy ly rồi rót hỗn hợp trà hoa hồng vào.\nBước 6: 6. Trang trí: Đặt một vài quả vải và cánh hoa hồng ăn được lên trên để tạo điểm nhấn.\nBước 7: 7. Thưởng thức: Khuấy nhẹ trước khi uống và thưởng thức ngay khi trà còn mát lạnh để cảm nhận vị trà thanh nhẹ, vải ngọt thơm và hương hoa hồng dịu dàng','Drinks',5,'Thức uống thanh mát kết hợp vị trà thơm nhẹ, vải ngọt mọng nước và hương hoa hồng dịu dàng, dùng cùng đá lạnh tạo nên một ly trà giải khát thơm ngon và dễ uống.','Pha trà → Chuẩn bị vải → Làm siro hoa hồng → Kết hợp trà và nguyên liệu → Thêm đá → Trang trí và thưởng thức.','recipe_1790952334_440.jpg','',9,'2026-09-23 00:15:04'),(155,'Matcha Latte Đá Xay',15,'Bước 1: Khuấy đều bột Matcha với 30ml nước ấm (khoảng 70–80°C) cho đến khi bột tan hoàn toàn.\nBước 2: Cho nước matcha đã hòa tan, sữa tươi, sữa đặc, sữa béo, siro đường, bột frappe và đá viên vào máy xay. Xay ở tốc độ cao trong khoảng 25–30 giây cho đến khi hỗn hợp mịn đều.\nBước 3: Rót phần đá xay ra ly, xịt kem tươi lên trên và rắc nhẹ một lớp bột matcha mỏng trang trí.','Drinks',5,'Tựa như một bản giao hưởng dịu mát giữa ngày hè, Matcha Latte đá xay là nét chấm phá thanh tao kết hợp giữa tinh hoa trà đạo Nhật Bản và sự ngậy béo phương Tây.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790868875_147.jpg','',3,'2026-09-23 00:15:04'),(156,'Nước Chanh Leo Tuyết Hạt Chia',15,'Bước 1: Cho hạt chia vào 100 ml nước lọc, khuấy đều và để khoảng 10–15 phút cho hạt nở hoàn toàn.\nBước 2: Cắt đôi chanh leo, lấy phần ruột cho vào bình. Thêm đường và khoảng 300 ml nước lọc, khuấy đến khi đường tan. Có thể lọc bớt hạt nếu muốn thức uống mịn hơn.\nBước 3: Cho đá viên vào máy xay, xay đến khi đá đạt dạng vụn mịn như tuyết. Tránh xay quá lâu khiến đá bị tan nhiều.\nBước 4: Cho hạt chia đã nở vào nước chanh leo, khuấy đều. Điều chỉnh độ chua ngọt bằng chanh hoặc đường tùy khẩu vị.\nBước 5: Cho đá tuyết vào ly, rót nước chanh leo lên trên. Trang trí bằng một lát chanh hoặc nửa quả chanh leo và dùng ngay.','Drinks',5,'Nước chanh leo tuyết hạt chia là thức uống mát lạnh với vị chua dịu, thơm đặc trưng của chanh leo và chút giòn nhẹ từ hạt chia. Phần đá xay mịn tạo cảm giác như tuyết, thích hợp dùng giải nhiệt.','Ngâm hạt chia → Pha chanh leo → Xay đá tuyết → Kết hợp → Trang trí & thưởng thức','recipe_1790855070_951.jpg','https://www.youtube.com/results?search_query=N%C6%B0%E1%BB%9Bc+Chanh+Leo+Tuy%E1%BA%BFt+H%E1%BA%A1t+Chia',5,'2026-09-23 00:15:04'),(160,'Mojito Dâu Tây Soda Mát Lạnh',10,'Bước 1: Dầm nguyên liệu: Cho dâu tây cắt lát, chanh, đường và lá bạc hà vào ly, dùng chày nhỏ dầm nhẹ để tiết nước và tinh dầu thơm.\nBước 2: Thêm đá: Cho đá viên vào đầy ly.\nBước 3: Rót soda: Rót nước soda lên trên, khuấy đều rồi trang trí thêm ngọn bạc hà là hoàn thành.','Drinks',5,'Soda chanh dâu tây lá bạc hà the mát mùa hè.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://i.pinimg.com/736x/ea/f0/bc/eaf0bc7739a8c8a9e73b293b74739d4e.jpg','',10,'2026-09-23 00:15:04'),(162,'Phở Bò Tái Nạm (Việt Nam)',120,'Bước 1: Sơ chế & hầm xương:\r\n\r\nXương ống rửa sạch, chần qua nước sôi 5 phút rồi rửa lại thật sạch.\r\n\r\nCho xương và miếng thịt nạm bò vào nồi lớn với khoảng 3.5–4 lít nước, nêm 1 thìa canh muối. Đun sôi rồi hạ nhỏ lửa hầm liu riu, hớt bọt liên tục.\r\n\r\nThịt nạm hầm khoảng 45–60 phút cho mềm thì vớt ra ngâm ngay vào tô nước đá, sau đó thái lát mỏng. Xương tiếp tục hầm từ 2–3 tiếng.\nBước 2: Nướng gia vị & nấu nước dùng:\r\n\r\nNướng cháy xém vỏ hành khô, gừng, hành tây. Rửa sạch lớp cháy.\r\n\r\nRang thơm hoa hồi, quế, thảo quả, đinh hương, hạt ngò rồi cho vào túi vải buộc chặt.\r\n\r\nCho túi gia vị, gừng, hành nướng vào nồi nước hầm xương. Nêm nước mắm, đường phèn và hạt nêm sao cho nước dùng ngọt thanh đậm đà vừa ăn.\nBước 3: Thành phẩm:\r\n\r\nTrụng bánh phở qua nước sôi rồi cho vào tô.\r\n\r\nXếp thịt nạm thái mỏng, thịt thăn băm nhẹ/thái mỏng (làm tái) lên mặt. Rắc hành lá, hành tây thái mỏng.\r\n\r\nMúc nước dùng đang sôi bùng chế trực tiếp lên tô để làm chín thịt tái. Thưởng thức nóng kèm chanh, ớt, rau thơm.','Vietnamese',6,'Món quốc hồn quốc túy thanh lành với bánh phở mềm, thịt bò ngọt ngậy quyện trong nước dùng ninh xương đậm đà, nức mũi hương hoa hồi, quế và thảo quả.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790866180_789.png','',2,'2026-10-01 21:49:40'),(163,'Tom Yum Goong',45,'Bước 1: Nấu nước dùng tôm:\r\n\r\nĐun nóng chút dầu ăn, cho đầu tôm và tỏi băm vào xào săn cho ra màu cam thơm rồi đổ 800ml nước vào đun sôi 10 phút.\r\n\r\nLọc bỏ phần đầu tôm, giữ lại phần nước dùng trong.\nBước 2: Nấu canh Tom Yum:\r\n\r\nCho sả, riềng, lá chanh và ớt hiểm vào nồi nước dùng đun sôi 5 phút cho tiết ra hương thơm.\r\n\r\nThêm sốt Tom Yum, nấm rơm cắt đôi và tôm tươi vào đun 3–4 phút cho tôm chín tới.\r\n\r\nHạ nhỏ lửa, đổ nước cốt dừa/sữa tươi vào khuấy nhẹ.\nBước 3: Hoàn thiện:\r\n\r\nTắt bếp rồi mới cho nước mắm, đường và nước cốt chanh vào (không đun nước cốt chanh trên bếp vì sẽ bị đắng).\r\n\r\nMúc ra bát, rắc ngò rí tươi lên trên và dùng nóng.','Chinese',3,'Món canh tôm chua cay bùng nổ vị giác, dung hòa hoàn hảo giữa vị chua thanh của chanh, cay nồng của ớt, thơm dịu từ sả, lá chanh và béo nhẹ của nước cốt dừa.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790866382_383.jpg','',2,'2026-10-01 21:53:02'),(164,'Sushi Roll / Maki Cá Hồi Bơ',30,'Bước 1: Nấu & trộn cơm sushi:\r\n\r\nVo sạch gạo, nấu cơm chín dẻo.\r\n\r\nKhi cơm còn nóng, xới ra tô rộng, rưới từ từ chén nước giấm đường vào, dùng muôi gỗ đảo nhẹ tay theo chiều ngang. Đậy khăn ẩm để cơm nguội bớt.\nBước 2: Cuộn sushi:\r\n\r\nĐặt mành cuốn sushi (mành tre) lên bàn, lót một lớp màng bọc thực phẩm.\r\n\r\nĐặt lá rong biển lên mành (mặt nhám ngửa lên trên).\r\n\r\nThấm nhẹ nước vào tay, lấy một lượng cơm vừa đủ trải đều lên lá rong biển (chừa lại khoảng 2cm ở mép trên).\r\n\r\nXếp cá hồi, bơ, dưa leo thành hàng ngang ở giữa lớp cơm.\nBước 3: Cắt & thưởng thức:\r\n\r\nNhẹ nhàng cuộn tròn mành tre lại, vừa cuộn vừa nắn nhẹ tay cho cuộn sushi chặt và tròn đều.\r\n\r\nDùng dao thật sắc thấm chút nước lau sạch lưỡi dao, cắt cuộn sushi thành từng miếng dày khoảng 1.5–2cm.\r\n\r\nThưởng thức cùng nước tương pha Wasabi','Chinese',3,'Món ăn tinh tế kết hợp hài hòa giữa hạt cơm trộn giấm dẻo mềm, hải sản tươi ngon và rau củ thanh mát, được cuộn tròn gọn gàng trong lá rong biển đậm vị biển cả.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790866953_604.jpg','',2,'2026-10-01 22:02:33'),(165,'Spaghetti Carbonara',30,'Bước 1: Luộc mì & Chuẩn bị sốt:\r\n\r\nĐun nồi nước sôi với chút muối, cho mì vào luộc thiếu 1–2 phút so với thời gian ghi trên bao bì (mì al dente). Giữ lại 1 cúp nước luộc mì.\r\n\r\nTrong tô nhỏ, đánh tan 3 lòng đỏ trứng gà cùng phô mai nạo và tiêu đen cho quyện đặc.\nBước 2: Rán thịt muối:\r\n\r\nCho thịt heo muối vào chảo đun lửa vừa (không cần thêm dầu ăn) cho thịt tiết mỡ và giòn vàng nhẹ. Tắt bếp.\nBước 3: Trộn Pasta (Kỹ thuật tạo sốt ngậy không dùng kem):\r\n\r\nCho mì vừa vớt vào chảo thịt (vẫn tắt bếp hoặc mở lửa thật nhỏ). Đổ vào khoảng 3–4 thìa canh nước luộc mì, đảo đều tay cho mỡ thịt và nước hòa quyện.\r\n\r\nĐợi chảo giảm nhiệt bớt (tránh làm trứng bị chín vón cục), đổ tô hỗn hợp trứng phô mai vào.\r\n\r\nĐảo liên tục và nhanh tay. Độ nóng còn lại của mì và chảo sẽ làm chín tái lòng đỏ trứng, kết hợp với phô mai và nước luộc mì tạo thành lớp sốt béo ngậy, sánh mịn bao phủ quanh sợi mì.\nBước 4: Thành phẩm: Gắp mì ra đĩa, rắc thêm phô mai nạo và tiêu đen lên trên.','Chinese',3,'Món mì Ý kinh điển béo ngậy chuẩn vị La Mã, nổi bật với lớp sốt sánh mịn làm từ lòng đỏ trứng gà và phô mai Pecorino, quyện cùng thịt heo muối giòn thơm và tiêu đen đậm đà.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790867540_689.jpg','',2,'2026-10-01 22:12:20'),(166,'Tacos Bò Nướng',30,'Bước 1: Xào thịt bò:\nBước 2: Ướp thịt bò với các loại bột gia vị (thì là, ớt, tỏi, muối, tiêu) trong 15 phút.\nBước 3: Đun nóng chảo với ít dầu ăn, cho thịt bò vào xào lửa lớn đến khi chín săn, xém cạnh thơm lừng.\nBước 4: Làm áp chảo vỏ bánh:\nBước 5: Cho vỏ bánh Tacos lên chảo khô áp chảo mỗi mặt khoảng 15–20 giây cho bánh ấm mềm và thơm.\nBước 6: Kẹp bánh Tacos:\nBước 7: Trải vỏ bánh ra đĩa, quết một lớp sốt bơ Guacamole lên đáy.\nBước 8: Cho thịt bò nướng vào giữa, tiếp đến là lớp xà lách thái sợi, sốt Salsa cà chua tươi mát.\nBước 9: Rắc phô mai nạo lên trên cùng, vắt thêm vài giọt chanh tươi và thưởng thức bằng tay.','Chinese',3,'Món ăn đường phố đầy màu sắc gồm vỏ bánh kẹp thịt bò nướng đậm đà, bùng nổ độ tươi mát nhờ sốt bơ Guacamole ngậy béo và sốt Salsa cà chua chua ngọt mọng nước.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790867702_761.jpg','',2,'2026-10-01 22:15:02'),(167,'Mứt dừa',60,'Bước 1: Thái cùi dừa thành những sợi dài hoặc cách nạo dừa làm mứt nhanh chóng là dùng dụng cụ nạo dừa cầm tay loại nạo dừa tròn có cán. Một mẹo dành cho bạn là bạn có thể cắt đôi hoặc cắt 1 phần trên đầu của cùi dừa, rồi dùng dao nạo theo vòng tròn là vừa đẹp mắt vừa nhanh.\r\nSau đó, bạn rửa thật sạch phần dừa vừa nạo và ngâm trong nước từ 12 – 14 tiếng nhằm lọai bỏ bớt dầu dừa. Vớt dừa ra và rửa thật kỹ cho hết hẳn mùi dầu dừa và để ráo.\nBước 2: Trộn đều phần dừa đã ráo nước với đường trong một nồi lớn, để cho đường tan và thấm vào sợi dừa (bạn có thể để qua đêm). Sợi dừa trắng trong là đạt.\r\nBật lửa to làm nóng chảo và khi chảo nóng thì cho cùi dừa vào rồi chỉnh lửa nhỏ lại, đảo nhẹ nhàng, đều tay (tránh làm sợi dừa đứt).\r\nCho sữa tươi và hương Vani vào.\r\nĐun nhỏ lửa cho đến khi sữa cạn và sợi dừa khô lại.\r\nVớt dừa ra, đợi cho nguội, phơi khô vài tiếng và cho vào hủ bảo quản.','Vietnamese',6,'Mứt dừa được xem là món ngon truyền thống trong những dịp lễ tết tại Việt Nam. Với hương vị thơm ngon, và cách làm mứt dừa đơn giản tại nhà thì đây là món ăn không thể thiếu của mỗi người dân Việt.\r\nMỗi năm con người lại sáng tạo ra thêm các loại mứt khác nhau nhằm góp phần làm phong phú mâm bánh kẹo ngày Tết. Nhưng trong đó, mứt dừa được mọi người yêu thích hơn cả. Một miếng mứt dừa vị ngọt ngọt, thơm thơm mùi dừa, lại giòn giòn với một tách trà nóng thì quả là tuyệt vời để tiếp khách ngày Tết. Hôm nay, Cet.edu.vn sẽ hướng dẫn bạn vài cách làm mứt dừa đơn giản tại nhà nhé!','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/01/m%E1%BB%A9t-d%E1%BB%ABa.jpg','',6,'2026-10-01 22:17:07'),(168,'Bún chả Hà Nội',120,'Bước 1: Bước 1: Sơ chế và chế biến nguyên liệu\r\nThịt ba chỉ thái thành những miếng vừa ăn. Thịt nạc vai đem thái mỏng và băm rối.\r\nHành tím, đầu hành, tỏi đập dập, băm nhuyễn rồi chia thành đôi, cho vào 2 phần thịt lợn.\nBước 2: Bước 2: Cách ướp thịt bún chả Hà Nội\r\n Tiếp tục cho vào mỗi phần thịt lợn một thìa canh nước hàng hoặc xì dầu đen, 1 thìa canh dầu hào, 1 thìa canh nước mắm, ½ thìa canh đường vàng, 1 muỗng canh nước tương, 1 muỗng canh mật ong và 1 chút tiêu xay.\r\n Trộn đều để cho các gia vị thấm sâu rồi cho vào tủ lạnh để trong khoảng 3 – 4 tiếng.\r\n Phần thịt vai băm, bạn làm thành hình tròn dẹt rồi đem nướng chín. Phần thịt ba thái miếng vừa ăn cũng vậy.\r\n Cà rốt, su hào gọt vỏ rồi rửa sạch, để ráo. Cà rốt thái tròn mỏng, su hào thái vuông mỏng. Sau đó, cho chung vào một âu và cùng 1 chút muối ăn rồi xóc đều.\r\n Ngâm cà rốt, su hào với muối trong khoảng 15 – 20 phút. Sau đó, đem rửa sạch rồi để ráo nước.\r\n Cho ½ muỗng canh tỏi băm, ½ muỗng canh giấm, 2 muỗng canh đường rồi đảo đều đến khi đường tan rồi cho thêm chút ớt băm vào.\r\nCác loại rau thơm bạn đem ngâm với nước muối loãng trong chừng 10 – 15 phút. Sau đó, đem rửa sạch rồi cho ra rổ để ráo nước.\nBước 3: Bước 3: Cách làm nước dùng bún chả\r\nChuẩn bị một bát nhỏ, múc 10 thìa canh nước lọc và cho 2 thìa canh đường, 2 thìa canh nước mắm vào khuấy đều cho đến khi đường tan.\r\nTiếp tục cho 3 muỗng canh nước cốt chanh, 1 muỗng canh đường, 1 muỗng cà phê tỏi băm, 1 muỗng cà phê ớt rồi khuấy đều lên.\nBước 4: Bước 4: Thưởng thức\r\nNhư vậy là bạn đã hoàn thành xong món bún chả rồi đấy. Bây giờ, bạn chỉ cần dọn rau thơm, bún, thịt, đồ chua và chả nướng cùng bát nước chấm ra là đã có thể mời mọi người thưởng thức được rồi.','Vietnamese',6,'Bún chả Hà Nội là món ăn đặc trưng của người miền Bắc. Sở hữu hương vị thơm ngon đặc trưng, bún chả hiện không chỉ được người Việt Nam ưa thích mà còn chinh phục được rất nhiều vị khách quốc tế. Hôm nay, hãy cùng vào bếp với  để học cách thực hiện món ăn ngon hấp dẫn này nhé. Chắc chắn gia đình và bạn bè của bạn khi được thưởng thức sẽ rất thích thú đấy!','Sơ chế -> tẩm ướp -> chế biến -> làm nước chấm -> thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/03/bun-cha-ha-noi.jpg','',7,'2026-10-01 22:32:33'),(169,'Súp cua (cho bé)',120,'Bước 1: Bước 1: Sơ chế nguyên liệu : Xương ức gà khi mua về, bạn cho vào rửa sạch với nước muỗi pha loãng hoặc vắt vào một ít nước cốt chanh để khử mùi tanh của gà. Sau đó, vớt ra và cho vào nấu nước dùng. Bạn cũng có thể nấu bằng xương heo nhưng đối với trẻ dưới 1 tuổi, xương gà sẽ dễ ăn hơn. Thịt gà sau khi mau về bạn cũng mang rửa sạch, rồi cho vào nồi nước dùng gà luộc chín, rồi vớt ra xé nhỏ, bỏ da để trẻ dễ ăn. Cua mua về bạn đem chà rửa sạch sẽ rồi cho vào nồi hấp chín. Tiếp đến, bỏ vỏ, bỏ mai rồi gỡ lấy thịt cua. Lưu ý, cẩn thẩn không để vỏ cua rơi vào thịt vì khiến trẻ bị hóc.\nBước 2: Nước dùng gà sau khi nấu từ 2 – 3 tiếng thì bạn vớt xương ra, lọc lấy nước dùng, lọc khoảng 2 lần để nước dùng thật trong và không có cặn. Sau đó, bạn hòa tan bột năng với nước rồi cho vào nồi nấu với lửa nhỏ. Tiếp theo, bạn đập trứng, hòa tan rồi cho vào nồi như bột năng rồi khuấy đều. Nấu đến khi hỗn hợp sền sệt thì bạn cho thịt cua và thịt gà xé nhỏ vào.\nBước 3: Nêm nếm món ăn với ít muối, đường cho vừa khẩu vị và không nên bỏ ớt hay tiêu vì không tốt cho hệ tiêu hóa của bé. Sau cùng, bạn cho hành lá và ngò rí cắt nhuyễn vào. Khi cho bé ăn bạn có thể cho thêm một muỗng dầu olive vào để làm đậm đà hương vị của súp cua.','Vietnamese',6,'Súp cua là món ăn khá quen thuộc và chứa nhiều đạm, canxi có ích cho sự phát triển chiều cao và thể trạng của trẻ. Tuy nhiên, để nấu được món súp cua chuẩn vị, giữ được dưỡng chất và phù hợp với trẻ dưới 1 tuổi, trẻ ăn dặm không phải việc đơn giản. Hãy cùng bắt tay vào thực hiện theo công thức món cháo ngon ngay sau đây thôi nào!','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/09/sup-cua.jpg','',6,'2026-10-01 22:33:24'),(170,'Đậu phụ Ma Bà',45,'Bước 1: Trụng sơ đậu phụ cắt khối vuông qua nước sôi có chút muối để tránh bị vỡ.\nBước 2: Phi thơm tỏi, gừng và tương Doubanjiang đến khi ra màu đỏ đẹp.\nBước 3: Cho thịt băm vào xào săn, thêm 150ml nước lọc hoặc nước dùng, nêm ít xì dầu và đường.\nBước 4: Cho đậu phụ vào đun nhỏ lửa khoảng 3-5 phút cho thấm gia vị.\nBước 5: Rưới nước bột năng từ từ để tạo độ sánh, rắc tiêu Tứ Xuyên và hành lá lên trên trước khi tắt bếp.','Chinese',3,'Món ăn kinh điển của vùng Tứ Xuyên với đậu phụ mềm mịn quyện cùng thịt băm trong sốt ớt đỏ cay nồng, thơm vị tiêu Tứ Xuyên gây tê nhẹ nơi đầu lưỡi.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790868948_168.jpg','',3,'2026-10-01 22:35:48'),(171,'Thịt kho Đông Pha',60,'Bước 1: Trụng thịt ba chỉ qua nước sôi, cắt thành các khối vuông khoảng 5x5 cm.\nBước 2: Xếp một lớp dày hành lá và gừng lát ở đáy nồi (dùng nồi đất càng tốt), đặt các khối thịt lên trên (mặt da hướng xuống).\nBước 3: Đổ rượu Thiệu Hưng, xì dầu, hắc xì dầu và đường phèn vào. Đậy nắp đun sôi rồi hạ lửa thật nhỏ kho trong 60 phút.\nBước 4: Lật mặt thịt (mặt da hướng lên), đun tiếp 30 phút.\nBước 5: Vớt thịt ra bát, chắt bớt mỡ trong nồi sốt rồi rưới sốt lên thịt. Mang hấp cách thủy thêm 30 phút để thịt mềm nhừ hoàn toàn.','Chinese',3,'Món thịt kho trứ danh của Hàng Châu sử dụng khối thịt ba chỉ vuông vức, kho chậm với rượu Thiệu Hưng và hắc xì dầu cho đến khi lớp mỡ mềm ngậy, tan ngay trong miệng mà không ngấy.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790869220_570.webp','',3,'2026-10-01 22:40:20'),(172,'Sủi cảo hấp/chần',60,'Bước 1: Cải thảo thái nhỏ, vắt bớt nước. Trộn đều cải thảo với thịt băm, gừng, xì dầu, dầu hàu, dầu mè và tiêu theo một chiều cho nhân dẻo quyện.\nBước 2: Cho một thìa nhân vào giữa vỏ bánh, miết chút nước quanh viền và xếp nếp gấp chặt mép bánh.\nBước 3: Đun sôi nồi nước lớn, thả sủi cảo vào luộc. Khi nước sôi bùng lên thì chêm thêm 1 bát nước lạnh (lặp lại 2-3 lần đến khi vỏ bánh trong và浮 nổi lên mặt nước).\nBước 4: Vớt ra ăn nóng kèm xì dầu pha chút giấm đen và sa tế.','Chinese',3,'Món ăn truyền thống không thể thiếu trong dịp Tết Trung Quốc, gồm lớp vỏ bột mì mỏng bọc lấy nhân thịt băm, hẹ hoặc cải thảo ngậy béo, thơm phức.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790869585_842.jpg','',3,'2026-10-01 22:46:25'),(173,'Bún Đậu Mắm Tôm',120,'Bước 1: Bước 1: Sơ chế nguyên liệu\r\nĐầu tiên bạn đem đậu phụ đem rửa qua với nước sạch để tránh bị bẩn. Vớt đậu ra đĩa để ráo nước, cắt thành từng miếng nhỏ vừa ăn.\nBước 2: Bước 2: Chiên đậu phụ\r\nCho dầu ăn vào chảo, đợi dầu ăn sôi rồi thả đậu phụ vào chiên với lửa liu riu. Ở công đoạn này, bạn cần phải rán giòn đậu thật khéo để có màu vàng ruộm, xốp và thơm thì ăn mới ngon. Khi rán đậu khuôn xong thì vớt đậu ra đĩa để cho ráo dầu.\nBước 3: Bước 3: Cách pha mắm tôm bún đậu ngon tuyệt\r\nBạn nên chọn loại mắm tôm có màu xanh, mịn, thoảng mùi thơm đặc trưng, đó là mắm ngon. Đầu tiên, cho mắm tôm vào bát nhỏ, sau đó cho tiếp chanh, rượu và đường, dùng đũa đảo đều lên cho tới khi sủi tăm là được.\r\nBắc 1 chảo dầu lên bếp, đun sôi, bỏ hành khô đã được băm nhuyễn vào rồi phi vàng lên.\r\nĐổ bát hỗn hợp mắm tôm, chanh, đường vào, đun nóng lên rồi bỏ ra bát. Ớt tươi bỏ hạt, thái lát cho vào bát.\r\nVậy là bạn đã có ngay bát mắm tôm thơm ngon với hương vị đặc trưng quyến rũ để ăn cùng món bún đậu rồi.\nBước 4: Bước 4: Trình bày và thưởng thức món bún đậu mắm tôm\r\nCông đoạn cuối cùng đó là xếp bún, đậu phụ, chả cốm và các loại rau sống, dưa leo lên đĩa là món ăn đã hoàn tất. Vậy là bạn đã có một món ăn rất tuyệt vời rồi.\r\nNgoài ra, bạn còn có thể luộc thịt chân giò hoặc làm thêm chả quế càng ngon hơn nhé.\r\nVới cách pha nước chấm bún đậu mắm tôm ngon vừa hoàn thành vừa rồi, CET tin chắc rằng cả nhà bạn sẽ có bữa ăn lạ miệng và thật hấp dẫn. Đặc biệt, với những gia đình nghiện món mắm tôm từ lâu thì công thức pha chế này vừa ngon chuẩn vị mà vừa đơn giản dễ làm. Chúc các bạn thành công và ngon miệng.','Vietnamese',6,'Bún đậu mắm tôm là một trong những món ăn ngon nổi tiếng của người Hà Nội, những ai đã từng đặt chân tới đây đều không thể bỏ qua hương vị đặc biệt của nó. Nếu để nói về yếu tố làm nên món ăn thú vị này thì ngoài phần thịt luộc, chả cốm, thì mắm tôm chấm ăn cùng là nhân tố quan trọng quyết định vị ngon của bún đậu. Chỉ đơn giản gồm bún tươi, đậu khuôn chiên giòn, chả cốm, thịt heo luộc, các loại rau thơm ăn kèm và dưa leo, mắm tôm, ấy vậy mà không kém phần tinh tế. Bởi thế, nó đã được liệt kê là một trong những món ăn ngon nhất của đất Việt.','Sơ chế -> tẩm ướp -> chế biến -> làm nước chấm -> thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2017/12/bun-dau-mam-tom-1.jpg','',7,'2026-10-01 22:48:53'),(174,'Vịt quay Bắc Kinh',60,'Bước 1: Rửa sạch vịt, ướp bên trong bụng vịt với muối, ngũ vị hương, rượu, gừng và hành lá.\nBước 2: Dội nước sôi lên toàn bộ da vịt cho da căng tròn.\nBước 3: Trộn mạch nha, giấm đỏ và chút nước ấm, quết đều lên toàn bộ da vịt. Treo vịt ở nơi khô ráo, thoáng gió ít nhất 5-8 tiếng (hoặc để quạt thổi) cho da thật khô.\nBước 4: Làm nóng lò nướng ở 200 độ C. Nướng vịt khoảng 20 phút, sau đó hạ xuống 170 độ C nướng thêm 40-50 phút đến khi da chuyển màu nâu đỏ giòn rụm.\nBước 5: Thái da và thịt thành lát mỏng, cuốn bánh tráng cùng đầu hành, dưa chuột và sốt Hoisin.','Chinese',3,'Món ăn hoàng gia Bắc Kinh nổi tiếng thế giới nhờ lớp da vịt mỏng, giòn rụm màu hổ phách, thịt bên trong mềm ngọt, thường ăn kèm bánh tráng mỏng, dưa chuột, đầu hành và sốt Hoisin.','Sơ chế -> Nấu chuẩn vị -> Thưởng thức','recipe_1790869787_807.jpg','',3,'2026-10-01 22:49:47'),(175,'Gà xào bắp ngọt',30,'Bước 1: Thái ức gà thành miếng vừa ăn, cho thêm chút muối và tiêu, cho bột mình để hình bên dưới, cho lượng vừa đủ sao cho gà áo đều bột.\nBước 2: Cho một chút dầu, rán hai mặt vàng đều.\nBước 3: Pha nước sốt: gồm những nguyên liêu mình để bên trên, pha đúng như vậy rồi bỏ tiêu vào nha mọi người. Nếu ăn vã thì cho 1 thìa nước mắm, nửa thìa tương ớt, nửa thìa đường thôi ạ. Xào ngô chín chín đã rồi mọi người đổ xốt vào.\nBước 4: Đổ gà đã rán, đảo đến khi quyện xốt lại thì bỏ hành băm nhỏ vào. Và sau đó thưởng thức','Vietnamese',6,'Món gà xào bắp ngọt với sự kết hợp hoàn hảo giữa thịt gà mềm thơm và những hạt bắp giòn ngọt tự nhiên. Món ăn có màu sắc bắt mắt, hương vị đậm đà, thơm phức mùi gia vị, rất thích hợp để đổi vị cho bữa cơm gia đình thêm phần ấm cúng và đưa cơm','Sơ chế & tẩm ướp -> Chiên gà giòn -> Xào ngô & pha sốt -> Hoàn thành & thưởng thức','https://img-global.cpcdn.com/recipes/acb84928879c919a/1280x1280sq80/photo.webp','',6,'2026-10-01 22:50:58'),(176,'Cá viên chiên mắm tỏi',45,'Bước 1: Bước 1: Sơ chế\r\nNhặt rau muống ( lưu ý đối với món cá viên chiên nước mắm, mình chỉ dùng phần cuống rau muống, không sử dụng ngọn rau muống)\r\nSau đó, chần sơ rau qua nước nóng\r\nBóc vỏ cá viên và mix các loại viên chiên bạn yêu thích\nBước 2: Bước 2: Cách làm xốt cá viên chiên nước mắm\r\nBạn cho vào bát 1.5 muỗng canh nước mắm, 3 muỗng canh đường, nửa muỗng canh tương ớt, nửa muỗng canh ớt bột, nửa muỗng cà phê bột ngọt và 2 muỗng canh nước lọc. Trộn đều hỗn hợp.\nBước 3: Bước 3: Chiên cá viên\r\nBắc chảo lên bếp, cho vào khoảng nửa bát con dầu ăn. Dầu nóng, bạn cho cá viên vào chiên. Vừa chiên vừa đảo để cá viên chín đều.\r\nChiên tới khi cá viên hơi phồng lên, bạn tắt bếp, vớt cá viên ra và để ráo dầu.\nBước 4: Bước 4: Cách làm cá viên chiên mắm tỏi\r\nBắc chảo lên bếp, cho vào 2 muỗng canh dầu ăn và cho tỏi băm vào phi thơm.\r\nTỏi vàng thơm, bạn cho rau muống vào và đảo nhanh tay.\r\nCho tiếp cá viên chiên vào, cho toàn bộ nước xốt đã pha vào. Đảo đều trong khoảng 30 giây để xốt áo đều nguyên liệu là có thể tắt bếp.\nBước 5: Bước 5: Thành phẩm và thưởng thức\r\nCá viên chiên mắm tỏi rau muống nóng hổi, thơm lừng. Các loại cá viên áo đều xốt mắm đậm đà, cay mặn ngọt hấp dẫn, rau muống xào chín tới vẫn giữ nguyên độ giòn, ăn thử một miếng đảm bảo sẽ gây nghiện.','Vietnamese',6,'Cá viên chiên nước mắm là món ăn vặt được nhiều bạn trẻ yêu thích. Những viên cá được chiên vàng thơm, giòn sần sật áo đều xốt nước mắm cay mặn ngọt vô cùng hấp dẫn, ăn một lần là mê. Để làm món cá viên chiên mắm này cũng rất đơn giản, cùng Bếp Trưởng Á Âu học ngay cách làm cá viên chiên nước mắm tại bài viết dưới đây nhé.','Sơ chế ->  chế biến -> thưởng thức','https://beptruong.edu.vn/wp-content/uploads/2024/12/cach-lam-ca-vien-chien-xot-mam-toi.jpg','',7,'2026-10-01 22:58:36'),(177,'Thịt Bò Xào Hành Tây',30,'Bước 1: Bước 1: Thịt bò rửa sạch, thái miếng mỏng vừa ăn. Ướp thịt với một nửa phần tỏi băm, gừng băm, 1 muỗng dầu hào, chút bột nêm và nước mắm trong khoảng 15 phút cho ngấm gia vị. Hành tây lột vỏ, bổ múi cau. Cần tây và cà rốt rửa sạch, thái khúc/thái lát vừa ăn.\nBước 2: Bước 2: Đun nóng chảo với một ít dầu ăn, phi thơm phần tỏi băm còn lại. Cho thịt bò vào xào trên lửa lớn đảo thật nhanh tay trong khoảng 2 phút cho thịt chín tới rồi trút ra đĩa riêng (tránh xào lâu thịt bị dai).\nBước 3: Bước 3: Dùng lại chảo đó, cho thêm một chút dầu ăn rồi lần lượt cho cà rốt, hành tây và cần tây vào đảo đều trên lửa lớn. Nêm chút bột canh, đường cho vừa miệng.\nBước 4: Bước 4: Khi rau củ vừa chín tới (vẫn giữ được độ giòn ngọt), trút toàn bộ đĩa thịt bò đã xào vào chảo, đảo đều tay khoảng 1 phút rồi tắt bếp. Rắc thêm chút hạt tiêu lên trên, múc ra đĩa và thưởng thức nóng.','Vietnamese',6,'Món thịt bò xào hành tây thơm ngon, đậm đà với từng miếng thịt bò mềm ngọt tự nhiên kết hợp cùng hành tây giòn giòn, thanh ngọt. Món ăn vừa nhanh gọn, dễ làm lại vô cùng đưa cơm, rất thích hợp cho những bữa cơm gia đình ấm cúng','Sơ chế nguyên liệu -> Ướp thịt bò -> Xào thịt bò chín tới -> Xào rau củ -> Hoàn thành món ăn','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTTA62seaZNG0K_LsXnghidJgs4bPhVi_hVI73lINBETA&s=10','',6,'2026-10-01 23:03:12'),(178,'Trứng gà nướng',20,'Bước 1: Bước 1: Sơ chế trứng gà\r\nTrứng gà sau khi mua về bạn rửa sạch, rồi đục một lỗ nhỏ trên đỉnh trứng. Khéo léo đục nhẹ nhàng để vỏ trứng không bị vỡ hoặc nứt. Cho vào trong trứng một chút mật ong, hạt tiêu, muối, bột rau câu và lắc nhẹ, cho đến khi thấy bọt trào ra từ trong lỗ thủng thì dừng lại.\r\nHoặc bạn có thể áp dụng phương pháp sau: Đục một lỗ nhỏ trên đầu trứng rồi dùng một chiếc xi lanh y tế mới tinh (loại chưa bóc vỏ vô trùng) tráng qua nước sôi cho đảm bảo. Dùng xi lanh hút hết lòng trứng ra một cái bát con. Nêm nếm gia vị và cho thêm bột rau câu Agar vào, dùng muỗng đánh đều lên sau đó lấy xilanh bơm ngược trở lại vào vỏ trứng. Bột rau câu sẽ giúp trứng nướng cứng, giòn và dai, không bị bở và tách nước.\nBước 2: Bước 2: Nướng trứng gà\r\nĐối với lò than ta để lửa cực nhỏ, nướng đến khi trứng chín đều và ngon (lửa to sẽ khiến trứng bị nổ). Đối với lò vi sóng ta cũng cho trứng vào lò và quay chín. Bạn có thể cho trứng vào hấp chín trước rồi mới nướng sau, sẽ giúp tiết kiệm thời gian hơn rất nhiều.\nBước 3: Bước 3: Pha nước chấm hột gà nướng\r\nChuẩn bị một bát nước mắm ngon, cho thêm vào ớt thái lát, gừng giã nhuyễn, đường, chanh rồi khuấy đều. Vậy là bạn đã có nước chấm hột gà nướng chuẩn vị Thái Lan.\r\nKhi trứng chín dọn ra ăn kèm với rau răm và nước chấm vừa pha.','Vietnamese',6,'Trứng gà là một nguyên liệu nấu ăn cực kì bổ dưỡng rất quen thuộc với người Việt Nam. Gần đây, trong các trào lưu món ngon đường phố có sự xuất hiện của món hột gà nướng độc đáo và thơm ngon. Trong bài viết này, Cet.edu.vn sẽ hướng dẫn cách làm hột gà nướng Việt Nam và cách làm hột gà nướng Thái Lan tại nhà để bạn có thêm vài công thức món ngon độc đáo từ trứng nhé.','Sơ chế ->  chế biến -> thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/11/hot-ga-nuong-thai-lan.jpg','',7,'2026-10-01 23:04:11'),(179,'Bánh chuối chiên',30,'Bước 1: Chuẩn bị bột làm bánh\r\nĐầu tiên, bạn cho bột gạo, bột năng, bột mì, bột nghệ và đường vào tô, thêm nước vào hỗn hợp bột rồi khuấy đều tay để bột không bị vón cục.\r\n\r\nSau đó, bạn lọc hỗn hợp bột này qua rây cho mịn, dùng màng thực phẩm bọc kín tô bột lại rồi ủ khoảng 45 – 50 phút ở nhiệt độ phòng.\nBước 2: Ép chuối\r\nChuối sau khi mua về bạn rửa sạch, cắt bỏ cuống, lột bỏ vỏ và phần xơ chuối.\r\nBạn sử dụng màng bọc thực phẩm quấn quanh tấm thớt hoặc dùng túi nhựa trải lên bề mặt để ép chuối.\r\nBạn dùng thêm một tấm nhựa trong hoặc thớt để ép chuối, thực hiện với lực nhẹ để nguyên liệu không bị nát, ép lần lượt cho đến khi hết số chuối đã chuẩn bị và xếp phần đều ra đĩa.\nBước 3: Chiên chuối\r\nCông đoạn chiên chuối cũng khá đơn giản, bạn cho một lượng dầu vừa đủ vào chảo đến khi dầu nóng già thì thực hiện chiên bánh.\r\nTiếp theo, bạn nhúng chuối đã ép vào hỗn hợp bột, gạt bớt phần bột dư rồi thả nhẹ nhàng vào chảo.\r\nNếu bạn thích ăn vỏ bột dày, được chiên giòn hãy đợi đến khi mặt bột se lại thì gắp chuối ra, nhúng vào tô bột một lần nữa và tiếp tục cho vào nồi chiên.\r\nBạn chiên chuối đến khi mặt ngoài có màu vàng nâu, bánh phồng lên thì hãy vớt ra để lên dĩa có giấy thấm dầu, như vậy khi ăn sẽ không bị ngán.','Vietnamese',6,'Bánh chuối chiên là món ăn vặt quen thuộc, thưởng thức chiếc bánh còn nóng ấm, có vị ngọt ngậy, thơm giòn đặc trưng vào những hôm tiết trời se lạnh thì còn gì bằng. Mời bạn đọc tham khảo một số cách làm bánh chuối chiên đơn giản sau đây, để trổ tài khéo tay nhé!','Sơ chế -> Chế biến -> Thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/09/cach-lam-banh-chuoi-chien.jpg','',7,'2026-10-01 23:08:41'),(180,'Trứng Ngâm Tương Hàn Quốc',120,'Bước 1: Bước 1: Sơ chế nguyên liệu\r\nTrứng gà sau khi mua về bạn rửa sạch từng quả, lưu ý nhẹ tay để tránh bị vỡ. Nếu trứng được bảo quản lạnh thì nên để bên ngoài một lúc rồi mới đem luộc.\r\n\r\nHành tây và hành lá rửa sạch, cắt nhỏ. Tỏi, hành tím cắt mỏng. Ớt có thể để nguyên trái, đập dập hoặc cắt lát tùy sở thích. Mè rửa sơ với nước sau đó đem rang vàng với lửa nhỏ.\nBước 2: Bước 2: Luộc trứng gà\r\nĐặt lên bếp một nồi nước, khi nước sôi thì hạ nhỏ lửa rồi lần lượt thả từng quả trứng gà vào luộc. Sau đó dùng đũa khuấy nhẹ theo chiều kim đồng hồ để khi chín, lòng đỏ nằm giữa lòng trắng, cắt đôi sẽ đẹp mắt hơn. Lưu ý thời gian luộc trứng lòng đào là khoảng 6-7 phút. Trứng chín thì bạn vớt ra và cho ngay vào một tô nước đá, sau đó bóc vỏ. Mẹo nhỏ giúp bạn bóc vỏ trứng dễ dàng là thêm chút giấm và muối vào nước khi luộc.\nBước 3: Bước 3: Nấu hỗn hợp nước ngâm\r\nCho nước tương, nước lọc cùng 2 muỗng canh đường, 1 muỗng canh rượu trắng vào nồi và khuấy đều, sau đó đun hỗn hợp đến khi sôi thì tắt bếp. Bạn nhớ nêm nếm lại vừa miệng. Đợi hỗn hợp nguội hoàn toàn thì cho hành tây, hành lá, hành tím, tỏi, ớt và mè rang vào trộn đều.\r\n\r\nXếp trứng vào hộp hoặc hũ thủy tinh rồi đổ hỗn hợp nước tương vào sao cho ngập trứng và đậy nắp kín. Sau khi ngâm khoảng 6-8 tiếng thì trứng ngấm gia vị và có thể thưởng thức.\nBước 4: Bước 4: Thành phẩm\r\nMón trứng ngâm tương sau khi hoàn thành thì bề ngoài trứng có màu nâu đẹp mắt, bên trong lòng trắng vừa chín, lòng đỏ dẻo sệt, còn nước tương thì vừa miệng, thơm ngon. Tóm lại, bạn sẽ cảm nhận được tất cả vị mặn, ngọt và cay nhẹ trong cùng một món ăn.\r\n\r\nTrứng ngâm tương có thể dùng với cơm trắng, bún, bánh mì hoặc mì gói. Để chống ngán và tăng thêm hương vị thì bạn nên ăn kèm với rau luộc hay đồ chua. Món ăn được bảo quản trong ngăn mát tủ lạnh khoảng 1 tuần.','Vietnamese',6,'Trứng ngâm tương là một trong những món banchan (ăn kèm) của xứ sở kim chi – Hàn Quốc. Tuy đơn giản với những quả trứng luộc lòng đào ngâm trong hỗn hợp nước tương với hành, ớt, hạt mè,… nhưng hương vị rất ngon khi ăn cùng cơm nóng. Món này không mất quá nhiều thời gian để làm mà lại có thể trữ ăn dần trong vài ngày nên thích hợp với những người bận rộn.','Sơ chế -> tẩm ướp -> chế biến -> thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2021/05/cach-lam-trung-ngam-tuong-1.jpg','',7,'2026-10-01 23:12:05'),(181,'Gà kho xả ớt',45,'Bước 1: Bước 1: Thịt gà rửa sạch với chút muối và gừng giã nhỏ để khử mùi hôi, chặt miếng vừa ăn rồi để ráo nước. Sả băm nhỏ một nửa, phần còn lại thái lát mỏng; ớt thái vạt; hành tỏi băm nhuyễn.\nBước 2: Bước 2: Ướp thịt gà với một nửa phần hành tỏi băm, sả băm, 2 thìa canh nước mắm, 1 thìa cà phê đường, chút hạt tiêu và bột ngọt, trộn đều và để ngấm gia vị trong khoảng 20 - 30 phút.\nBước 3: Bước 3: Đặt nồi lên bếp, cho 1 thìa canh đường vào thắng đến khi chuyển màu vàng cánh gián thì cho thêm chút dầu ăn, hành tỏi và sả thái lát còn lại vào phi thơm.\nBước 4: Bước 4: Trút toàn bộ thịt gà đã ướp vào xào săn trên lửa lớn cho thịt thấm màu và săn lại, sau đó thêm chút nước lọc xâm xấp mặt thịt, kho nhỏ lửa khoảng 20 phút cho đến khi nước sền sệt thì nêm nếm lại cho vừa miệng rồi tắt bếp.','Vietnamese',6,'Gà kho sả ớt đậm đà, thơm nức mũi mùi sả và cay nồng vị ớt, thịt gà săn chắc thấm vị, ăn kèm cơm trắng nóng hổi thì vô cùng tuyệt vời trong những ngày se lạnh.','Sơ chế nguyên liệu -> Ướp thịt gà -> Xào săn & kho gà -> Hoàn thành & thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/08/ga-kho-mien-nam.jpg','',6,'2026-10-01 23:12:33'),(182,'Gỏi cuốn và nước chấm ngon',60,'Bước 1: Bước 1: Sơ chế rau sống\nBước 2: Rau sống, rau thơm, hẹ… bạn đem rửa sạch, ngâm qua với nước muối, rửa sạch với nước và sau đó vớt ra rổ để ráo nước.\nBước 3: Bước 2: Chuẩn bị tôm\nBước 4: Tôm rửa sạch, ướp với 1/2 muỗng cafe muối, 1/2 muỗng canh rượu, 1 muỗng cafe đường để tôm đậm đà và không bị hôi, tanh.\nBước 5: Bắc nồi lên bếp, đậy nắp, bật lửa nấu cho tôm chuyển đỏ và đừng quên phải đảo đều.\nBước 6: Sau đó vớt tôm ra rổ để ráo rồi tiến hành lột vỏ, xẻ đôi tôm và bỏ chỉ lưng của tôm, sau đó xếp ra đĩa để chuẩn bị cho công đoạn chế biến món ngon tiếp theo.\nBước 7: Bước 3: Chuẩn bị thịt\nBước 8: Thịt ba chỉ bạn mua về đem cạo lông, rửa sạch, sau đó đun sôi nồi nước, thả vào 1 củ hành đập dập và cho thịt vào luộc khoảng 20 phút. Khi thịt chín, nhanh tay vớt ra và ngâm vào một bát nước lạnh để giúp thịt trắng và giòn ngon hơn. Thái thịt thành lát mỏng cho vào một chiếc đĩa riêng.\nBước 9: Bước 4: Cuốn gỏi cuốn\nBước 10: Sắp bánh tráng và các nguyên liệu ra bàn để chuẩn bị cuốn. Sau khi làm ướt bánh tráng, bạn lót rau lên trên và xếp bún, thịt, tôm, cùng với cọng hẹ, rau thơm trang trí rồi cuộn cho chắc tay là được. Tiếp tục lặp lại thao tác cho đến khi hết nguyên liệu thì thôi. Dùng kèm gỏi cuốn tôm thịt với tương, sau đó rắc thêm lạc và đồ chua nếu thích là có thể mời mọi người cùng thưởng thức.\nBước 11: Bước 5: Cách pha mắm nêm chấm gỏi cuốn\nBước 12: Tỏi bóc vỏ, ớt bỏ hạt. Giã nhuyễn tỏi và ớt, bằm nhuyễn 1/3 chỗ dứa (hoặc dùng máy xay sinh tố).\nBước 13: Trộn đều tỏi, ớt, dứa xay với mắm nêm đã chuẩn bị sẵn, thêm 2 – 3 thìa cà phê đường, sau đó vắt thêm vài giọt nước cốt chanh, nêm nếm lại cho vừa miệng.','Vietnamese',6,'“Gỏi cuốn” – món ăn Việt Nam từng được CNN bình chọn vào danh sách “50 món ăn ngon nhất thế giới” năm 2011 không quá phức tạp. Chỉ cần chuẩn bị đầy đủ các nguyên liệu và vài bước đơn giản là bạn có ngay món gỏi cuốn và nước chấm ngon tại nhà. Cùng Cet.edu.vn tìm hiểu cách làm gỏi cuốn tôm thịt, gỏi cuốn thịt heo và gỏi cuốn chay ngon trong bài sau đây.','Sơ chế -> tẩm ướp -> chế biến -> làm nước chấm -> thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/11/goi-cuon-tom-thit.jpg','',7,'2026-10-01 23:15:10'),(183,'Xôi chè',60,'Bước 1: Bước 1: Gạo nếp và đậu xanh vo sạch, ngâm nước riêng biệt khoảng 4 – 6 tiếng rồi vớt ra để ráo, xóc thêm chút muối. Đồ chín đậu xanh, đem nghiền nhuyễn rồi trộn một nửa vào gạo nếp đem đồ thành xôi vò tơi xốp.\nBước 2: Bước 2: Phần đậu xanh nghiền nhuyễn còn lại giữ làm nhân để nấu chè. Gừng cạo vỏ, thái sợi hoặc đập dập.\nBước 3: Bước 3: Đun sôi một lượng nước vừa đủ với đường cát và gừng tươi cho tan đều. Hòa tan bột sắn dây với chút nước rồi từ từ đổ vào nồi khuấy đều đến khi chè sánh lại, sau đó cho phần đậu xanh còn lại vào khuấy đều rồi tắt bếp.\nBước 4: Bước 4: Múc chè ra bát hoặc chén, đặt lên trên một phần xôi vò thơm phức, có thể ăn kèm nước cốt dừa tùy thích để tăng độ béo ngậy.','Vietnamese',6,'Xôi chè là món ăn truyền thống thanh ngọt, kết hợp hoàn hảo giữa từng hạt xôi vò tơi xốp, thơm mùi đậu xanh và phần chè đường cát ngọt dịu, ấm nồng vị gừng, mang đậm hương vị quê hương quen thuộc.','Sơ chế & nấu xôi vò -> Nấu chè đường gừng -> Kết hợp hoàn thiện -> Thưởng thức ấm','https://www.cet.edu.vn/wp-content/uploads/2019/01/xoi-che.jpg','',6,'2026-10-01 23:16:40'),(184,'Bánh giò',60,'Bước 1: Bước 1: Cách làm nhân bánh ngon đậm đà\r\nVới cách làm bánh ngon tại nhà không cần lá chuối, bạn cần chuẩn bị phần nhân bánh. Bạn có thể mua thịt về băm nhuyễn hoặc có thể mua thịt xay cho tiện, sau đó, bạn ướp thịt với 1 muỗng cà phê hạt nêm, ½ muỗng cà phê đường. 1 muỗng canh nước mắm và 1 muỗng cà phê tiêu xay.\r\nBạn bắc một chảo lên bếp, cho 2 muỗng dầu ăn vào, khi dầu nóng, bạn cho hành băm vào xào cho thơm, rồi cho thịt đã ướp vào xào cùng. Xào đến khi thịt tơi ra và gần chín bạn nêm nếm với 1 muỗng canh nước mắm, 1 muỗng cà phê tiêu.\r\nNấm mèo bạn đem ngâm với nước cho nở mềm, rồi vớt ra để ráo và băm nhuyễn. Sau đó, bạn cho nấm mèo vào xào cùng với thịt xay trong khoảng 5 phút rồi cho hành phi vào đảo đều rồi tắt bếp.\nBước 2: Bước 2: Cách làm bột (vỏ bánh)\r\nCông đoạn quan trọng trong cách làm bánh giò không cần lá chuối là làm vỏ bánh. Bạn cho bột gạo, bột bắp, ½ muỗng cà phê hạt nêm và nước vào nồi rồi dùng muỗng khuấy đều tay đến khi bột tan. Sau đó cho nồi lên bếp, vặn lửa nhỏ và liên tục khuấy bột đều tay.\r\nKhuấy bột đến khi bạn cảm thấy bột sền sệt và hơi nặng tay thì tắt bếp. Tuy tắt bếp, nhưng bạn vẫn khuấy cho bột mịn và không vón cục. Bạn nên thật cẩn thận ở thao tác này, vì nếu khuấy không đều, bột sẽ bị đóng cục và bánh giò sẽ không được ngon.\r\nĐể thay thế cho lá chuối, bạn chuẩn bị một vài khuôn hoặc chén. Tiếp đến, khi bột hoàn thành, bạn cho ít bột vào một nửa khuôn rồi cho thêm trứng cút và phần nhân vào giữa. Sau cùng, bạn cho tiếp một ít bột phủ lên phần nhân.\nBước 3: Bước 3: Hấp bánh\r\nBạn nấu nước đến khi sôi, thì cho khuôn bánh vào xửng hoặc lồng hấp rồi cho vào nồi hấp cách thủy trong khoảng 25 – 30 phút là được. Khi bánh chín, bạn cho bánh ra đĩa, trang trí với xà lách, dưa leo cùng một ít nước mắm tỏi ớt chua chua ngọt ngọt để ăn kèm. Bánh giò ngon nhất là ăn khi còn nóng đấy!','Vietnamese',6,'Bánh giò là món ăn truyền thống gắn liền với ký ức tuổi thơ của bao thế hệ học sinh, sinh viên. Cũng với những nguyên liệu dễ tìm như bánh bèo, bánh xèo, bánh đúc… nguyên liệu làm bánh giò khá dễ tìm và cách làm cũng rất đơn giản, không tốn nhiều thời gian. Vì thế, bạn có thể thực hiện tại nhà để làm bữa sáng cho cả gia đình. Nếu bạn gặp khó khăn trong việc tìm lá chuối gói bánh, hãy theo dõi và thực hiện theo cách làm bánh giò ngon nhất ngay sau đây.','Sơ chế -> Chế biến -> Thưởng thức','https://www.cet.edu.vn/wp-content/uploads/2018/08/banh-gio.jpg','',7,'2026-10-01 23:18:46'),(185,'Matcha latte',30,'Bước 1: Hòa tan bột matcha\r\nCho bột 3gr bột matcha cùng 30ml nước nóng có nhiệt độ khoảng 80 độ C vào ly và dùng muỗng khuấy tan.\nBước 2: Pha matcha với sữa\r\nCho vào bình lắc 40ml sữa đặc và 100ml sữa tươi không đường rồi dùng muỗng khuấy tan.\r\n\r\nTiếp đến bạn cho hết phần hỗn hợp matcha đã được hòa tan với nước nóng vào, đậy nắp và lắc khoảng 15 - 20 giây cho hỗn hợp hòa vào nhau.\nBước 3: Thành phẩm\r\nCho matcha latte ra ly cùng ít đá viên và thưởng thức ngay thôi nào.\r\n\r\nMùi thơm lừng của matcha, vị béo ngọt của sữa cùng với vài viên đá tạo cảm giác mát lạnh sẽ khiến bạn thích mê thức uống cực đơn giản này đấy nhé!','Drinks',5,'Những ngày nóng oi bức như thế này mà thưởng thức một ly matcha latte mát lạnh, thơm lừng thì còn gì thích bằng. Chẳng cần phải đi đâu xa, cùng vào bếp thử ngay công thức làm thức uống matcha lattengay dưới đây nhé!','Sơ chế -> Chế biến -> Thưởng thức','https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTIzBSL3X5BwZJV0WA3Rp_OGz89pOMVvE5BsQoOjfhDy-Hptv5ESTrDdDw&s=10','',7,'2026-10-01 23:22:08');
